INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C1','kor',4,2,'u1',2,'이 단원에서 배울 두 가지 — 작품 속 세계와 현실 세계를 비교하며 감상하기 · 서로 다른 글쓴이의 의견을 비교하며 읽기 — 둘 다 나란히 놓고 닮은 점과 다른 점을 따지는 일',ARRAY['[4국05-02][4국02-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C2','kor',4,2,'u1',2,'작품 속 세계와 현실 세계 — 작품에는 현실과 비슷한 부분과 상상해 꾸며 쓴 부분이 함께 있음 — 작품 속 세계는 현실과 똑같지도, 아주 동떨어지지도 않음',ARRAY['[4국05-02][4국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C3','kor',4,2,'u1',2,'꾸며 쓴 부분이 하는 일 — 꾸며 쓴 부분은 거짓말이 아니라 상상하는 재미를 주고 인물의 마음이나 글쓴이의 생각을 더 또렷하게 보여 주는 방법',ARRAY['[4국05-02][4국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C4','kor',4,2,'u1',2,'마음에 남는 장면은 사람마다 — 같은 작품을 읽어도 마음에 남는 장면과 생각은 사람마다 다를 수 있음 — 하나가 잘못 읽은 것이 아님',ARRAY['[4국05-02][4국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C5','kor',4,2,'u1',2,'인상 깊은 장면과 까닭 — 인상 깊은 장면을 말할 때는 작품 속 장면과 왜 그 장면인지 까닭을 함께 말함',ARRAY['[4국05-02][4국05-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C6','kor',4,2,'u1',2,'내 경험 떠올리기 — 내 경험을 떠올리며 읽으면 작품에서 현실과 닮은 부분과 다른 부분이 잘 보임',ARRAY['[4국05-02][4국05-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C7','kor',4,2,'u1',2,'작품과 현실 견주기 — 같은 대상(신호등·초록불·자동차)을 다룬 것끼리 작품에 나타난 모습과 현실의 모습을 나란히 놓고 견줌',ARRAY['[4국05-02][4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C8','kor',4,2,'u1',2,'작품 전체가 글쓴이가 만든 세계 — 말하거나 움직이는 사물만 꾸민 것이 아니라, 현실과 닮은 부분도 글쓴이가 전하려는 모습을 그리려고 골라 엮은 것 — 그렇다고 견줄 필요가 없는 것도 아님',ARRAY['[4국05-02][4국05-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C9','kor',4,2,'u1',2,'말하는 이가 바라는 모습 — 「뛰지 않아도 되는 길」·「느긋한 우리 동네」처럼 시 속 말을 근거로 말하는 이가 현실에 바라는 모습을 찾음',ARRAY['[4국05-02][4국05-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C10','kor',4,2,'u1',2,'바꾸어 쓰기 — 현실과 비교한 것을 바탕으로 내가 바라는 모습을 상상해 작품의 한 부분을 바꾸어 쓰고 바꾼 까닭을 말함',ARRAY['[4국05-02][4국05-05]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C11','kor',4,2,'u1',2,'작품과 현실을 비교하면 좋은 점 — 현실의 모습을 되돌아볼 수 있고, 현실과 다른 세계를 상상해 볼 수 있고, 익숙한 모습을 새로운 눈으로 볼 수 있음',ARRAY['[4국05-02][4국05-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C12','kor',4,2,'u1',4,'「골목 끝 빨간 우체통」 내용 — 처음 — 이사 온 은호가 말을 걸지 못함 · 가운데 — 이름만 적은 편지에 이름 없는 답장이 옴 · 끝 — 은호가 해린이에게 먼저 말을 걸고 둘이 마지막 편지를 넣음',ARRAY['[4국05-02][4국05-05]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C13','kor',4,2,'u1',4,'인물의 마음을 담은 낱말 — 낯설다(겪어 보지 않아 익숙하지 않다) · 머뭇거리다(선뜻 하지 못하고 망설이다) · 서성이다(한곳에 머물지 않고 왔다 갔다 하다)',ARRAY['[4국05-02][4국05-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C14','kor',4,2,'u1',4,'말과 행동으로 성격 짐작하기 — 한 장면만이 아니라 처음과 끝의 말과 행동을 함께 보고 인물의 성격을 짐작함',ARRAY['[4국05-02][4국05-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C15','kor',4,2,'u1',4,'이야기를 나와 관련짓기 — 비슷한 경험을 떠올리고, 경험이 없으면 책이나 영상에서 본 일을 떠올려 인물과 견줌',ARRAY['[4국05-02][4국05-05]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C16','kor',4,2,'u1',4,'평범해 보이는 일도 현실과 다를 수 있음 — 움직이는 그림자처럼 눈에 띄는 것만 꾸민 부분이 아님 — 주소 없는 편지에 답장이 오는 일처럼 평범해 보여도 현실의 규칙과 견주면 일어날 수 없는 일이 있음',ARRAY['[4국05-02][4국05-05]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C17','kor',4,2,'u1',4,'닮은 부분과 꾸민 부분이 주는 것 — 현실과 닮은 부분은 읽는 사람이 공감하게 하고, 꾸며 쓴 부분은 재미와 감동, 깨달음을 줌',ARRAY['[4국05-02][4국05-05]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C18','kor',4,2,'u1',4,'글쓴이가 전하려는 생각 — 이야기 속 근거를 대어 찾음 — 근거가 서면 여러 갈래로 받아들일 수 있지만, 꾸민 장치를 그대로 믿는 생각이나 이야기와 거꾸로인 생각은 알맞지 않음',ARRAY['[4국05-02][4국05-05]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C19','kor',4,2,'u1',4,'세상과 연결하기 — 이야기를 읽고 내 주변에서 도움이 필요한 사람을 떠올려 현실에서 할 수 있는 도움 방법을 상상함',ARRAY['[4국05-02][4국05-05]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C20','kor',4,2,'u1',7,'같은 문제, 다른 의견 — 같은 일을 두고도 사람마다 의견과 그렇게 생각한 이유가 다를 수 있음',ARRAY['[4국02-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C21','kor',4,2,'u1',7,'두 글이 다루는 문제 — 두 글이 함께 다루는 문제(뒤뜰 화단에 무엇을 심을까)를 찾고, 생각이 같은 곳과 갈린 곳을 가름',ARRAY['[4국02-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C22','kor',4,2,'u1',7,'글쓴이마다 이유 가르기 — 각 글쓴이가 자기 의견을 받쳐 주려고 든 이유를 찾아, 다른 글쓴이의 이유와 섞지 않고 가름',ARRAY['[4국02-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C23','kor',4,2,'u1',7,'의견을 비교하며 읽으면 좋은 점 — 같은 문제에 대한 여러 생각을 알 수 있음 · 내 의견을 정하는 데 도움이 됨 · 어느 의견이 더 알맞은지 따져 볼 수 있음',ARRAY['[4국02-04]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C24','kor',4,2,'u1',7,'다른 의견은 틀린 의견이 아님 — 의견이 반대라고 하나가 틀린 것이 아니며, 다 맞으니 따질 필요가 없는 것도 아님 — 이유가 알맞은지 따져 봄',ARRAY['[4국02-04]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C25','kor',4,2,'u1',7,'새로운 의견 — 두 글쓴이의 의견 가운데 하나를 고르지 않고 새로운 의견을 내어도 됨',ARRAY['[4국02-04]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C26','kor',4,2,'u1',8,'의견과 이유 — 의견은 어떤 문제에 대해 글쓴이가 가진 생각, 이유는 그렇게 생각한 까닭 — 있었던 일(사실)과 다름',ARRAY['[4국02-04]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C27','kor',4,2,'u1',8,'제목은 실마리 — 제목으로 의견을 짐작할 수 있지만 물음으로 된 제목은 거꾸로 읽힐 수 있음 — 제목이 곧 의견도, 아예 안 볼 것도 아님',ARRAY['[4국02-04]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C28','kor',4,2,'u1',8,'의견을 파악하는 차례 — 제목으로 짐작 → 글 끝부분의 「그러므로·그래서 ~해야 합니다·제안합니다」에서 확인 → 의견을 받쳐 주는 이유 찾기',ARRAY['[4국02-04]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C29','kor',4,2,'u1',8,'같은 것을 다르게 보는 두 글 — 두 글쓴이는 같은 대상(칭찬 스티커판)을 보고도 좋은 점과 걱정되는 점을 다르게 봄 — 한쪽이 잘못 본 것이 아님',ARRAY['[4국02-04]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C30','kor',4,2,'u1',8,'생활 속 글의 의견 — 학교 누리집 글·학급 신문·어린이 기사에도 의견이 있으며, 여러 의견을 알면 문제를 푸는 더 나은 방법을 찾을 수 있음',ARRAY['[4국02-04]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C31','kor',4,2,'u1',10,'의견을 말할 때 쓰는 낱말 — 두루(빠짐없이 골고루) · 배려(남을 도우려고 마음을 씀) · 제안(생각이나 방법을 내놓음)',ARRAY['[4국02-04][4국01-06]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C32','kor',4,2,'u1',10,'의견을 평가하는 세 가지 기준 — 문제 상황에 알맞은 의견인가 · 의견을 받쳐 주는 이유가 믿을 만한가 · 그 의견대로 했을 때 다른 문제가 생기지 않는가',ARRAY['[4국02-04][4국01-06]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C33','kor',4,2,'u1',10,'믿기 어려운 이유 — 뒷받침할 경험이나 까닭 없이 「한 명도·모두·반드시」로 장담하는 이유는 믿기 어려움',ARRAY['[4국02-04][4국01-06]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C34','kor',4,2,'u1',10,'의견대로 했을 때 생길 문제 — 그 의견대로 했을 때 누가 어떤 어려움을 겪을지 살핌(다른 쪽 글이 걱정한 일이 실마리)',ARRAY['[4국02-04][4국01-06]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C35','kor',4,2,'u1',10,'이유의 개수가 아니라 이유의 힘 — 이유가 많다고 더 알맞은 의견이 아니며, 이유와 상관없이 마음에 드는 쪽을 고르는 것도 평가가 아님',ARRAY['[4국02-04][4국01-06]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C36','kor',4,2,'u1',10,'어느 의견이든 같은 기준으로 — 한쪽만 따지고 다른 쪽은 그냥 믿으면 공평한 평가가 아님 — 두 의견 모두 같은 세 가지 기준으로 따짐',ARRAY['[4국02-04][4국01-06]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C37','kor',4,2,'u1',10,'내 의견 정하기 — 내 의견은 글쓴이와 같아도 달라도 됨 — 두 의견을 섞은 새 의견도 저절로 더 좋아지지 않으니 같은 기준으로 따짐',ARRAY['[4국02-04][4국01-06]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C38','kor',4,2,'u1',10,'의견을 나타내는 글과 평가 — 「~해야 한다」·「~라고 생각한다」로 의견을 쓰고 이유를 구체적으로 씀 · 친구 글은 의견이 달라도 존중하며 이유를 중심으로 말해 줌',ARRAY['[4국02-04][4국01-06]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C39','kor',4,2,'u1',12,'현실과 견주어 작품 소개하기 — 작품 제목 · 현실과 비슷한 점과 다른 점 · 꾸며 쓴 부분이 준 재미나 깨달음을 담음(줄거리 옮기기·「재미있었다」 한마디는 소개가 아님)',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C40','kor',4,2,'u1',12,'게시글과 댓글의 의견·이유 — 누가 한 말인지 먼저 가린 뒤 게시글과 댓글에서 각각 의견과 이유를 찾음',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C41','kor',4,2,'u1',12,'두 의견이 함께 걱정하는 것 — 맞선 두 의견도 같은 문제(안전)를 걱정할 수 있음 — 걱정하는 사람이 다를 뿐이며, 둘 다 직접 겪은 일을 이유로 듦',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C42','kor',4,2,'u1',12,'의견을 나누는 댓글 — 의견과 이유가 드러나고 다른 사람을 존중하는 말투로 씀(외치기만·「저도요」·깎아내리기는 알맞지 않음)',ARRAY['[4국05-02][4국02-04][4국01-06]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C43','kor',4,2,'u1',12,'하려는 뜻의 「-려고」 — 받침 없는 말 + 려고(보려고) · 받침 있는 말 + 으려고(먹으려고) · 원래 ㄹ 받침인 말은 그대로(놀려고·만들려고) — 원래 없던 ㄹ을 덧붙이면 틀림(볼려고)',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C44','kor',4,2,'u1',12,'「-(으)ㅁ」을 붙여 바꾼 낱말 — 받침 없으면 ㅁ(그림) · 받침 있으면 음(믿음) · ㄹ 받침에 ㅁ이 붙으면 ㄻ(만듦·힘듦)',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u1-C45','kor',4,2,'u1',12,'ㄲ·ㅆ 받침 글씨 — 닦다·묶다·샀다·왔다처럼 ㄲ·ㅆ 받침을 ㄱ·ㅅ으로 바꾸지 않고 바르게 씀',ARRAY['기초 다지기(문법·쓰기 — 성취기준 번호 확인 필요)']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X01','kor',4,'u1',ARRAY['K4-2-u1-C2','K4-2-u1-C8']::text[],'작품 속 세계를 현실과 똑같다고 여기거나 작품 속 일을 실제로 있었던 일이라고 믿는다','글쓴이가 만든 세계예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X02','kor',4,'u1',ARRAY['K4-2-u1-C3']::text[],'현실과 다르게 꾸며 쓴 부분을 거짓말이나 고쳐야 할 잘못으로 여긴다','꾸민 부분이 주는 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X03','kor',4,'u1',ARRAY['K4-2-u1-C4']::text[],'같은 작품을 읽고 마음에 남는 장면이 다르면 하나는 잘못 읽은 것이라고 여긴다','겪은 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X04','kor',4,'u1',ARRAY['K4-2-u1-C5']::text[],'인상 깊은 장면만 말하고 까닭은 말하지 않거나, 작품에 없는 장면을 든다','장면 + 왜 그 장면인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X05','kor',4,'u1',ARRAY['K4-2-u1-C8','K4-2-u1-C16']::text[],'꾸며 쓴 부분을 말하거나 움직이는 사물에서만 찾아, 그 밖의 부분은 모두 실제로 있었던 일이라고 여긴다','평범해 보여도 현실과 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X06','kor',4,'u1',ARRAY['K4-2-u1-C8','K4-2-u1-C11']::text[],'작품은 다 꾸민 것이라 현실과 견주어 볼 필요가 없다고 여긴다','견주면 현실이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X07','kor',4,'u1',ARRAY['K4-2-u1-C7']::text[],'작품과 현실을 견줄 때 서로 다른 대상끼리 잇거나 현실의 모습을 잘못 안다','같은 대상끼리 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X08','kor',4,'u1',ARRAY['K4-2-u1-C9']::text[],'말하는 이가 바라는 모습을 시 속 말과 상관없이 짐작한다','시에 나온 말을 근거로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X09','kor',4,'u1',ARRAY['K4-2-u1-C10']::text[],'바꾸어 쓰기를 현실과 견주지 않고 아무 낱말이나 바꾸거나 외워 쓰는 일로 여긴다','내가 바라는 모습 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X10','kor',4,'u1',ARRAY['K4-2-u1-C11']::text[],'작품과 현실을 비교하는 까닭을 작품에서 틀린 곳을 찾아 알려 주는 것으로 여긴다','현실을 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X11','kor',4,'u1',ARRAY['K4-2-u1-C12']::text[],'이야기에서 일어난 일의 내용이나 차례를 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X12','kor',4,'u1',ARRAY['K4-2-u1-C13','K4-2-u1-C31']::text[],'낱말의 뜻을 엇갈리게 알거나 문장에 맞지 않는 낱말을 넣는다','낱말이 나온 문장을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X13','kor',4,'u1',ARRAY['K4-2-u1-C14']::text[],'한 장면만 보거나 말과 행동과 상관없는 것을 보고 인물의 성격을 정한다','처음과 끝을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X14','kor',4,'u1',ARRAY['K4-2-u1-C15']::text[],'인물과 똑같은 일을 겪어야만 이야기를 나와 관련지을 수 있다고 여긴다','책·영상에서 본 일도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X15','kor',4,'u1',ARRAY['K4-2-u1-C17']::text[],'현실과 닮은 부분과 꾸며 쓴 부분이 하는 일을 엇갈리게 안다','공감 · 재미와 깨달음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X16','kor',4,'u1',ARRAY['K4-2-u1-C18']::text[],'꾸며 쓴 장치를 그대로 믿는 생각을 글쓴이가 전하려는 생각으로 고른다','장치가 아니라 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X17','kor',4,'u1',ARRAY['K4-2-u1-C18']::text[],'전하려는 생각은 하나뿐이라 다른 생각은 틀렸다고 여기거나, 이야기와 거꾸로이거나 근거 없는 생각을 고른다','이야기 속 근거가 서나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X18','kor',4,'u1',ARRAY['K4-2-u1-C21']::text[],'두 글이 다루는 같은 문제를 찾지 못하거나 생각이 같은 곳과 갈린 곳을 가르지 못한다','두 글이 똑같이 말하는 대상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X19','kor',4,'u1',ARRAY['K4-2-u1-C22','K4-2-u1-C40']::text[],'두 글쓴이의 이유를 섞거나 의견과 상관없는 것을 이유로 고른다','누구의 의견을 받쳐 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X20','kor',4,'u1',ARRAY['K4-2-u1-C23']::text[],'의견을 비교하며 읽는 것을 더 긴 글 따르기나 나와 같은 의견만 골라 읽기로 여긴다','여러 생각 · 내 의견 · 따져 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X21','kor',4,'u1',ARRAY['K4-2-u1-C20','K4-2-u1-C24']::text[],'의견이 반대면 둘 가운데 하나는 틀렸다고 여기거나 먼저 쓴 쪽을 따른다','다른 것과 틀린 것은 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X22','kor',4,'u1',ARRAY['K4-2-u1-C24','K4-2-u1-C35']::text[],'의견은 다 맞으니 이유를 따져 볼 필요 없이 마음에 드는 쪽을 고르면 된다고 여긴다','이유를 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X23','kor',4,'u1',ARRAY['K4-2-u1-C25','K4-2-u1-C37']::text[],'두 글쓴이의 의견 가운데 하나를 반드시 골라야 하고 새로운 의견은 낼 수 없다고 여긴다','새 의견도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X24','kor',4,'u1',ARRAY['K4-2-u1-C26']::text[],'의견과 이유, 있었던 일(사실)을 가르지 못한다','생각 · 까닭 · 있었던 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X25','kor',4,'u1',ARRAY['K4-2-u1-C27']::text[],'제목만 보고 의견을 정한다(물음으로 된 제목도 그대로 또는 무조건 거꾸로 읽는다)','제목은 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X26','kor',4,'u1',ARRAY['K4-2-u1-C27','K4-2-u1-C28']::text[],'제목은 믿을 수 없으니 아예 보지 않는다','짐작에는 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X27','kor',4,'u1',ARRAY['K4-2-u1-C28']::text[],'의견을 글 앞부분의 있었던 일이나 아무 문장에서 찾고 끝부분에서 확인하지 않는다','그러므로 · 그래서 ~') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X28','kor',4,'u1',ARRAY['K4-2-u1-C29','K4-2-u1-C41']::text[],'같은 대상을 두고 다르게 본 것을 한쪽이 잘못 보았거나 상대를 모르고 반대한 것으로 여긴다','무엇을 걱정했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X29','kor',4,'u1',ARRAY['K4-2-u1-C30']::text[],'의견을 찾아 읽는 일을 국어 시간 글에서만 하는 일로 여긴다','누리집 · 신문 · 기사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X30','kor',4,'u1',ARRAY['K4-2-u1-C32']::text[],'의견을 평가하는 기준을 글의 길이·글씨·글쓴이가 누구인지로 잡는다','알맞은가 · 믿을 만한가 · 다른 문제는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X31','kor',4,'u1',ARRAY['K4-2-u1-C33']::text[],'뒷받침할 까닭 없이 장담하는 이유(한 명도·모두·반드시)를 믿을 만한 이유로 여기거나, 경험이 받쳐 주는 이유를 믿기 어렵다고 여긴다','뒷받침할 경험이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X32','kor',4,'u1',ARRAY['K4-2-u1-C34']::text[],'의견대로 했을 때 생길 다른 문제를 살피지 않거나 의견과 상관없는 일을 든다','누가 어떤 어려움을?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X33','kor',4,'u1',ARRAY['K4-2-u1-C35']::text[],'이유가 많은 의견이 언제나 더 알맞다고 여기거나, 이유가 적으면 틀린 의견이라고 여긴다','개수 말고 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X34','kor',4,'u1',ARRAY['K4-2-u1-C36']::text[],'한쪽 의견만 따지고 다른 쪽(내 의견과 같은 쪽·경험을 든 쪽)은 그냥 믿는다','같은 기준으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X35','kor',4,'u1',ARRAY['K4-2-u1-C37']::text[],'두 의견을 반씩 섞으면 저절로 가장 좋은 의견이 된다고 여긴다','섞은 의견도 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X36','kor',4,'u1',ARRAY['K4-2-u1-C38']::text[],'의견 글이나 평가에서 이유 없이 의견만 내세우거나 나와 다른 의견을 틀렸다고 말한다','이유 중심 · 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X37','kor',4,'u1',ARRAY['K4-2-u1-C39']::text[],'작품 소개를 줄거리 옮기기나 「재미있었다」 한마디, 상관없는 정보로 여긴다','현실과 견준 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X38','kor',4,'u1',ARRAY['K4-2-u1-C42']::text[],'댓글을 이유 없이 외치거나 「저도요」 한마디로 쓰거나 상대를 깎아내린다','의견 + 이유 + 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X39','kor',4,'u1',ARRAY['K4-2-u1-C43']::text[],'원래 없던 ㄹ을 덧붙여 「-ㄹ려고」로 쓴다(볼려고·쓸려고)','기본형에 ㄹ이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X40','kor',4,'u1',ARRAY['K4-2-u1-C43']::text[],'원래 ㄹ 받침이 있는 말에서 ㄹ을 빼거나 「-으려고」를 붙여 쓴다(노려고·만드려고)','놀다 → 놀려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X41','kor',4,'u1',ARRAY['K4-2-u1-C44']::text[],'「-(으)ㅁ」을 붙일 때 받침에 따라 ㅁ·음·ㄻ을 엇갈리게 쓴다(만듬·그리음)','받침 없음 · 있음 · ㄹ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X42','kor',4,'u1',ARRAY['K4-2-u1-C45']::text[],'ㄲ·ㅆ 받침을 ㄱ·ㅅ이나 다른 받침으로 쓴다(닥다·왓다)','쌍받침 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X43','kor',4,'u1',ARRAY['K4-2-u1-C24','K4-2-u1-C38']::text[],'다른 의견을 존중하라는 말을 다툼이 없게 무조건 친구 의견을 따르라는 것으로 여긴다','듣고 함께 따지기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X44','kor',4,'u1',ARRAY['K4-2-u1-C2','K4-2-u1-C16']::text[],'현실에서 흔히 볼 수 있는 일을 현실에서 일어나기 어려운 일로 잘못 고른다','우리 동네에서도 볼 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u1-X45','kor',4,'u1',ARRAY['K4-2-u1-C19']::text[],'세상과 연결할 때 이야기 속 꾸민 장치를 현실에서 그대로 쓰려 한다','현실에서 할 수 있는 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#1','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C2',1,'mc','auto','「병에 담긴 바닷바람」에서 현실에서는 일어나기 어려운 장면은 무엇인가요?',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":1,"concept":"K4-2-u1-C2","difficulty":1,"kind":"mc","stem":"「병에 담긴 바닷바람」에서 현실에서는 일어나기 어려운 장면은 무엇인가요?","options":[{"t":"병뚜껑을 열자 방 안에 파도 소리와 짠 바람이 가득 찬 장면","correct":true},{"t":"무더운 여름 날씨가 이어지는 장면","mis":"K4-2-u1-X44"},{"t":"아이가 모아 둔 용돈으로 물건을 사는 장면","mis":"K4-2-u1-X44"},{"t":"경비원 아저씨가 땀을 닦는 장면","mis":"K4-2-u1-X44"}],"explanation":["우리 동네에서도 볼 수 있는 장면을 빼요.","병 속에서 파도 소리가 나는 일은 없어요.","그 장면이 꾸며 쓴 부분이에요."],"asset":{"type":"passage","lines":["무더운 여름, 골목에 병에 담긴 바람을 파는 작은 가게가 생겼다.","아이가 모아 둔 용돈으로 「시원한 바닷바람」 한 병을 샀다.","뚜껑을 열자 방 안에 파도 소리와 짠 바람이 가득 찼다.","아이는 땀을 닦던 경비원 아저씨께 그 병을 드렸다."],"title":"이야기 「병에 담긴 바닷바람」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#2','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C3',1,'mc','auto','이야기에서 현실과 다르게 꾸며 쓴 부분은 어떤 일을 하나요?',ARRAY['K4-2-u1-X02','K4-2-u1-X06']::text[],false,'{"seq":2,"concept":"K4-2-u1-C3","difficulty":1,"kind":"mc","stem":"이야기에서 현실과 다르게 꾸며 쓴 부분은 어떤 일을 하나요?","options":[{"t":"상상하는 재미를 주고 인물의 마음을 더 또렷하게 보여 준다","correct":true},{"t":"이야기를 거짓말로 만들어 믿을 수 없게 한다","mis":"K4-2-u1-X02"},{"t":"읽는 사람을 헷갈리게 하니 고쳐야 할 곳이다","mis":"K4-2-u1-X02"},{"t":"현실과 견주어 볼 필요가 없다는 것을 알려 준다","mis":"K4-2-u1-X06"}],"explanation":["거짓말이 아니에요.","상상하는 재미가 생겨요.","아이의 따뜻한 마음도 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#3','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C4',1,'ox','auto','같은 이야기를 읽고 마음에 남는 장면이 친구와 다르면 둘 가운데 하나는 잘못 읽은 거예요.',ARRAY['K4-2-u1-X03']::text[],false,'{"seq":3,"concept":"K4-2-u1-C4","difficulty":1,"kind":"ox","stem":"같은 이야기를 읽고 마음에 남는 장면이 친구와 다르면 둘 가운데 하나는 잘못 읽은 거예요.","answer":"X","reason_options":[{"t":"사람마다 겪은 일이 달라 마음에 남는 장면이 다를 수 있고, 까닭과 함께 말하면 되기 때문에","correct":true},{"t":"이야기마다 마음에 남아야 할 장면이 하나로 정해져 있기 때문에","mis":"K4-2-u1-X03"}],"mis":"K4-2-u1-X03","explanation":["다현이와 채이를 떠올려요.","마음에 남은 곳이 달랐어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#4','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C1',1,'mc','auto','이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X33','K4-2-u1-X21']::text[],false,'{"seq":4,"concept":"K4-2-u1-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"작품 속 세계와 현실 세계 비교하기 · 서로 다른 글쓴이의 의견 비교하기","correct":true},{"t":"작품 줄거리 외우기 · 나와 같은 의견의 글만 골라 읽기","mis":"K4-2-u1-X20"},{"t":"꾸며 쓴 부분 지우기 · 이유가 많은 글 고르기","mis":"K4-2-u1-X33"},{"t":"꾸며 쓴 부분을 거짓말이라 알리기 · 먼저 쓴 의견 따르기","mis":"K4-2-u1-X21"}],"explanation":["하나는 작품과 현실이에요.","하나는 서로 다른 의견이에요.","둘 다 나란히 놓고 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#5','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C7',2,'match','auto','「느림보 신호등」에 나타난 모습과 현실의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u1-C7","difficulty":2,"kind":"match","stem":"「느림보 신호등」에 나타난 모습과 현실의 모습을 알맞게 이으세요.","pairs":[{"l":"신호등이 「천천히 오세요」 하고 말한다","r":"신호등은 불빛과 소리로만 알린다"},{"l":"초록 눈이 할머니를 꾹 참고 기다린다","r":"초록불은 정해진 시간이 지나면 바뀐다"},{"l":"자동차들이 하품하며 기다린다","r":"자동차는 정지선에서 멈추어 기다린다"}],"mis":"K4-2-u1-X07","explanation":["같은 대상끼리 이어요.","신호등 · 초록불 · 자동차예요.","시와 현실이 어떻게 다른지 보여요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#6','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C6',2,'mc','auto','「느림보 신호등」을 읽고 내 경험을 떠올려 말하면 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X04','K4-2-u1-X01','K4-2-u1-X14']::text[],false,'{"seq":6,"concept":"K4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「느림보 신호등」을 읽고 내 경험을 떠올려 말하면 좋은 점은 무엇인가요?","options":[{"t":"내 경험과 견주어 시에서 현실과 닮은 부분이 잘 보인다","correct":true},{"t":"시에 없는 장면을 더 지어낼 수 있다","mis":"K4-2-u1-X04"},{"t":"시가 현실과 똑같은지 확인할 수 있다","mis":"K4-2-u1-X01"},{"t":"경험이 없는 친구는 시를 읽지 않아도 된다","mis":"K4-2-u1-X14"}],"explanation":["초록불에 뛴 적이 있나요?","그 경험이 시와 겹쳐요.","닮은 부분이 보여요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#7','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C8',2,'mc','auto','「느림보 신호등」을 읽은 친구가 「말하는 신호등만 빼면 나머지는 모두 진짜 있었던 일이야.」라고 했어요. 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X02']::text[],false,'{"seq":7,"concept":"K4-2-u1-C8","difficulty":2,"kind":"mc","stem":"「느림보 신호등」을 읽은 친구가 「말하는 신호등만 빼면 나머지는 모두 진짜 있었던 일이야.」라고 했어요. 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 닮은 부분도 말하는 이가 바라는 모습을 그리려고 골라 엮은 거라, 그대로 있었던 일이라고 할 수 없어","correct":true},{"t":"맞아. 말하는 것만 꾸며 쓴 거야.","mis":"K4-2-u1-X05"},{"t":"시는 다 꾸민 거라서 현실과 견줄 필요가 없어.","mis":"K4-2-u1-X06"},{"t":"시는 거짓말이니까 믿으면 안 돼.","mis":"K4-2-u1-X02"}],"explanation":["「뛰지 않아도 되는 길」을 떠올려요.","정말 있었던 일일까요?","시 전체가 말하는 이가 만든 세계예요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#8','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C9',2,'mc','auto','「느림보 신호등」의 말하는 이가 현실의 사람들에게 바라는 모습은 무엇인가요?',ARRAY['K4-2-u1-X08']::text[],false,'{"seq":8,"concept":"K4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「느림보 신호등」의 말하는 이가 현실의 사람들에게 바라는 모습은 무엇인가요?","options":[{"t":"걸음이 느린 사람도 서두르지 않고 안전하게 건널 수 있는 동네","correct":true},{"t":"자동차가 더 빨리 지나가는 동네","mis":"K4-2-u1-X08"},{"t":"신호등 불빛이 더 밝아지는 동네","mis":"K4-2-u1-X08"},{"t":"초록불이 아주 짧아 모두 뛰어 건너는 동네","mis":"K4-2-u1-X08"}],"explanation":["「뛰지 않아도 되는 길」을 봐요.","「느긋한 우리 동네」도 봐요.","서두르지 않아도 되는 동네예요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#9','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C11',2,'mc','auto','작품 속 세계와 현실 세계를 비교하며 읽으면 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X10','K4-2-u1-X02','K4-2-u1-X01']::text[],false,'{"seq":9,"concept":"K4-2-u1-C11","difficulty":2,"kind":"mc","stem":"작품 속 세계와 현실 세계를 비교하며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"익숙한 모습을 새로운 눈으로 볼 수 있다","correct":true},{"t":"작품에서 틀린 곳을 찾아 고칠 수 있다","mis":"K4-2-u1-X10"},{"t":"작품이 거짓인지 참인지 가릴 수 있다","mis":"K4-2-u1-X02"},{"t":"현실과 똑같은 작품만 골라 읽을 수 있다","mis":"K4-2-u1-X01"}],"explanation":["늘 보던 건널목이에요.","시와 견주니 달리 보여요.","새로운 눈이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_basic#10','kor',4,2,'u1','L02','g4_2_kor_u1_L02_basic','lesson_basic','K4-2-u1-C5',3,'error','auto','「느림보 신호등」에서 인상 깊은 장면을 말했어요. 모자라게 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X04']::text[],false,'{"seq":10,"concept":"K4-2-u1-C5","difficulty":3,"kind":"error","stem":"「느림보 신호등」에서 인상 깊은 장면을 말했어요. 모자라게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「자동차가 하품하는 장면이 인상 깊어.」","correct":true,"mis_target":"K4-2-u1-X04"},{"t":"친구 가 — 「할머니를 기다리는 장면이 인상 깊어. 우리 할머니 걸음이 떠올랐거든.」","mis":"K4-2-u1-X04"},{"t":"친구 나 — 「‘뛰지 않아도 되는 길’이 인상 깊어. 나는 늘 초록불에 뛰었거든.」","mis":"K4-2-u1-X04"}],"explanation":["장면은 셋 다 말했어요.","까닭이 빠진 친구가 있어요.","친구 다가 모자라요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#1','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C2',2,'sa','auto','작품에서 현실과 다르게 상상하여 지어낸 부분을 무엇이라고 하나요? 「○○ 쓴 부분」의 ○○에 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u1-C2","difficulty":2,"kind":"sa","stem":"작품에서 현실과 다르게 상상하여 지어낸 부분을 무엇이라고 하나요? 「○○ 쓴 부분」의 ○○에 들어갈 말을 쓰세요.","answer":["꾸며"],"explanation":["현실과 다른 부분이에요.","상상해 지어낸 부분이에요.","‘꾸며’ 쓴 부분이에요."],"mis":"K4-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#2','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C4',2,'mc','auto','다현이와 채이의 마음에 남은 장면이 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X03','K4-2-u1-X04']::text[],false,'{"seq":2,"concept":"K4-2-u1-C4","difficulty":2,"kind":"mc","stem":"다현이와 채이의 마음에 남은 장면이 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"채이는 한여름 경비실을 본 일이 있어 그 부분이 진짜처럼 느껴졌기 때문에","correct":true},{"t":"채이가 이야기를 잘못 읽었기 때문에","mis":"K4-2-u1-X03"},{"t":"다현이만 꾸며 쓴 부분을 제대로 찾았기 때문에","mis":"K4-2-u1-X03"},{"t":"두 친구 모두 이야기에 없는 장면을 말했기 때문에","mis":"K4-2-u1-X04"}],"explanation":["채이 말에 경험이 있어요.","겪은 일이 달라요.","그래서 마음에 남은 곳이 달라요."],"asset":{"type":"speech","turns":[{"who":"다현","text":"병에서 바닷바람이 나오는 장면이 정말 신기했어."},{"who":"채이","text":"나는 우리 아파트 경비실도 한여름에 무척 더워 보여서 그 부분이 진짜 같았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#3','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C8',3,'mc','auto','「느림보 신호등」의 「책가방 멘 나도 / 숨 고르며 걷는다」는 어떻게 보는 것이 알맞나요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":3,"concept":"K4-2-u1-C8","difficulty":3,"kind":"mc","stem":"「느림보 신호등」의 「책가방 멘 나도 / 숨 고르며 걷는다」는 어떻게 보는 것이 알맞나요?","options":[{"t":"현실에도 있을 법한 모습이지만, 말하는 이가 바라는 동네를 그리려고 골라 쓴 장면이다","correct":true},{"t":"말하는 사물이 아니니 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"시는 다 꾸민 것이라 따져 볼 필요가 없다","mis":"K4-2-u1-X06"},{"t":"시인이 어제 본 일을 그대로 옮긴 것이다","mis":"K4-2-u1-X01"}],"explanation":["아이가 걷는 건 흔한 일이에요.","그런데 뛰지 않아도 되는 길이에요.","바라는 모습을 그리려고 쓴 장면이에요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#4','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C3',3,'mc','auto','「병에 담긴 바닷바람」에 바람을 파는 가게가 없고 「아이가 아저씨께 부채를 드렸다.」만 있다면 어떻게 달라질까요?',ARRAY['K4-2-u1-X02','K4-2-u1-X15','K4-2-u1-X06']::text[],false,'{"seq":4,"concept":"K4-2-u1-C3","difficulty":3,"kind":"mc","stem":"「병에 담긴 바닷바람」에 바람을 파는 가게가 없고 「아이가 아저씨께 부채를 드렸다.」만 있다면 어떻게 달라질까요?","options":[{"t":"현실과 더 비슷해지지만 상상하는 재미가 줄어든다","correct":true},{"t":"거짓이 없어졌으니 더 좋은 이야기가 된다","mis":"K4-2-u1-X02"},{"t":"아이의 마음이 더 신기하고 또렷하게 다가온다","mis":"K4-2-u1-X15"},{"t":"꾸민 부분이 없으니 현실과 견줄 거리가 더 많아진다","mis":"K4-2-u1-X06"}],"explanation":["현실 그대로만 쓰면 어떨까요?","신기한 장면이 사라져요.","상상하는 재미가 줄어요."],"asset":{"type":"passage","lines":["무더운 여름, 골목에 병에 담긴 바람을 파는 작은 가게가 생겼다.","아이가 모아 둔 용돈으로 「시원한 바닷바람」 한 병을 샀다.","뚜껑을 열자 방 안에 파도 소리와 짠 바람이 가득 찼다.","아이는 땀을 닦던 경비원 아저씨께 그 병을 드렸다."],"title":"이야기 「병에 담긴 바닷바람」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#5','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C10',3,'mc','auto','시의 한 부분을 바꾸어 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X09','K4-2-u1-X02']::text[],false,'{"seq":5,"concept":"K4-2-u1-C10","difficulty":3,"kind":"mc","stem":"시의 한 부분을 바꾸어 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 견주어 본 뒤 내가 바라는 모습을 상상해 바꾸고, 바꾼 까닭을 말한다","correct":true},{"t":"아무 낱말이나 반대말로 바꾼다","mis":"K4-2-u1-X09"},{"t":"현실과 똑같아지도록 꾸민 부분을 모두 지운다","mis":"K4-2-u1-X02"},{"t":"시 전체를 외워서 처음부터 다시 쓴다","mis":"K4-2-u1-X09"}],"explanation":["먼저 현실과 견주어요.","바라는 모습을 상상해요.","바꾼 까닭도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#6','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C11',3,'ox','auto','작품과 현실을 비교하는 까닭은 작품에서 현실과 다른 곳을 찾아 틀렸다고 알려 주기 위해서예요.',ARRAY['K4-2-u1-X10']::text[],false,'{"seq":6,"concept":"K4-2-u1-C11","difficulty":3,"kind":"ox","stem":"작품과 현실을 비교하는 까닭은 작품에서 현실과 다른 곳을 찾아 틀렸다고 알려 주기 위해서예요.","answer":"X","reason_options":[{"t":"현실의 모습을 되돌아보고, 현실과 다른 세계를 상상해 볼 수 있기 때문에","correct":true},{"t":"작품은 현실과 똑같이 써야 하기 때문에","mis":"K4-2-u1-X10"}],"mis":"K4-2-u1-X10","explanation":["틀린 곳 찾기가 아니에요.","현실을 되돌아봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#7','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C9',3,'error','auto','「느림보 신호등」의 말하는 이가 바라는 모습을 잘못 짐작한 친구는 누구인가요?',ARRAY['K4-2-u1-X08']::text[],false,'{"seq":7,"concept":"K4-2-u1-C9","difficulty":3,"kind":"error","stem":"「느림보 신호등」의 말하는 이가 바라는 모습을 잘못 짐작한 친구는 누구인가요?","options":[{"t":"친구 나 — 「초록불이 빨리 바뀌어서 차가 막히지 않는 동네야.」","correct":true,"mis_target":"K4-2-u1-X08"},{"t":"친구 가 — 「할머니도 서두르지 않고 건널 수 있는 동네야.」","mis":"K4-2-u1-X08"},{"t":"친구 다 — 「아이도 숨 고르며 걸을 수 있는 느긋한 동네야.」","mis":"K4-2-u1-X08"}],"explanation":["신호등은 기다려 줘요.","빨리 바뀌는 건 시와 거꾸로예요.","친구 나가 잘못 짐작했어요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#8','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C8',4,'mc','auto','「병에 담긴 바닷바람」에 대한 생각 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":8,"concept":"K4-2-u1-C8","difficulty":4,"kind":"mc","stem":"「병에 담긴 바닷바람」에 대한 생각 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"바람이 나오는 일뿐 아니라 하나뿐인 병을 아저씨께 드리는 장면도 글쓴이가 전하고 싶은 마음을 그리려고 지은 것이다","correct":true},{"t":"바람이 나오는 장면만 꾸민 것이고 나머지는 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"꾸민 장면이 있으니 이 이야기는 현실과 견줄 수 없다","mis":"K4-2-u1-X06"},{"t":"병에 바람을 담아 파는 가게가 어딘가에 실제로 있을 것이다","mis":"K4-2-u1-X01"}],"explanation":["신기한 장면만 꾸민 걸까요?","이야기 전체를 글쓴이가 지었어요.","따뜻한 마음을 그리려고요."],"asset":{"type":"passage","lines":["무더운 여름, 골목에 병에 담긴 바람을 파는 작은 가게가 생겼다.","아이가 모아 둔 용돈으로 「시원한 바닷바람」 한 병을 샀다.","뚜껑을 열자 방 안에 파도 소리와 짠 바람이 가득 찼다.","아이는 땀을 닦던 경비원 아저씨께 그 병을 드렸다."],"title":"이야기 「병에 담긴 바닷바람」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#9','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C7',4,'essay','teacher','「느림보 신호등」에서 시에 나타난 모습 하나를 골라 현실의 모습과 견주어 쓰고, 말하는 이가 왜 그렇게 썼을지 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C7","difficulty":4,"kind":"essay","stem":"「느림보 신호등」에서 시에 나타난 모습 하나를 골라 현실의 모습과 견주어 쓰고, 말하는 이가 왜 그렇게 썼을지 짐작해 쓰세요.","answer_guide":{"answer":"예: 시에서는 신호등이 할머니를 꾹 참고 기다리지만, 현실의 초록불은 정해진 시간이 지나면 바뀐다. 걸음이 느린 사람도 서두르지 않고 안전하게 건널 수 있는 동네가 되기를 바라서 그렇게 쓴 것 같다.","scoring_points":["시에 나타난 모습을 골랐는가","같은 대상의 현실 모습과 견주었는가","그렇게 쓴 까닭을 시 속 말과 이어 짐작했는가"]},"explanation":["같은 대상끼리 견줘요.","어떻게 다른지 써요.","바라는 모습과 이어요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L02_challenge#10','kor',4,2,'u1','L02','g4_2_kor_u1_L02_challenge','lesson_challenge','K4-2-u1-C2',4,'essay','teacher','「병에 담긴 바닷바람」에서 현실과 비슷한 부분과 꾸며 쓴 부분을 하나씩 찾아 쓰고, 꾸며 쓴 부분이 이야기에 무엇을 더해 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C2","difficulty":4,"kind":"essay","stem":"「병에 담긴 바닷바람」에서 현실과 비슷한 부분과 꾸며 쓴 부분을 하나씩 찾아 쓰고, 꾸며 쓴 부분이 이야기에 무엇을 더해 주는지 쓰세요.","answer_guide":{"answer":"예: 무더운 여름에 경비원 아저씨가 땀을 닦는 모습은 현실과 비슷하다. 병뚜껑을 열자 파도 소리와 바람이 쏟아지는 것은 꾸며 쓴 부분이다. 꾸며 쓴 부분 덕분에 상상하는 재미가 생기고, 아이가 하나뿐인 시원함을 드린 따뜻한 마음이 더 또렷하게 다가온다.","scoring_points":["현실과 비슷한 부분을 찾았는가","꾸며 쓴 부분을 찾았는가","꾸며 쓴 부분이 더해 주는 것을 썼는가"]},"explanation":["우리 동네에도 있는 모습이에요.","현실에선 없는 일이에요.","재미와 마음을 더해요."],"asset":{"type":"passage","lines":["무더운 여름, 골목에 병에 담긴 바람을 파는 작은 가게가 생겼다.","아이가 모아 둔 용돈으로 「시원한 바닷바람」 한 병을 샀다.","뚜껑을 열자 방 안에 파도 소리와 짠 바람이 가득 찼다.","아이는 땀을 닦던 경비원 아저씨께 그 병을 드렸다."],"title":"이야기 「병에 담긴 바닷바람」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#1','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C12',1,'mc','auto','「골목 끝 빨간 우체통」에서 은호가 편지 봉투에 적은 것은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":1,"concept":"K4-2-u1-C12","difficulty":1,"kind":"mc","stem":"「골목 끝 빨간 우체통」에서 은호가 편지 봉투에 적은 것은 무엇인가요?","options":[{"t":"「건우에게」라는 이름만","correct":true},{"t":"건우네 새 주소와 이름","mis":"K4-2-u1-X11"},{"t":"해린이의 이름","mis":"K4-2-u1-X11"},{"t":"할머니 댁 주소","mis":"K4-2-u1-X11"}],"explanation":["새 주소를 몰랐어요.","그래서 이름만 적었어요.","「건우에게」뿐이에요."],"asset":{"type":"passage","lines":["은호네 가족은 가을에 새 동네로 이사를 왔다.","새 학교에서 은호는 쉬는 시간마다 창밖만 보았다.","집으로 오는 골목 끝에는 오래된 빨간 우체통이 서 있었다.","은호는 이사 오기 전 단짝이던 건우에게 편지를 썼다.","새 주소를 몰라서 봉투에는 「건우에게」라고만 적었다.","은호는 우체통 앞에서 한참 머뭇거리다가 편지를 넣었다.","그날 밤, 우체통의 그림자가 스르르 길어지더니 편지를 품고 골목을 건너갔다."],"title":"이야기 「골목 끝 빨간 우체통」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#2','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C13',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u1-C13","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"낯설다","r":"전에 겪어 보지 않아 익숙하지 않다"},{"l":"머뭇거리다","r":"선뜻 하지 못하고 자꾸 망설이다"},{"l":"서성이다","r":"한곳에 머물지 않고 왔다 갔다 하다"}],"mis":"K4-2-u1-X12","explanation":["낱말이 나온 문장을 떠올려요.","우체통 앞에서, 교실 뒤에서였어요.","은호의 마음이 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#3','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C14',1,'mc','auto','인물의 성격을 짐작하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":3,"concept":"K4-2-u1-C14","difficulty":1,"kind":"mc","stem":"인물의 성격을 짐작하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"처음과 끝의 말과 행동을 함께 본다","correct":true},{"t":"맨 처음 한 장면만 본다","mis":"K4-2-u1-X13"},{"t":"인물의 이름을 보고 정한다","mis":"K4-2-u1-X13"},{"t":"인물이 입은 옷 색깔을 본다","mis":"K4-2-u1-X13"}],"explanation":["한 장면만 보면 반쪽이에요.","말과 행동을 모아요.","처음과 끝을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#4','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C15',1,'ox','auto','은호처럼 이사를 해 본 적이 없으면 이 이야기를 나와 관련지을 수 없어요.',ARRAY['K4-2-u1-X14']::text[],false,'{"seq":4,"concept":"K4-2-u1-C15","difficulty":1,"kind":"ox","stem":"은호처럼 이사를 해 본 적이 없으면 이 이야기를 나와 관련지을 수 없어요.","answer":"X","reason_options":[{"t":"낯선 곳에서 쓸쓸했던 다른 경험이나 책·영상에서 본 일을 떠올려도 되기 때문에","correct":true},{"t":"똑같은 일을 겪어야만 이야기를 이해할 수 있기 때문에","mis":"K4-2-u1-X14"}],"mis":"K4-2-u1-X14","explanation":["새 학원에 간 날도 낯설어요.","책에서 본 일도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#5','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C16',2,'mc','auto','「골목 끝 빨간 우체통」에서 그림자처럼 눈에 띄지는 않지만 현실에서는 일어나기 어려운 일은 무엇인가요?',ARRAY['K4-2-u1-X44']::text[],false,'{"seq":5,"concept":"K4-2-u1-C16","difficulty":2,"kind":"mc","stem":"「골목 끝 빨간 우체통」에서 그림자처럼 눈에 띄지는 않지만 현실에서는 일어나기 어려운 일은 무엇인가요?","options":[{"t":"주소 없이 이름만 적은 편지에 답장이 창틀로 온 일","correct":true},{"t":"이사 와서 새 친구를 사귀기 어려운 일","mis":"K4-2-u1-X44"},{"t":"할머니가 손주에게 농담을 건넨 일","mis":"K4-2-u1-X44"},{"t":"짝의 필통에 그림 스티커가 붙어 있는 일","mis":"K4-2-u1-X44"}],"explanation":["편지가 어떻게 전해졌나요?","주소가 없었어요.","평범해 보여도 현실과 달라요."],"asset":{"type":"passage","lines":["다음 날 아침, 은호의 창틀에 하늘색 편지 한 장이 놓여 있었다.","「나도 이 동네가 아직 낯설어. 쉬는 시간에 창밖을 보는 건 나도 똑같아.」","편지 끝에는 이름 대신 작은 은행잎이 그려져 있었다.","어느 날 은호는 짝 해린이의 필통에 똑같은 은행잎 그림을 보았다.","은호는 교실 뒤에서 한참 서성이다가 용기를 내어 말했다. 「혹시…… 너니?」","해린이도 지난봄에 이사를 왔던 것이다.","두 아이는 함께 마지막 편지를 넣었다. 「이제부터는 우리가 직접 말할게.」"],"title":"이야기 「골목 끝 빨간 우체통」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#6','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C16',2,'mc','auto','주소 없는 편지에 답장이 온 일이 현실과 다른 까닭은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X44','K4-2-u1-X11']::text[],false,'{"seq":6,"concept":"K4-2-u1-C16","difficulty":2,"kind":"mc","stem":"주소 없는 편지에 답장이 온 일이 현실과 다른 까닭은 무엇인가요?","options":[{"t":"실제로는 봉투에 주소가 없으면 편지를 전해 줄 수 없기 때문에","correct":true},{"t":"우체통이 말을 하지 않았기 때문에","mis":"K4-2-u1-X05"},{"t":"답장 편지가 하늘색이었기 때문에","mis":"K4-2-u1-X44"},{"t":"은호가 편지를 쓰지 않았기 때문에","mis":"K4-2-u1-X11"}],"explanation":["우체국은 주소로 편지를 전해요.","주소가 없었어요.","그래서 현실과 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#7','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C17',2,'mc','auto','은호의 쓸쓸한 마음처럼 현실과 닮은 부분은 읽는 사람에게 무엇을 주나요?',ARRAY['K4-2-u1-X02','K4-2-u1-X15']::text[],false,'{"seq":7,"concept":"K4-2-u1-C17","difficulty":2,"kind":"mc","stem":"은호의 쓸쓸한 마음처럼 현실과 닮은 부분은 읽는 사람에게 무엇을 주나요?","options":[{"t":"읽는 사람이 인물의 마음에 공감하게 한다","correct":true},{"t":"이야기를 거짓으로 만든다","mis":"K4-2-u1-X02"},{"t":"신기한 재미만 준다","mis":"K4-2-u1-X15"},{"t":"읽는 사람을 헷갈리게 한다","mis":"K4-2-u1-X02"}],"explanation":["나도 낯설었던 적이 있어요.","은호 마음을 알 것 같아요.","공감하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#8','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C18',2,'mc','auto','「골목 끝 빨간 우체통」의 글쓴이가 전하려는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":8,"concept":"K4-2-u1-C18","difficulty":2,"kind":"mc","stem":"「골목 끝 빨간 우체통」의 글쓴이가 전하려는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"마음을 먼저 건네면 같은 마음을 가진 친구를 만날 수 있다","correct":true},{"t":"오래된 우체통에는 마법이 있으니 편지를 많이 넣자","mis":"K4-2-u1-X16"},{"t":"이사를 가면 새 친구를 사귈 수 없다","mis":"K4-2-u1-X17"},{"t":"친구에게는 직접 말하지 말고 편지로만 마음을 전하자","mis":"K4-2-u1-X17"}],"explanation":["마지막 편지를 떠올려요.","「이제부터는 우리가 직접 말할게.」","근거가 서는 생각을 골라요."],"asset":{"type":"passage","lines":["다음 날 아침, 은호의 창틀에 하늘색 편지 한 장이 놓여 있었다.","「나도 이 동네가 아직 낯설어. 쉬는 시간에 창밖을 보는 건 나도 똑같아.」","편지 끝에는 이름 대신 작은 은행잎이 그려져 있었다.","어느 날 은호는 짝 해린이의 필통에 똑같은 은행잎 그림을 보았다.","은호는 교실 뒤에서 한참 서성이다가 용기를 내어 말했다. 「혹시…… 너니?」","해린이도 지난봄에 이사를 왔던 것이다.","두 아이는 함께 마지막 편지를 넣었다. 「이제부터는 우리가 직접 말할게.」"],"title":"이야기 「골목 끝 빨간 우체통」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#9','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C12',2,'mc','auto','「골목 끝 빨간 우체통」의 끝에 일어난 일은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":9,"concept":"K4-2-u1-C12","difficulty":2,"kind":"mc","stem":"「골목 끝 빨간 우체통」의 끝에 일어난 일은 무엇인가요?","options":[{"t":"은호가 해린이에게 먼저 말을 걸었다","correct":true},{"t":"우체통에 넣은 편지에 이름 없는 답장이 왔다","mis":"K4-2-u1-X11"},{"t":"이사 온 은호가 쉬는 시간마다 창밖만 보았다","mis":"K4-2-u1-X11"},{"t":"할머니가 우체통이 배가 고프다고 하셨다","mis":"K4-2-u1-X11"}],"explanation":["처음엔 말을 못 걸었어요.","가운데에 답장이 왔어요.","끝에 먼저 말을 걸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_basic#10','kor',4,2,'u1','L04','g4_2_kor_u1_L04_basic','lesson_basic','K4-2-u1-C19',3,'error','auto','이야기를 읽고 주변에서 도움이 필요한 사람을 도울 방법을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X45']::text[],false,'{"seq":10,"concept":"K4-2-u1-C19","difficulty":3,"kind":"error","stem":"이야기를 읽고 주변에서 도움이 필요한 사람을 도울 방법을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「전학 온 친구에게 그림자 우체통을 찾아 주겠다.」","correct":true,"mis_target":"K4-2-u1-X45"},{"t":"친구 가 — 「전학 온 친구에게 같이 놀자고 쪽지를 건네겠다.」","mis":"K4-2-u1-X45"},{"t":"친구 다 — 「이사 온 옆집 동생에게 동네 가게 위치를 그려 주겠다.」","mis":"K4-2-u1-X45"}],"explanation":["현실에서 할 수 있는 일이어야 해요.","그림자 우체통은 꾸민 장치예요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#1','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C13',2,'blank','auto','「은호는 우체통 앞에서 한참 (　) 편지를 넣었다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":1,"concept":"K4-2-u1-C13","difficulty":2,"kind":"blank","stem":"「은호는 우체통 앞에서 한참 (　) 편지를 넣었다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"머뭇거리다가","correct":true},{"t":"낯설다가","mis":"K4-2-u1-X12"},{"t":"반가워하다가","mis":"K4-2-u1-X12"},{"t":"뛰어가다가","mis":"K4-2-u1-X12"}],"explanation":["편지를 넣을까 말까 했어요.","선뜻 넣지 못했어요.","머뭇거리다가예요."],"asset":{"type":"passage","lines":["은호네 가족은 가을에 새 동네로 이사를 왔다.","새 학교에서 은호는 쉬는 시간마다 창밖만 보았다.","집으로 오는 골목 끝에는 오래된 빨간 우체통이 서 있었다.","은호는 이사 오기 전 단짝이던 건우에게 편지를 썼다.","새 주소를 몰라서 봉투에는 「건우에게」라고만 적었다.","은호는 우체통 앞에서 한참 머뭇거리다가 편지를 넣었다.","그날 밤, 우체통의 그림자가 스르르 길어지더니 편지를 품고 골목을 건너갔다."],"title":"이야기 「골목 끝 빨간 우체통」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#2','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C14',2,'mc','auto','은호의 말과 행동으로 짐작할 수 있는 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":2,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"은호의 말과 행동으로 짐작할 수 있는 성격은 무엇인가요?","options":[{"t":"처음엔 말을 잘 걸지 못하지만 마음먹으면 먼저 다가가는 성격","correct":true},{"t":"처음부터 누구에게나 말을 잘 거는 성격","mis":"K4-2-u1-X13"},{"t":"친구에게 관심이 없는 성격","mis":"K4-2-u1-X13"},{"t":"끝까지 아무에게도 말하지 못하는 성격","mis":"K4-2-u1-X13"}],"explanation":["처음엔 창밖만 보았어요.","끝엔 먼저 말을 걸었어요.","둘을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#3','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C16',3,'mc','auto','은호의 창틀에 답장이 놓인 일을 두고 한 생각 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X44']::text[],false,'{"seq":3,"concept":"K4-2-u1-C16","difficulty":3,"kind":"mc","stem":"은호의 창틀에 답장이 놓인 일을 두고 한 생각 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"마법처럼 보이지 않아도, 주소 없는 편지가 해린이에게 전해진 것부터 현실에서는 일어나기 어렵다","correct":true},{"t":"그림자가 움직인 것만 꾸민 것이고 답장은 실제로 있을 수 있는 일이다","mis":"K4-2-u1-X05"},{"t":"이야기는 다 꾸민 것이라 따져 볼 필요가 없다","mis":"K4-2-u1-X06"},{"t":"친구 집 창틀에 편지를 두는 일은 현실에서 절대 일어날 수 없다","mis":"K4-2-u1-X44"}],"explanation":["창틀에 편지를 두는 건 흔해요.","그런데 편지가 어떻게 해린이에게 갔을까요?","주소가 없었어요."],"asset":{"type":"passage","lines":["다음 날 아침, 은호의 창틀에 하늘색 편지 한 장이 놓여 있었다.","「나도 이 동네가 아직 낯설어. 쉬는 시간에 창밖을 보는 건 나도 똑같아.」","편지 끝에는 이름 대신 작은 은행잎이 그려져 있었다.","어느 날 은호는 짝 해린이의 필통에 똑같은 은행잎 그림을 보았다.","은호는 교실 뒤에서 한참 서성이다가 용기를 내어 말했다. 「혹시…… 너니?」","해린이도 지난봄에 이사를 왔던 것이다.","두 아이는 함께 마지막 편지를 넣었다. 「이제부터는 우리가 직접 말할게.」"],"title":"이야기 「골목 끝 빨간 우체통」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#4','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C18',3,'mc','auto','글쓴이가 전하려는 생각을 친구들이 서로 다르게 말했어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X17','K4-2-u1-X16']::text[],false,'{"seq":4,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"글쓴이가 전하려는 생각을 친구들이 서로 다르게 말했어요. 알맞은 생각은 무엇인가요?","options":[{"t":"이야기 속에서 근거를 댈 수 있으면 서로 달라도 받아들일 수 있다","correct":true},{"t":"전하려는 생각은 하나뿐이라 다른 생각은 틀렸다","mis":"K4-2-u1-X17"},{"t":"이야기에 없는 생각이어도 내 마음에 들면 알맞다","mis":"K4-2-u1-X17"},{"t":"우체통에 마법이 있다는 생각도 그림자 장면이 근거이니 알맞다","mis":"K4-2-u1-X16"}],"explanation":["여러 갈래가 될 수 있어요.","다만 근거가 서야 해요.","꾸민 장치를 믿는 건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#5','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C18',3,'error','auto','「골목 끝 빨간 우체통」의 전하려는 생각을 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":5,"concept":"K4-2-u1-C18","difficulty":3,"kind":"error","stem":"「골목 끝 빨간 우체통」의 전하려는 생각을 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우체통에 넣으면 주소가 없어도 편지가 꼭 전해진다는 이야기야.」","correct":true,"mis_target":"K4-2-u1-X16"},{"t":"친구 가 — 「낯선 곳에 온 친구에게 먼저 손을 내밀자는 이야기 같아.」","mis":"K4-2-u1-X17"},{"t":"친구 나 — 「말로 하기 어려운 마음은 글로 먼저 전해 볼 수 있다는 이야기 같아.」","mis":"K4-2-u1-X17"}],"explanation":["친구 가와 나는 근거가 있어요.","친구 다는 꾸민 장치를 믿었어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#6','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C17',3,'mc','auto','움직이는 그림자처럼 꾸며 쓴 부분이 읽는 사람에게 주는 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X02','K4-2-u1-X15']::text[],false,'{"seq":6,"concept":"K4-2-u1-C17","difficulty":3,"kind":"mc","stem":"움직이는 그림자처럼 꾸며 쓴 부분이 읽는 사람에게 주는 것은 무엇인가요?","options":[{"t":"재미와 감동, 깨달음","correct":true},{"t":"이야기가 현실과 똑같다는 믿음","mis":"K4-2-u1-X01"},{"t":"고쳐야 할 거짓말","mis":"K4-2-u1-X02"},{"t":"인물의 쓸쓸함에 대한 공감만","mis":"K4-2-u1-X15"}],"explanation":["공감은 닮은 부분이 줘요.","꾸민 부분은 다른 것을 줘요.","재미와 감동, 깨달음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#7','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C15',3,'ox','auto','이야기를 나와 관련지을 때 비슷한 경험이 없으면 책이나 영상에서 본 일을 떠올려도 돼요.',ARRAY['K4-2-u1-X14']::text[],false,'{"seq":7,"concept":"K4-2-u1-C15","difficulty":3,"kind":"ox","stem":"이야기를 나와 관련지을 때 비슷한 경험이 없으면 책이나 영상에서 본 일을 떠올려도 돼요.","answer":"O","reason_options":[{"t":"간접으로 겪은 일로도 인물의 마음을 견주어 볼 수 있기 때문에","correct":true},{"t":"나와 관련짓기는 똑같은 일을 겪은 사람만 할 수 있기 때문에","mis":"K4-2-u1-X14"}],"mis":"K4-2-u1-X14","explanation":["겪지 않은 일도 있어요.","본 일도 경험이 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#8','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C16',4,'mc','auto','다음 이야기 대목에서 현실에서는 일어나기 어려운 일을 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u1-X44','K4-2-u1-X05']::text[],false,'{"seq":8,"concept":"K4-2-u1-C16","difficulty":4,"kind":"mc","stem":"다음 이야기 대목에서 현실에서는 일어나기 어려운 일을 바르게 고른 것은 무엇인가요?","options":[{"t":"아침에 심은 콩이 그날 저녁에 꼬투리를 맺어 밥에 넣은 일","correct":true},{"t":"화분에 강낭콩을 심은 일","mis":"K4-2-u1-X44"},{"t":"엄마와 함께 저녁밥을 지은 일","mis":"K4-2-u1-X44"},{"t":"말하거나 움직이는 것이 없으니 모두 실제로 있을 수 있는 일이다","mis":"K4-2-u1-X05"}],"explanation":["말하는 것은 없어요.","그런데 콩이 하루 만에 열릴까요?","평범해 보여도 현실과 달라요."],"asset":{"type":"passage","lines":["나는 아침에 마당 화분에 강낭콩 세 알을 심었다.","저녁에 화분을 보니 덩굴에 꼬투리가 주렁주렁 열려 있었다.","엄마와 나는 그 콩을 따서 저녁밥에 넣어 지었다."],"title":"이야기 한 대목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#9','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C18',4,'essay','teacher','「골목 끝 빨간 우체통」의 글쓴이가 전하려는 생각을 쓰고, 그렇게 생각한 근거를 이야기에서 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C18","difficulty":4,"kind":"essay","stem":"「골목 끝 빨간 우체통」의 글쓴이가 전하려는 생각을 쓰고, 그렇게 생각한 근거를 이야기에서 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 쓸쓸한 마음을 먼저 꺼내 보이면 곁에서 알아주는 친구를 만날 수 있다는 생각이다. 은호가 머뭇거리다 편지를 넣자 같은 마음을 가진 해린이의 답장이 왔고, 은호가 용기를 내어 먼저 말을 걸자 두 아이가 「이제부터는 우리가 직접 말할게.」라고 했기 때문이다.","scoring_points":["전하려는 생각을 썼는가","이야기 속 근거를 두 가지 찾았는가","꾸민 장치를 그대로 믿는 생각이 아닌가"]},"explanation":["생각을 한 문장으로 써요.","이야기 속 근거를 찾아요.","장치가 아니라 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L04_challenge#10','kor',4,2,'u1','L04','g4_2_kor_u1_L04_challenge','lesson_challenge','K4-2-u1-C17',4,'essay','teacher','「골목 끝 빨간 우체통」에서 현실과 닮은 부분 하나와 꾸며 쓴 부분 하나를 찾아, 각각 읽는 사람에게 무엇을 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C17","difficulty":4,"kind":"essay","stem":"「골목 끝 빨간 우체통」에서 현실과 닮은 부분 하나와 꾸며 쓴 부분 하나를 찾아, 각각 읽는 사람에게 무엇을 주는지 쓰세요.","answer_guide":{"answer":"예: 이사 와서 쉬는 시간마다 창밖만 보는 은호의 모습은 현실과 닮아, 낯선 곳에 가 본 사람이 은호 마음에 공감하게 한다. 우체통 그림자가 편지를 품고 골목을 건너가는 장면은 꾸며 쓴 부분으로, 신기한 재미를 주고 마음은 꼭 닿는다는 깨달음을 준다.","scoring_points":["현실과 닮은 부분을 찾았는가","꾸며 쓴 부분을 찾았는가","각각이 주는 것(공감 / 재미·감동·깨달음)을 썼는가"]},"explanation":["닮은 부분을 찾아요.","꾸민 부분을 찾아요.","주는 것이 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#1','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C21',1,'mc','auto','세빈이와 재희의 글은 어떤 문제를 두고 쓴 글인가요?',ARRAY['K4-2-u1-X18']::text[],false,'{"seq":1,"concept":"K4-2-u1-C21","difficulty":1,"kind":"mc","stem":"세빈이와 재희의 글은 어떤 문제를 두고 쓴 글인가요?","options":[{"t":"뒤뜰 화단에 무엇을 심을까","correct":true},{"t":"화단을 없앨까 말까","mis":"K4-2-u1-X18"},{"t":"여름 방학에 어디에 갈까","mis":"K4-2-u1-X18"},{"t":"거둔 채소를 어떻게 요리할까","mis":"K4-2-u1-X18"}],"explanation":["두 글 모두 화단 이야기예요.","무엇을 심을지 말해요.","같은 문제를 다뤄요."],"asset":{"type":"passage","lines":["뒤뜰 화단을 가꾸자는 생각에 저도 찬성해요. 다만 무엇을 심을지는 달라요.","채소는 한여름에 물을 자주 줘야 하는데, 방학에는 돌볼 사람이 없어요.","해마다 다시 피는 꽃을 심으면 봄부터 가을까지 모두가 즐길 수 있어요.","그래서 저는 화단에 꽃을 심자고 제안해요."],"title":"글 ㉯ 「화단에 꽃을 심어요」(재희)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#2','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C20',1,'mc','auto','모둠 이름을 두고 두 친구가 한 말에서 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X36']::text[],false,'{"seq":2,"concept":"K4-2-u1-C20","difficulty":1,"kind":"mc","stem":"모둠 이름을 두고 두 친구가 한 말에서 알 수 있는 것은 무엇인가요?","options":[{"t":"같은 일을 두고도 의견과 이유가 사람마다 다르다","correct":true},{"t":"둘 가운데 한 명은 틀린 의견을 냈다","mis":"K4-2-u1-X21"},{"t":"의견을 말할 때 이유는 없어도 된다","mis":"K4-2-u1-X36"},{"t":"먼저 말한 친구의 의견을 따라야 한다","mis":"K4-2-u1-X21"}],"explanation":["별빛 · 다람쥐예요.","이유도 저마다 달라요.","의견과 이유가 달라요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"우리 모둠 이름은 「별빛」이 좋겠어. 밤하늘처럼 반짝이게!"},{"who":"친구 나","text":"나는 「다람쥐」가 좋아. 부지런히 모으는 모둠이 되자고!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#3','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C22',1,'mc','auto','재희(글 ㉯)가 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":3,"concept":"K4-2-u1-C22","difficulty":1,"kind":"mc","stem":"재희(글 ㉯)가 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"방학에는 채소를 돌볼 사람이 없다","correct":true},{"t":"열매 맺는 과정을 직접 보며 배운다","mis":"K4-2-u1-X19"},{"t":"거둔 채소를 나누어 먹는다","mis":"K4-2-u1-X19"},{"t":"화단이 봄부터 비어 있다","mis":"K4-2-u1-X24"}],"explanation":["꽃을 심자는 글이에요.","세빈의 이유와 섞지 않아요.","방학 걱정이 재희의 이유예요."],"asset":{"type":"passage","lines":["뒤뜰 화단을 가꾸자는 생각에 저도 찬성해요. 다만 무엇을 심을지는 달라요.","채소는 한여름에 물을 자주 줘야 하는데, 방학에는 돌볼 사람이 없어요.","해마다 다시 피는 꽃을 심으면 봄부터 가을까지 모두가 즐길 수 있어요.","그래서 저는 화단에 꽃을 심자고 제안해요."],"title":"글 ㉯ 「화단에 꽃을 심어요」(재희)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#4','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C24',1,'ox','auto','두 글쓴이의 의견이 서로 다르면 둘 가운데 한 명은 틀린 거예요.',ARRAY['K4-2-u1-X21']::text[],false,'{"seq":4,"concept":"K4-2-u1-C24","difficulty":1,"kind":"ox","stem":"두 글쓴이의 의견이 서로 다르면 둘 가운데 한 명은 틀린 거예요.","answer":"X","reason_options":[{"t":"의견은 다를 수 있고, 이유가 알맞은지 따져 보면 되기 때문에","correct":true},{"t":"한 문제에는 맞는 의견이 하나뿐이기 때문에","mis":"K4-2-u1-X21"}],"mis":"K4-2-u1-X21","explanation":["채소도 꽃도 이유가 있어요.","다른 것과 틀린 것은 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#5','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C23',2,'mc','auto','다른 의견이 담긴 글을 비교하며 읽으면 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X21']::text[],false,'{"seq":5,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"다른 의견이 담긴 글을 비교하며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"같은 문제에 대한 여러 생각을 알 수 있다","correct":true},{"t":"더 길게 쓴 글의 의견을 따르면 된다","mis":"K4-2-u1-X20"},{"t":"나와 같은 의견만 골라 읽을 수 있다","mis":"K4-2-u1-X20"},{"t":"먼저 쓴 글이 맞는지 알 수 있다","mis":"K4-2-u1-X21"}],"explanation":["두 글을 나란히 읽어요.","새로 알게 된 것이 있어요.","여러 생각을 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#6','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C22',2,'mc','auto','세빈(글 ㉮)이 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":6,"concept":"K4-2-u1-C22","difficulty":2,"kind":"mc","stem":"세빈(글 ㉮)이 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"거둔 채소를 친구들과 나누어 먹으며 보람을 느낀다","correct":true},{"t":"방학 동안 돌볼 사람이 없어 시들기 쉽다","mis":"K4-2-u1-X19"},{"t":"꽃은 해마다 다시 핀다","mis":"K4-2-u1-X19"},{"t":"나는 채소를 심고 싶다","mis":"K4-2-u1-X24"}],"explanation":["채소를 심자는 글이에요.","그렇게 생각한 까닭을 찾아요.","나누어 먹는 보람이에요."],"asset":{"type":"passage","lines":["우리 학교 뒤뜰 화단이 봄부터 비어 있어요.","채소를 심으면 씨앗이 자라 열매를 맺는 과정을 직접 보며 배울 수 있어요.","또 거둔 채소를 반 친구들과 나누어 먹으며 기르는 보람을 느낄 수 있어요.","그래서 저는 화단에 채소를 심자고 제안해요."],"title":"글 ㉮ 「화단에 채소를 심어요」(세빈)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#7','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C24',2,'mc','auto','두 글을 읽은 친구가 「의견이 반대니까 둘 중 한 명은 틀린 거야.」라고 했어요. 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":7,"concept":"K4-2-u1-C24","difficulty":2,"kind":"mc","stem":"두 글을 읽은 친구가 「의견이 반대니까 둘 중 한 명은 틀린 거야.」라고 했어요. 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"의견은 다를 수 있어. 누가 틀렸는지보다 이유가 알맞은지 따져 보자","correct":true},{"t":"맞아. 먼저 쓴 세빈이가 맞아.","mis":"K4-2-u1-X21"},{"t":"둘 다 맞으니까 따져 볼 필요가 없어.","mis":"K4-2-u1-X22"},{"t":"둘 다 틀렸으니 아무 의견이나 정하자.","mis":"K4-2-u1-X22"}],"explanation":["두 극단을 조심해요.","틀렸다도, 따질 필요 없다도 아니에요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#8','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C25',2,'mc','auto','두 글을 읽고 새로운 의견을 낸 것은 무엇인가요?',ARRAY['K4-2-u1-X23']::text[],false,'{"seq":8,"concept":"K4-2-u1-C25","difficulty":2,"kind":"mc","stem":"두 글을 읽고 새로운 의견을 낸 것은 무엇인가요?","options":[{"t":"방학에 물을 덜 줘도 되는 키 작은 나무를 심자","correct":true},{"t":"화단에 채소를 심자","mis":"K4-2-u1-X23"},{"t":"화단에 꽃을 심자","mis":"K4-2-u1-X23"},{"t":"두 의견 가운데 하나만 골라야 하니 새 의견은 낼 수 없다","mis":"K4-2-u1-X23"}],"explanation":["채소도 꽃도 아닌 의견이에요.","두 글에 없던 생각이에요.","새 의견도 낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#9','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C21',2,'match','auto','두 글쓴이의 생각을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C21","difficulty":2,"kind":"match","stem":"두 글쓴이의 생각을 알맞게 이으세요.","pairs":[{"l":"세빈의 의견","r":"화단에 채소를 심자"},{"l":"재희의 의견","r":"화단에 꽃을 심자"},{"l":"두 사람이 같은 생각","r":"비어 있는 화단을 가꾸자"}],"mis":"K4-2-u1-X18","explanation":["의견이 갈린 곳이 있어요.","생각이 같은 곳도 있어요.","둘을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_basic#10','kor',4,2,'u1','L07','g4_2_kor_u1_L07_basic','lesson_basic','K4-2-u1-C23',3,'error','auto','두 글을 비교하며 읽은 뒤 말했어요. 좋은 점을 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X20']::text[],false,'{"seq":10,"concept":"K4-2-u1-C23","difficulty":3,"kind":"error","stem":"두 글을 비교하며 읽은 뒤 말했어요. 좋은 점을 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「길게 쓴 글이 더 공들인 글이니까 그 의견을 따르면 돼.」","correct":true,"mis_target":"K4-2-u1-X20"},{"t":"친구 가 — 「두 글을 읽고 방학 때 돌볼 사람 문제를 처음 알았어.」","mis":"K4-2-u1-X20"},{"t":"친구 다 — 「두 글을 견주어 보니 내 의견을 정하기 쉬워졌어.」","mis":"K4-2-u1-X20"}],"explanation":["여러 생각을 알았어요.","내 의견을 정했어요.","길이를 따르는 건 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#1','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C20',2,'mc','auto','같은 일을 두고 사람마다 의견이 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":1,"concept":"K4-2-u1-C20","difficulty":2,"kind":"mc","stem":"같은 일을 두고 사람마다 의견이 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"저마다 중요하게 여기는 점과 겪은 일이 다르기 때문에","correct":true},{"t":"한 사람이 문제를 잘못 알았기 때문에","mis":"K4-2-u1-X21"},{"t":"의견은 아무렇게나 정하는 것이기 때문에","mis":"K4-2-u1-X22"},{"t":"늦게 말한 사람이 따라 하지 않았기 때문에","mis":"K4-2-u1-X21"}],"explanation":["세빈은 배움을 보았어요.","재희는 방학을 걱정했어요.","보는 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#2','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C21',2,'sa','auto','세빈이와 재희의 글이 함께 다루는 학교의 장소는 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u1-C21","difficulty":2,"kind":"sa","stem":"세빈이와 재희의 글이 함께 다루는 학교의 장소는 어디인가요? 두 글자로 쓰세요.","answer":["화단"],"explanation":["뒤뜰에 있어요.","무엇을 심을지 말해요.","‘화단’이에요."],"mis":"K4-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#3','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C22',3,'mc','auto','「해마다 다시 피는 꽃을 심으면 봄부터 가을까지 모두가 즐길 수 있어요.」가 받쳐 주는 의견은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":3,"concept":"K4-2-u1-C22","difficulty":3,"kind":"mc","stem":"「해마다 다시 피는 꽃을 심으면 봄부터 가을까지 모두가 즐길 수 있어요.」가 받쳐 주는 의견은 무엇인가요?","options":[{"t":"화단에 꽃을 심자","correct":true},{"t":"화단에 채소를 심자","mis":"K4-2-u1-X19"},{"t":"화단을 가꾸지 말자","mis":"K4-2-u1-X19"},{"t":"방학에도 학교에 나오자","mis":"K4-2-u1-X19"}],"explanation":["이유는 의견을 받쳐 줘요.","꽃 이야기예요.","꽃을 심자는 의견이에요."],"asset":{"type":"passage","lines":["뒤뜰 화단을 가꾸자는 생각에 저도 찬성해요. 다만 무엇을 심을지는 달라요.","채소는 한여름에 물을 자주 줘야 하는데, 방학에는 돌볼 사람이 없어요.","해마다 다시 피는 꽃을 심으면 봄부터 가을까지 모두가 즐길 수 있어요.","그래서 저는 화단에 꽃을 심자고 제안해요."],"title":"글 ㉯ 「화단에 꽃을 심어요」(재희)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#4','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C24',3,'mc','auto','세빈이와 재희의 글을 읽은 뒤 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X22','K4-2-u1-X21','K4-2-u1-X20']::text[],false,'{"seq":4,"concept":"K4-2-u1-C24","difficulty":3,"kind":"mc","stem":"세빈이와 재희의 글을 읽은 뒤 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"두 글쓴이의 이유가 의견을 잘 받쳐 주는지 따져 본다","correct":true},{"t":"두 글 다 맞으니 그냥 넘어간다","mis":"K4-2-u1-X22"},{"t":"먼저 올라온 세빈이의 글을 따른다","mis":"K4-2-u1-X21"},{"t":"글이 더 긴 쪽을 고른다","mis":"K4-2-u1-X20"}],"explanation":["넘어가지 않아요.","먼저 · 길이로 정하지 않아요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#5','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C25',3,'mc','auto','「나는 채소 쪽이야. 방학 때 돌볼 당번을 정하면 되니까.」라고 말한 친구에 대해 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X22','K4-2-u1-X23']::text[],false,'{"seq":5,"concept":"K4-2-u1-C25","difficulty":3,"kind":"mc","stem":"「나는 채소 쪽이야. 방학 때 돌볼 당번을 정하면 되니까.」라고 말한 친구에 대해 알맞은 것은 무엇인가요?","options":[{"t":"다른 쪽 글이 걱정한 점까지 살펴 내 의견과 이유를 정했다","correct":true},{"t":"재희의 글은 틀렸다고 여겼다","mis":"K4-2-u1-X21"},{"t":"이유 없이 마음에 드는 쪽을 골랐다","mis":"K4-2-u1-X22"},{"t":"새 의견은 낼 수 없어서 하나를 골랐다","mis":"K4-2-u1-X23"}],"explanation":["재희가 걱정한 건 방학이에요.","이 친구는 당번을 말했어요.","걱정까지 살폈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#6','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C24',3,'ox','auto','두 의견이 다 맞으니 어느 쪽 이유가 더 알맞은지 따져 볼 필요가 없어요.',ARRAY['K4-2-u1-X22']::text[],false,'{"seq":6,"concept":"K4-2-u1-C24","difficulty":3,"kind":"ox","stem":"두 의견이 다 맞으니 어느 쪽 이유가 더 알맞은지 따져 볼 필요가 없어요.","answer":"X","reason_options":[{"t":"다른 의견이라도 이유가 의견을 잘 받쳐 주는지 따져 보아야 더 알맞은 의견을 찾을 수 있기 때문에","correct":true},{"t":"의견에는 맞고 틀림이 없으니 무엇이든 괜찮기 때문에","mis":"K4-2-u1-X22"}],"mis":"K4-2-u1-X22","explanation":["틀린 의견은 아니에요.","그래도 따져 볼 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#7','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C21',3,'error','auto','두 글이 다루는 문제를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X18']::text[],false,'{"seq":7,"concept":"K4-2-u1-C21","difficulty":3,"kind":"error","stem":"두 글이 다루는 문제를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「두 글은 화단을 가꿀지 말지를 두고 다투는 글이야.」","correct":true,"mis_target":"K4-2-u1-X18"},{"t":"친구 가 — 「둘 다 화단을 가꾸자는 데는 생각이 같아.」","mis":"K4-2-u1-X18"},{"t":"친구 나 — 「무엇을 심을지에서 의견이 갈렸어.」","mis":"K4-2-u1-X18"}],"explanation":["재희도 가꾸자는 데 찬성했어요.","갈린 곳은 무엇을 심을지예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#8','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C23',4,'mc','auto','다른 의견이 담긴 글을 비교하며 읽으면 좋은 점을 가장 알맞게 묶은 것은 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":8,"concept":"K4-2-u1-C23","difficulty":4,"kind":"mc","stem":"다른 의견이 담긴 글을 비교하며 읽으면 좋은 점을 가장 알맞게 묶은 것은 무엇인가요?","options":[{"t":"여러 생각을 알고, 내 의견을 정하는 데 도움을 받고, 더 알맞은 의견을 따져 볼 수 있다","correct":true},{"t":"더 긴 글을 고르고, 나와 같은 의견만 골라 읽을 수 있다","mis":"K4-2-u1-X20"},{"t":"어느 글이 틀렸는지 찾아 알려 줄 수 있다","mis":"K4-2-u1-X21"},{"t":"비교만 하면 따지지 않아도 답이 저절로 나온다","mis":"K4-2-u1-X22"}],"explanation":["하나, 여러 생각이에요.","둘, 내 의견이에요.","셋, 따져 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#9','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C24',4,'essay','teacher','세빈이와 재희의 의견 가운데 하나를 고르거나 새 의견을 내어 이유와 함께 쓰고, 고르지 않은 의견이 틀린 것이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C24","difficulty":4,"kind":"essay","stem":"세빈이와 재희의 의견 가운데 하나를 고르거나 새 의견을 내어 이유와 함께 쓰고, 고르지 않은 의견이 틀린 것이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 나는 꽃을 심자는 재희의 의견에 찬성한다. 방학 동안 채소가 시들면 애써 심은 것이 아깝기 때문이다. 하지만 세빈이의 의견도 열매 맺는 과정을 보며 배운다는 이유가 받쳐 주므로 틀린 의견이 아니다. 의견이 다른 것과 틀린 것은 다르다.","scoring_points":["의견을 고르거나 새 의견을 냈는가","의견에 맞는 이유를 썼는가","다른 의견이 틀린 것이 아닌 까닭을 썼는가"]},"explanation":["하나를 골라도 돼요.","새 의견이어도 돼요.","다른 것과 틀린 것은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L07_challenge#10','kor',4,2,'u1','L07','g4_2_kor_u1_L07_challenge','lesson_challenge','K4-2-u1-C20',4,'essay','teacher','같은 일을 두고 친구와 의견이 갈렸던 일을 떠올려(지어내도 돼요), 두 사람의 의견과 이유를 나란히 정리해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C20","difficulty":4,"kind":"essay","stem":"같은 일을 두고 친구와 의견이 갈렸던 일을 떠올려(지어내도 돼요), 두 사람의 의견과 이유를 나란히 정리해 쓰세요.","answer_guide":{"answer":"예: 학급 놀이 시간에 무엇을 할지 의견이 갈렸다. 나는 피구를 하자고 했다. 다 같이 움직일 수 있기 때문이다. 짝은 수수께끼 놀이를 하자고 했다. 비 오는 날에도 교실에서 할 수 있기 때문이다.","scoring_points":["문제 상황을 썼는가","두 사람의 의견을 각각 썼는가","의견마다 이유를 나란히 썼는가"]},"explanation":["무엇을 두고 갈렸나요?","두 사람의 의견을 써요.","이유를 나란히 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#1','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C26',1,'mc','auto','의견의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X25']::text[],false,'{"seq":1,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"의견의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 문제에 대해 글쓴이가 가진 생각","correct":true},{"t":"실제로 있었던 일","mis":"K4-2-u1-X24"},{"t":"글의 제목","mis":"K4-2-u1-X25"},{"t":"그렇게 생각한 까닭","mis":"K4-2-u1-X24"}],"explanation":["까닭은 이유예요.","있었던 일은 사실이에요.","의견은 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#2','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C26',1,'mc','auto','「비 오는 날은 좋다.」가 의견이라면, 이 의견의 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X19']::text[],false,'{"seq":2,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"「비 오는 날은 좋다.」가 의견이라면, 이 의견의 이유로 알맞은 것은 무엇인가요?","options":[{"t":"빗소리가 들려서","correct":true},{"t":"비 오는 날은 싫다","mis":"K4-2-u1-X24"},{"t":"어제 비가 왔다","mis":"K4-2-u1-X24"},{"t":"신발이 젖어서","mis":"K4-2-u1-X19"}],"explanation":["좋다고 생각한 까닭이에요.","신발이 젖는 건 싫은 까닭이에요.","빗소리가 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#3','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C27',1,'mc','auto','글 ㉮의 제목 「칭찬 스티커로 좋은 습관을 길러요」로 짐작할 수 있는 의견은 무엇인가요?',ARRAY['K4-2-u1-X25']::text[],false,'{"seq":3,"concept":"K4-2-u1-C27","difficulty":1,"kind":"mc","stem":"글 ㉮의 제목 「칭찬 스티커로 좋은 습관을 길러요」로 짐작할 수 있는 의견은 무엇인가요?","options":[{"t":"칭찬 스티커판을 계속 쓰자","correct":true},{"t":"칭찬 스티커판을 그만 쓰자","mis":"K4-2-u1-X25"},{"t":"스티커를 직접 만들자","mis":"K4-2-u1-X25"},{"t":"좋은 습관은 필요 없다","mis":"K4-2-u1-X25"}],"explanation":["「길러요」를 봐요.","스티커로 기르자는 말이에요.","계속 쓰자는 의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#4','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',1,'mc','auto','글쓴이의 의견을 확인하기 좋은 곳은 어디인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X25']::text[],false,'{"seq":4,"concept":"K4-2-u1-C28","difficulty":1,"kind":"mc","stem":"글쓴이의 의견을 확인하기 좋은 곳은 어디인가요?","options":[{"t":"글 끝부분의 「그러므로·그래서 ~해야 합니다」","correct":true},{"t":"글 맨 앞의 있었던 일","mis":"K4-2-u1-X27"},{"t":"제목만","mis":"K4-2-u1-X25"},{"t":"가장 긴 문장","mis":"K4-2-u1-X27"}],"explanation":["제목은 짐작이에요.","확인은 끝부분에서 해요.","그러므로 · 그래서를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#5','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C27',2,'mc','auto','글 ㉯의 제목 「칭찬 스티커, 꼭 필요할까요?」만 보고 「스티커가 꼭 필요하다는 글이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":5,"concept":"K4-2-u1-C27","difficulty":2,"kind":"mc","stem":"글 ㉯의 제목 「칭찬 스티커, 꼭 필요할까요?」만 보고 「스티커가 꼭 필요하다는 글이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"제목이 물음이라 제목만으로는 몰라. 글 끝에서 대답을 확인해 봐","correct":true},{"t":"맞아. 제목만 보면 의견을 다 알 수 있어.","mis":"K4-2-u1-X25"},{"t":"제목은 믿을 수 없으니 아예 보지 마.","mis":"K4-2-u1-X26"},{"t":"물음으로 된 제목은 언제나 반대 뜻이야.","mis":"K4-2-u1-X25"}],"explanation":["제목이 물음이에요.","대답은 글 끝에 있어요.","끝에서 확인해요."],"asset":{"type":"passage","lines":["칭찬 스티커는 좋은 행동을 하게 도와주는 것처럼 보입니다.","그런데 한 친구가 휴지를 줍고 나서 「스티커 주세요.」라고 했습니다.","스티커를 못 받는 날에는 줍지 않을지도 모릅니다.","또 스티커가 적은 친구는 스티커판 앞에서 속상해합니다.","좋은 습관은 누가 알아주지 않아도 스스로 하는 마음에서 자랍니다.","그래서 저는 스티커판을 그만 쓰고, 스스로 잘한 일을 적는 공책을 쓰자고 제안합니다."],"title":"글 ㉯ 「칭찬 스티커, 꼭 필요할까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#6','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',2,'mc','auto','칭찬 스티커 글 ㉯의 글쓴이의 의견은 무엇인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X25']::text[],false,'{"seq":6,"concept":"K4-2-u1-C28","difficulty":2,"kind":"mc","stem":"칭찬 스티커 글 ㉯의 글쓴이의 의견은 무엇인가요?","options":[{"t":"스티커판을 그만 쓰고 스스로 잘한 일을 적는 공책을 쓰자","correct":true},{"t":"스티커를 더 많이 주자","mis":"K4-2-u1-X27"},{"t":"떨어진 휴지는 줍지 말자","mis":"K4-2-u1-X27"},{"t":"스티커판을 계속 쓰자","mis":"K4-2-u1-X25"}],"explanation":["마지막 줄을 봐요.","「그래서 저는 ~ 제안합니다」예요.","공책을 쓰자는 의견이에요."],"asset":{"type":"passage","lines":["칭찬 스티커는 좋은 행동을 하게 도와주는 것처럼 보입니다.","그런데 한 친구가 휴지를 줍고 나서 「스티커 주세요.」라고 했습니다.","스티커를 못 받는 날에는 줍지 않을지도 모릅니다.","또 스티커가 적은 친구는 스티커판 앞에서 속상해합니다.","좋은 습관은 누가 알아주지 않아도 스스로 하는 마음에서 자랍니다.","그래서 저는 스티커판을 그만 쓰고, 스스로 잘한 일을 적는 공책을 쓰자고 제안합니다."],"title":"글 ㉯ 「칭찬 스티커, 꼭 필요할까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#7','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',2,'mc','auto','글쓴이의 의견을 파악하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":7,"concept":"K4-2-u1-C28","difficulty":2,"kind":"mc","stem":"글쓴이의 의견을 파악하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"제목으로 짐작 → 끝부분에서 확인 → 이유 찾기","correct":true},{"t":"이유 찾기 → 제목으로 짐작 → 끝부분은 건너뛰기","mis":"K4-2-u1-X27"},{"t":"제목만 읽고 끝내기","mis":"K4-2-u1-X25"},{"t":"제목은 건너뛰고 첫 줄만 읽기","mis":"K4-2-u1-X26"}],"explanation":["제목은 실마리예요.","끝부분에서 확인해요.","그다음 이유를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#8','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C29',2,'mc','auto','칭찬 스티커판을 다룬 두 글에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X18']::text[],false,'{"seq":8,"concept":"K4-2-u1-C29","difficulty":2,"kind":"mc","stem":"칭찬 스티커판을 다룬 두 글에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"한 글은 좋은 점을, 다른 글은 걱정되는 점을 크게 보았다","correct":true},{"t":"한 글쓴이가 스티커판을 잘못 보았다","mis":"K4-2-u1-X28"},{"t":"두 글 모두 좋은 점만 말했다","mis":"K4-2-u1-X28"},{"t":"두 글은 서로 다른 물건을 다루었다","mis":"K4-2-u1-X18"}],"explanation":["같은 스티커판이에요.","보는 점이 달랐어요.","좋은 점과 걱정되는 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#9','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C30',2,'mc','auto','글쓴이의 의견을 찾아 읽는 연습은 어디에서 할 수 있나요?',ARRAY['K4-2-u1-X29']::text[],false,'{"seq":9,"concept":"K4-2-u1-C30","difficulty":2,"kind":"mc","stem":"글쓴이의 의견을 찾아 읽는 연습은 어디에서 할 수 있나요?","options":[{"t":"학교 누리집 글, 학급 신문, 어린이 기사 같은 생활 속 글","correct":true},{"t":"국어 시간에 배운 글에서만","mis":"K4-2-u1-X29"},{"t":"제목이 물음인 글에서만","mis":"K4-2-u1-X29"},{"t":"옛이야기에서만","mis":"K4-2-u1-X29"}],"explanation":["생활 속 글에도 의견이 있어요.","누리집 · 신문 · 기사예요.","어디서든 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_basic#10','kor',4,2,'u1','L08','g4_2_kor_u1_L08_basic','lesson_basic','K4-2-u1-C28',3,'error','auto','글 ㉮의 의견을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X25']::text[],false,'{"seq":10,"concept":"K4-2-u1-C28","difficulty":3,"kind":"error","stem":"글 ㉮의 의견을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 나 — 「‘우리 반은 지난달부터 칭찬 스티커판을 쓰고 있습니다’가 의견이야.」","correct":true,"mis_target":"K4-2-u1-X27"},{"t":"친구 가 — 「끝 줄 ‘계속 써야 합니다’가 의견이야.」","mis":"K4-2-u1-X27"},{"t":"친구 다 — 「제목으로 짐작한 것과 끝 줄이 같은 생각이야.」","mis":"K4-2-u1-X25"}],"explanation":["첫 줄은 있었던 일이에요.","의견은 끝 줄에 있어요.","친구 나가 잘못 찾았어요."],"asset":{"type":"passage","lines":["우리 반은 지난달부터 칭찬 스티커판을 쓰고 있습니다.","스티커판을 쓰고 나서 해야 할 일을 잊지 않게 되었습니다.","오늘 무엇을 했는지 한눈에 보이기 때문입니다.","또 스티커가 한 장씩 늘 때마다 다음 일도 해 보고 싶어집니다.","그러므로 우리 반은 칭찬 스티커판을 계속 써야 합니다."],"title":"글 ㉮ 「칭찬 스티커로 좋은 습관을 길러요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#1','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C26',2,'mc','auto','다음 가운데 의견을 나타낸 문장은 무엇인가요?',ARRAY['K4-2-u1-X24']::text[],false,'{"seq":1,"concept":"K4-2-u1-C26","difficulty":2,"kind":"mc","stem":"다음 가운데 의견을 나타낸 문장은 무엇인가요?","options":[{"t":"우리 반은 칭찬 스티커판을 계속 써야 합니다.","correct":true},{"t":"우리 반은 지난달부터 칭찬 스티커판을 쓰고 있습니다.","mis":"K4-2-u1-X24"},{"t":"숙제를 해 오면 스티커를 한 장 붙입니다.","mis":"K4-2-u1-X24"},{"t":"스티커판은 교실 뒤에 붙어 있습니다.","mis":"K4-2-u1-X24"}],"explanation":["있었던 일은 사실이에요.","「~해야 합니다」를 찾아요.","그 문장이 의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#2','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C29',2,'mc','auto','글 ㉯의 글쓴이가 걱정한 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":2,"concept":"K4-2-u1-C29","difficulty":2,"kind":"mc","stem":"글 ㉯의 글쓴이가 걱정한 점으로 알맞은 것은 무엇인가요?","options":[{"t":"스티커가 적은 친구가 스티커판 앞에서 속상해한다","correct":true},{"t":"해야 할 일이 한눈에 보인다","mis":"K4-2-u1-X19"},{"t":"스티커가 늘면 다음 일도 해 보고 싶다","mis":"K4-2-u1-X19"},{"t":"스티커 색이 예쁘지 않다","mis":"K4-2-u1-X19"}],"explanation":["글 ㉯는 걱정을 말해요.","글 ㉮의 좋은 점과 섞지 않아요.","속상한 친구가 걱정이에요."],"asset":{"type":"passage","lines":["칭찬 스티커는 좋은 행동을 하게 도와주는 것처럼 보입니다.","그런데 한 친구가 휴지를 줍고 나서 「스티커 주세요.」라고 했습니다.","스티커를 못 받는 날에는 줍지 않을지도 모릅니다.","또 스티커가 적은 친구는 스티커판 앞에서 속상해합니다.","좋은 습관은 누가 알아주지 않아도 스스로 하는 마음에서 자랍니다.","그래서 저는 스티커판을 그만 쓰고, 스스로 잘한 일을 적는 공책을 쓰자고 제안합니다."],"title":"글 ㉯ 「칭찬 스티커, 꼭 필요할까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#3','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C27',3,'mc','auto','글의 제목에 대한 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":3,"concept":"K4-2-u1-C27","difficulty":3,"kind":"mc","stem":"글의 제목에 대한 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제목은 의견을 짐작하는 실마리이고, 의견은 글 끝에서 확인한다","correct":true},{"t":"제목이 곧 글쓴이의 의견이다","mis":"K4-2-u1-X25"},{"t":"제목은 틀릴 때가 있으니 읽지 않는다","mis":"K4-2-u1-X26"},{"t":"물음으로 된 제목의 글에는 의견이 없다","mis":"K4-2-u1-X25"}],"explanation":["제목은 버리지 않아요.","하지만 답도 아니에요.","실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#4','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C29',3,'match','auto','두 글과 그 글이 든 이유를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u1-C29","difficulty":3,"kind":"match","stem":"두 글과 그 글이 든 이유를 알맞게 이으세요.","pairs":[{"l":"글 ㉮ 계속 쓰자","r":"해야 할 일을 잊지 않게 된다"},{"l":"글 ㉯ 그만 쓰자","r":"스티커가 목적이 되면 스스로 하지 않을 수 있다"},{"l":"두 글이 함께 다룬 것","r":"우리 반 칭찬 스티커판"}],"mis":"K4-2-u1-X19","explanation":["누구의 이유인지 봐요.","좋은 점과 걱정되는 점이에요.","다룬 것은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#5','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C27',3,'ox','auto','물음으로 된 제목은 글쓴이의 의견과 반대 뜻이니 거꾸로 읽으면 돼요.',ARRAY['K4-2-u1-X25']::text[],false,'{"seq":5,"concept":"K4-2-u1-C27","difficulty":3,"kind":"ox","stem":"물음으로 된 제목은 글쓴이의 의견과 반대 뜻이니 거꾸로 읽으면 돼요.","answer":"X","reason_options":[{"t":"물음 제목은 거꾸로일 수도 아닐 수도 있어서 글 끝에서 대답을 확인해야 하기 때문에","correct":true},{"t":"제목만 보면 의견을 알 수 있기 때문에","mis":"K4-2-u1-X25"}],"mis":"K4-2-u1-X25","explanation":["거꾸로 읽는 것도 제목만 본 거예요.","대답은 글 끝에 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#6','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C29',3,'error','auto','칭찬 스티커판을 다룬 두 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X28']::text[],false,'{"seq":6,"concept":"K4-2-u1-C29","difficulty":3,"kind":"error","stem":"칭찬 스티커판을 다룬 두 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「글 ㉯를 쓴 사람은 스티커판의 좋은 점을 몰라서 반대한 거야.」","correct":true,"mis_target":"K4-2-u1-X28"},{"t":"친구 나 — 「글 ㉯도 스티커가 좋은 행동을 돕는 것처럼 보인다고 했어.」","mis":"K4-2-u1-X28"},{"t":"친구 다 — 「같은 스티커판인데 걱정되는 점을 더 크게 봤어.」","mis":"K4-2-u1-X28"}],"explanation":["글 ㉯ 첫 줄을 봐요.","좋은 점을 알고 있었어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["칭찬 스티커는 좋은 행동을 하게 도와주는 것처럼 보입니다.","그런데 한 친구가 휴지를 줍고 나서 「스티커 주세요.」라고 했습니다.","스티커를 못 받는 날에는 줍지 않을지도 모릅니다.","또 스티커가 적은 친구는 스티커판 앞에서 속상해합니다.","좋은 습관은 누가 알아주지 않아도 스스로 하는 마음에서 자랍니다.","그래서 저는 스티커판을 그만 쓰고, 스스로 잘한 일을 적는 공책을 쓰자고 제안합니다."],"title":"글 ㉯ 「칭찬 스티커, 꼭 필요할까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#7','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C30',3,'mc','auto','같은 문제에 대한 여러 의견을 알면 좋은 점은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":7,"concept":"K4-2-u1-C30","difficulty":3,"kind":"mc","stem":"같은 문제에 대한 여러 의견을 알면 좋은 점은 무엇인가요?","options":[{"t":"문제를 푸는 더 나은 방법을 찾을 수 있다","correct":true},{"t":"내 의견이 틀렸다는 것을 알 수 있다","mis":"K4-2-u1-X21"},{"t":"다른 의견을 이길 말을 찾을 수 있다","mis":"K4-2-u1-X21"},{"t":"내 의견을 정하지 않아도 된다","mis":"K4-2-u1-X22"}],"explanation":["스티커를 반 전체 목표로 모으자는 생각도 나왔어요.","여러 의견이 모였어요.","더 나은 방법이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#8','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C28',4,'mc','auto','이 글을 읽고 의견을 바르게 파악한 친구의 말은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X27','K4-2-u1-X26']::text[],false,'{"seq":8,"concept":"K4-2-u1-C28","difficulty":4,"kind":"mc","stem":"이 글을 읽고 의견을 바르게 파악한 친구의 말은 무엇인가요?","options":[{"t":"「제목을 보고 안 된다는 글인가 짐작했는데, 끝 줄에서 과일은 먹게 하자는 의견을 확인했어.」","correct":true},{"t":"「제목에 ‘안 될까요’가 있으니 간식을 먹지 말자는 글이야.」","mis":"K4-2-u1-X25"},{"t":"「첫 줄에 ‘먹지 않기로 했습니다’가 있으니 그게 의견이야.」","mis":"K4-2-u1-X27"},{"t":"「제목은 헷갈리니 안 보고 가운데 줄만 읽었어.」","mis":"K4-2-u1-X26"}],"explanation":["제목으로 짐작해요.","끝 줄에서 확인해요.","첫 줄은 있었던 일이에요."],"asset":{"type":"passage","lines":["우리 반은 쉬는 시간에 간식을 먹지 않기로 했습니다.","그런데 아침을 못 먹고 오는 친구는 둘째 시간쯤 배가 고파 집중하기 어렵습니다.","또 집에서 싸 온 과일은 냄새도 적고 쓰레기도 거의 나오지 않습니다.","그러므로 쉬는 시간에 집에서 싸 온 과일은 먹을 수 있게 해야 합니다."],"title":"글 「쉬는 시간 간식, 정말 안 될까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#9','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C28',4,'essay','teacher','이 글에서 글쓴이의 의견과 이유 두 가지를 찾아 쓰고, 의견을 찾은 차례를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C28","difficulty":4,"kind":"essay","stem":"이 글에서 글쓴이의 의견과 이유 두 가지를 찾아 쓰고, 의견을 찾은 차례를 쓰세요.","answer_guide":{"answer":"예: 의견은 쉬는 시간에 집에서 싸 온 과일은 먹을 수 있게 해야 한다는 것이다. 이유는 아침을 못 먹고 오는 친구가 배가 고파 집중하기 어렵다는 것과, 과일은 냄새가 적고 쓰레기도 거의 나오지 않는다는 것이다. 제목으로 먼저 짐작하고, 끝 줄의 「그러므로 ~해야 합니다」에서 의견을 확인한 뒤, 그 의견을 받쳐 주는 이유를 찾았다.","scoring_points":["의견을 찾아 썼는가","이유 두 가지를 찾아 썼는가","제목 → 끝부분 → 이유의 차례를 썼는가"]},"explanation":["끝 줄에 의견이 있어요.","가운데 두 줄이 이유예요.","찾은 차례도 써요."],"asset":{"type":"passage","lines":["우리 반은 쉬는 시간에 간식을 먹지 않기로 했습니다.","그런데 아침을 못 먹고 오는 친구는 둘째 시간쯤 배가 고파 집중하기 어렵습니다.","또 집에서 싸 온 과일은 냄새도 적고 쓰레기도 거의 나오지 않습니다.","그러므로 쉬는 시간에 집에서 싸 온 과일은 먹을 수 있게 해야 합니다."],"title":"글 「쉬는 시간 간식, 정말 안 될까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L08_challenge#10','kor',4,2,'u1','L08','g4_2_kor_u1_L08_challenge','lesson_challenge','K4-2-u1-C30',4,'essay','teacher','칭찬 스티커판에 대한 내 의견을 쓰고(두 글과 같아도, 새 의견이어도 돼요) 이유를 쓰세요. 두 글을 함께 읽은 것이 의견을 정하는 데 어떻게 도움이 되었는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C30","difficulty":4,"kind":"essay","stem":"칭찬 스티커판에 대한 내 의견을 쓰고(두 글과 같아도, 새 의견이어도 돼요) 이유를 쓰세요. 두 글을 함께 읽은 것이 의견을 정하는 데 어떻게 도움이 되었는지도 쓰세요.","answer_guide":{"answer":"예: 스티커는 두되 한 사람씩이 아니라 반 전체 목표로 모으면 좋겠다. 한 사람씩 비교되어 속상한 친구가 생기지 않고, 함께 해냈다는 즐거움도 느낄 수 있기 때문이다. 두 글을 함께 읽으니 좋은 점과 걱정되는 점을 모두 알게 되어 둘을 살리는 방법을 떠올릴 수 있었다.","scoring_points":["내 의견을 썼는가","의견에 맞는 이유를 썼는가","두 글을 함께 읽은 것이 준 도움을 썼는가"]},"explanation":["같아도 새로워도 돼요.","이유를 붙여요.","여러 의견이 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#1','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C31',1,'match','auto','의견을 말할 때 자주 쓰는 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u1-C31","difficulty":1,"kind":"match","stem":"의견을 말할 때 자주 쓰는 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"두루","r":"빠짐없이 골고루"},{"l":"배려","r":"남을 도우려고 마음을 씀"},{"l":"제안","r":"생각이나 방법을 내놓음"}],"mis":"K4-2-u1-X12","explanation":["「두루 알게 됩니다」를 떠올려요.","남을 생각하는 마음도 있어요.","내놓는 것도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#2','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C32',1,'mc','auto','의견을 평가할 때 따져 볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X30']::text[],false,'{"seq":2,"concept":"K4-2-u1-C32","difficulty":1,"kind":"mc","stem":"의견을 평가할 때 따져 볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"의견을 받쳐 주는 이유가 믿을 만한가","correct":true},{"t":"글이 얼마나 긴가","mis":"K4-2-u1-X30"},{"t":"글씨가 얼마나 예쁜가","mis":"K4-2-u1-X30"},{"t":"누가 쓴 글인가","mis":"K4-2-u1-X30"}],"explanation":["길이 · 글씨 · 글쓴이가 아니에요.","이유를 봐요.","믿을 만한지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#3','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C31',1,'blank','auto','「제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 (　) 알게 됩니다.」의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":3,"concept":"K4-2-u1-C31","difficulty":1,"kind":"blank","stem":"「제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 (　) 알게 됩니다.」의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"두루","correct":true},{"t":"배려","mis":"K4-2-u1-X12"},{"t":"제안","mis":"K4-2-u1-X12"},{"t":"혼자","mis":"K4-2-u1-X12"}],"explanation":["빠짐없이 골고루예요.","반 친구 모두를 알게 돼요.","‘두루’예요."],"asset":{"type":"passage","lines":["짝을 스스로 정하면 친한 친구끼리만 짝이 됩니다.","아직 친한 친구가 없는 사람은 끝까지 혼자 남아 마음이 상할 수 있습니다.","실제로 지난 학기에 모둠을 스스로 만들었을 때, 전학 온 친구가 끝까지 모둠을 찾지 못했습니다.","또 제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 두루 알게 됩니다.","그래서 짝은 제비뽑기로 정해야 합니다."],"title":"글 ㉯ 「짝은 제비뽑기로 정해요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#4','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C35',1,'ox','auto','이유가 많은 의견이 언제나 더 알맞은 의견이에요.',ARRAY['K4-2-u1-X33']::text[],false,'{"seq":4,"concept":"K4-2-u1-C35","difficulty":1,"kind":"ox","stem":"이유가 많은 의견이 언제나 더 알맞은 의견이에요.","answer":"X","reason_options":[{"t":"이유의 개수보다 이유가 믿을 만한지, 다른 문제는 없는지가 중요하기 때문에","correct":true},{"t":"이유가 많을수록 의견을 더 많이 받쳐 주기 때문에","mis":"K4-2-u1-X33"}],"mis":"K4-2-u1-X33","explanation":["글 ㉮는 이유가 셋이에요.","그런데 하나는 믿기 어려워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#5','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C33',2,'mc','auto','짝 정하기 글 ㉮의 이유 가운데 믿기 어려운 이유는 무엇인가요?',ARRAY['K4-2-u1-X31','K4-2-u1-X22']::text[],false,'{"seq":5,"concept":"K4-2-u1-C33","difficulty":2,"kind":"mc","stem":"짝 정하기 글 ㉮의 이유 가운데 믿기 어려운 이유는 무엇인가요?","options":[{"t":"짝을 스스로 정하면 수업 시간에 떠드는 친구가 한 명도 없을 것이다","correct":true},{"t":"마음이 맞는 친구와 짝이 되면 생각을 편하게 말할 수 있다","mis":"K4-2-u1-X31"},{"t":"스스로 고른 짝이니 서로 돕겠다는 약속을 더 잘 지키려 한다","mis":"K4-2-u1-X31"},{"t":"셋 다 믿을 만한 이유라 따질 것이 없다","mis":"K4-2-u1-X22"}],"explanation":["「한 명도」를 봐요.","짝 정하는 방법만 바꾼다고 그럴까요?","뒷받침할 까닭이 없어요."],"asset":{"type":"passage","lines":["첫째, 마음이 맞는 친구와 짝이 되면 모둠 활동에서 생각을 편하게 말할 수 있습니다.","둘째, 스스로 고른 짝이니 서로 돕겠다는 약속을 더 잘 지키려고 합니다.","셋째, 짝을 스스로 정하면 수업 시간에 떠드는 친구가 한 명도 없을 것입니다.","그러므로 짝은 우리가 스스로 정해야 합니다."],"title":"글 ㉮ 「짝은 스스로 정해요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#6','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C34',2,'mc','auto','글 ㉮의 의견대로 짝을 스스로 정하면 생길 수 있는 다른 문제는 무엇인가요?',ARRAY['K4-2-u1-X32']::text[],false,'{"seq":6,"concept":"K4-2-u1-C34","difficulty":2,"kind":"mc","stem":"글 ㉮의 의견대로 짝을 스스로 정하면 생길 수 있는 다른 문제는 무엇인가요?","options":[{"t":"친한 친구가 없는 친구가 혼자 남아 속상할 수 있다","correct":true},{"t":"공책이 모자라게 된다","mis":"K4-2-u1-X32"},{"t":"수업이 늦게 끝난다","mis":"K4-2-u1-X32"},{"t":"짝 이름을 외우기 어렵다","mis":"K4-2-u1-X32"}],"explanation":["글 ㉯가 걱정한 일이에요.","누가 어려움을 겪을까요?","혼자 남는 친구가 생겨요."],"asset":{"type":"passage","lines":["짝을 스스로 정하면 친한 친구끼리만 짝이 됩니다.","아직 친한 친구가 없는 사람은 끝까지 혼자 남아 마음이 상할 수 있습니다.","실제로 지난 학기에 모둠을 스스로 만들었을 때, 전학 온 친구가 끝까지 모둠을 찾지 못했습니다.","또 제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 두루 알게 됩니다.","그래서 짝은 제비뽑기로 정해야 합니다."],"title":"글 ㉯ 「짝은 제비뽑기로 정해요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#7','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C36',2,'mc','auto','글 ㉯에도 따져 볼 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X34','K4-2-u1-X21','K4-2-u1-X33']::text[],false,'{"seq":7,"concept":"K4-2-u1-C36","difficulty":2,"kind":"mc","stem":"글 ㉯에도 따져 볼 점으로 알맞은 것은 무엇인가요?","options":[{"t":"제비뽑기로 서로 불편한 사이가 짝이 되면 어떻게 할지","correct":true},{"t":"글 ㉯는 경험을 들었으니 따질 것이 없다","mis":"K4-2-u1-X34"},{"t":"글 ㉯는 반대쪽 글이라 읽을 필요가 없다","mis":"K4-2-u1-X21"},{"t":"글 ㉯는 이유가 둘뿐이니 틀린 의견이다","mis":"K4-2-u1-X33"}],"explanation":["글 ㉮만 따지면 공평하지 않아요.","글 ㉯도 같은 기준으로 봐요.","불편한 짝 문제가 있어요."],"asset":{"type":"passage","lines":["짝을 스스로 정하면 친한 친구끼리만 짝이 됩니다.","아직 친한 친구가 없는 사람은 끝까지 혼자 남아 마음이 상할 수 있습니다.","실제로 지난 학기에 모둠을 스스로 만들었을 때, 전학 온 친구가 끝까지 모둠을 찾지 못했습니다.","또 제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 두루 알게 됩니다.","그래서 짝은 제비뽑기로 정해야 합니다."],"title":"글 ㉯ 「짝은 제비뽑기로 정해요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#8','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C37',2,'mc','auto','두 글을 평가한 뒤 내 의견을 정할 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X35','K4-2-u1-X22']::text[],false,'{"seq":8,"concept":"K4-2-u1-C37","difficulty":2,"kind":"mc","stem":"두 글을 평가한 뒤 내 의견을 정할 때 알맞은 생각은 무엇인가요?","options":[{"t":"두 글쓴이와 같아도 달라도 되고, 이유를 함께 정한다","correct":true},{"t":"반드시 두 글 가운데 하나를 골라야 한다","mis":"K4-2-u1-X23"},{"t":"두 의견을 반씩 섞으면 저절로 가장 좋은 의견이 된다","mis":"K4-2-u1-X35"},{"t":"이유는 상관없이 마음에 드는 쪽을 고른다","mis":"K4-2-u1-X22"}],"explanation":["같아도 달라도 돼요.","섞어도 따져야 해요.","이유가 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#9','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C38',2,'mc','auto','의견을 나타내는 글에 쓰기 알맞은 표현은 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X36']::text[],false,'{"seq":9,"concept":"K4-2-u1-C38","difficulty":2,"kind":"mc","stem":"의견을 나타내는 글에 쓰기 알맞은 표현은 무엇인가요?","options":[{"t":"「~해야 한다」, 「~라고 생각한다」","correct":true},{"t":"「~했다고 한다」","mis":"K4-2-u1-X24"},{"t":"「옛날 옛적에」","mis":"K4-2-u1-X24"},{"t":"「반대! 무조건 안 돼!」","mis":"K4-2-u1-X36"}],"explanation":["있었던 일을 전하는 말이 아니에요.","외치는 말도 아니에요.","생각을 나타내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_basic#10','kor',4,2,'u1','L10','g4_2_kor_u1_L10_basic','lesson_basic','K4-2-u1-C35',3,'error','auto','짝 정하기 두 글을 평가했어요. 잘못 평가한 친구는 누구인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X31','K4-2-u1-X34']::text[],false,'{"seq":10,"concept":"K4-2-u1-C35","difficulty":3,"kind":"error","stem":"짝 정하기 두 글을 평가했어요. 잘못 평가한 친구는 누구인가요?","options":[{"t":"친구 가 — 「글 ㉮는 이유가 셋이니까 더 알맞은 의견이야.」","correct":true,"mis_target":"K4-2-u1-X33"},{"t":"친구 나 — 「글 ㉮의 셋째 이유는 뒷받침할 까닭이 없어.」","mis":"K4-2-u1-X31"},{"t":"친구 다 — 「글 ㉯의 의견도 같은 기준으로 따져 봐야 해.」","mis":"K4-2-u1-X34"}],"explanation":["개수로 정했어요.","이유의 힘을 봐야 해요.","친구 가가 잘못 평가했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#1','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C32',2,'mc','auto','의견을 평가하는 세 가지 기준을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X33']::text[],false,'{"seq":1,"concept":"K4-2-u1-C32","difficulty":2,"kind":"mc","stem":"의견을 평가하는 세 가지 기준을 바르게 묶은 것은 무엇인가요?","options":[{"t":"문제에 알맞은가 · 이유가 믿을 만한가 · 다른 문제는 없는가","correct":true},{"t":"글이 긴가 · 이유가 많은가 · 먼저 썼는가","mis":"K4-2-u1-X30"},{"t":"내 마음에 드는가 · 친한 친구 글인가 · 글씨가 바른가","mis":"K4-2-u1-X30"},{"t":"이유가 셋인가 · 제목이 물음인가 · 끝 줄이 있는가","mis":"K4-2-u1-X33"}],"explanation":["문제를 봐요.","이유를 봐요.","그 뒤에 생길 일을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#2','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C31',2,'mc','auto','「남을 도우려고 마음을 씀」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":2,"concept":"K4-2-u1-C31","difficulty":2,"kind":"mc","stem":"「남을 도우려고 마음을 씀」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"배려","correct":true},{"t":"두루","mis":"K4-2-u1-X12"},{"t":"제안","mis":"K4-2-u1-X12"},{"t":"장담","mis":"K4-2-u1-X12"}],"explanation":["남을 생각하는 마음이에요.","두루는 골고루예요.","‘배려’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#3','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C33',3,'mc','auto','체험 학습 장소 회의에서 「놀이공원이요! 그냥 제일 재미있으니까요.」라는 의견의 이유를 따지면 어떤가요?',ARRAY['K4-2-u1-X31','K4-2-u1-X22','K4-2-u1-X33']::text[],false,'{"seq":3,"concept":"K4-2-u1-C33","difficulty":3,"kind":"mc","stem":"체험 학습 장소 회의에서 「놀이공원이요! 그냥 제일 재미있으니까요.」라는 의견의 이유를 따지면 어떤가요?","options":[{"t":"「그냥 제일 재미있다」는 뒷받침할 까닭이 없어 믿기 어렵다","correct":true},{"t":"이유가 짧으니 가장 믿을 만하다","mis":"K4-2-u1-X31"},{"t":"재미있다는 이유는 누구나 좋아하니 따질 필요가 없다","mis":"K4-2-u1-X22"},{"t":"이유가 하나뿐이니 틀린 의견이다","mis":"K4-2-u1-X33"}],"explanation":["「비가 와도 괜찮다」에는 까닭이 있어요.","「그냥」은 까닭이 없어요.","믿기 어려운 이유예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"과학관에 가요! 비가 와도 괜찮으니까요."},{"who":"친구 나","text":"숲 체험장이요! 넓어서 마음껏 뛸 수 있어요."},{"who":"친구 다","text":"놀이공원이요! 그냥 제일 재미있으니까요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#4','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C34',3,'mc','auto','글 ㉯의 의견대로 제비뽑기로 짝을 정하면 생길 수 있는 다른 문제는 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X34']::text[],false,'{"seq":4,"concept":"K4-2-u1-C34","difficulty":3,"kind":"mc","stem":"글 ㉯의 의견대로 제비뽑기로 짝을 정하면 생길 수 있는 다른 문제는 무엇인가요?","options":[{"t":"서로 불편한 사이가 짝이 되어 모둠 활동이 어려울 수 있다","correct":true},{"t":"교실 책상이 모자라게 된다","mis":"K4-2-u1-X32"},{"t":"제비 뽑을 종이가 아깝다","mis":"K4-2-u1-X32"},{"t":"글 ㉯는 걱정을 말한 글이라 다른 문제가 생기지 않는다","mis":"K4-2-u1-X34"}],"explanation":["글 ㉯도 따져 봐요.","누가 어려움을 겪을까요?","불편한 짝이에요."],"asset":{"type":"passage","lines":["짝을 스스로 정하면 친한 친구끼리만 짝이 됩니다.","아직 친한 친구가 없는 사람은 끝까지 혼자 남아 마음이 상할 수 있습니다.","실제로 지난 학기에 모둠을 스스로 만들었을 때, 전학 온 친구가 끝까지 모둠을 찾지 못했습니다.","또 제비뽑기로 짝을 바꾸면 한 해 동안 반 친구들을 두루 알게 됩니다.","그래서 짝은 제비뽑기로 정해야 합니다."],"title":"글 ㉯ 「짝은 제비뽑기로 정해요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#5','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C37',3,'mc','auto','「선생님께서 친구들 이야기를 들어 보시고 짝을 정해 주셔야 한다.」는 새 의견을 두고 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X35','K4-2-u1-X23','K4-2-u1-X22']::text[],false,'{"seq":5,"concept":"K4-2-u1-C37","difficulty":3,"kind":"mc","stem":"「선생님께서 친구들 이야기를 들어 보시고 짝을 정해 주셔야 한다.」는 새 의견을 두고 알맞은 생각은 무엇인가요?","options":[{"t":"새 의견도 문제에 알맞은지, 이유가 믿을 만한지, 다른 문제는 없는지 따져 본다","correct":true},{"t":"두 의견의 좋은 점을 섞었으니 저절로 가장 좋다","mis":"K4-2-u1-X35"},{"t":"두 글쓴이와 다르니 틀린 의견이다","mis":"K4-2-u1-X23"},{"t":"선생님이 정하시니 따질 필요가 없다","mis":"K4-2-u1-X22"}],"explanation":["새 의견도 좋아요.","그래도 저절로 좋아지진 않아요.","같은 세 가지로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#6','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C36',3,'ox','auto','한쪽 의견은 따지고 다른 쪽 의견은 그냥 믿는 것은 공평한 평가가 아니에요.',ARRAY['K4-2-u1-X34']::text[],false,'{"seq":6,"concept":"K4-2-u1-C36","difficulty":3,"kind":"ox","stem":"한쪽 의견은 따지고 다른 쪽 의견은 그냥 믿는 것은 공평한 평가가 아니에요.","answer":"O","reason_options":[{"t":"어느 의견이든 같은 기준으로 따져야 하기 때문에","correct":true},{"t":"내 의견과 같은 쪽은 따지지 않아도 되기 때문에","mis":"K4-2-u1-X34"}],"mis":"K4-2-u1-X34","explanation":["글 ㉮만 따졌나요?","글 ㉯도 따져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#7','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C38',3,'error','auto','친구 글을 바꾸어 읽고 한마디씩 했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X36']::text[],false,'{"seq":7,"concept":"K4-2-u1-C38","difficulty":3,"kind":"error","stem":"친구 글을 바꾸어 읽고 한마디씩 했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「나랑 생각이 다르니까 네 글은 틀렸어.」","correct":true,"mis_target":"K4-2-u1-X36"},{"t":"친구 가 — 「의견은 나와 다르지만 둘째 이유가 경험이라 믿음이 가.」","mis":"K4-2-u1-X36"},{"t":"친구 나 — 「그 의견대로 하면 혼자 남는 친구는 어떻게 될지 궁금해.」","mis":"K4-2-u1-X36"}],"explanation":["의견이 달라도 존중해요.","이유를 중심으로 말해요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#8','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C35',4,'mc','auto','짝 정하기 두 글을 평가한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X34','K4-2-u1-X22']::text[],false,'{"seq":8,"concept":"K4-2-u1-C35","difficulty":4,"kind":"mc","stem":"짝 정하기 두 글을 평가한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"㉮의 셋째 이유는 믿기 어렵고 ㉮대로 하면 혼자 남는 친구가 생길 수 있다. ㉯도 불편한 짝 문제를 따져 보아야 한다","correct":true},{"t":"㉮가 이유가 셋이니 더 알맞다","mis":"K4-2-u1-X33"},{"t":"㉯는 경험을 들었으니 따질 것 없이 정답이다","mis":"K4-2-u1-X34"},{"t":"이유는 상관없고 마음에 드는 쪽을 고르면 된다","mis":"K4-2-u1-X22"}],"explanation":["개수를 보지 않아요.","두 글 모두 따져요.","세 가지 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#9','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C32',4,'essay','teacher','짝 정하기 두 글 가운데 하나를 골라, 세 가지 기준(문제에 알맞은가 · 이유가 믿을 만한가 · 다른 문제는 없는가)으로 평가해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C32","difficulty":4,"kind":"essay","stem":"짝 정하기 두 글 가운데 하나를 골라, 세 가지 기준(문제에 알맞은가 · 이유가 믿을 만한가 · 다른 문제는 없는가)으로 평가해 쓰세요.","answer_guide":{"answer":"예: 글 ㉯를 평가하면, 짝을 어떻게 정할지라는 문제에 알맞은 의견이다. 전학 온 친구가 모둠을 찾지 못한 경험을 들어 이유가 믿을 만하다. 다만 제비뽑기로 서로 불편한 사이가 짝이 되면 모둠 활동이 어려울 수 있다는 문제는 더 따져 보아야 한다.","scoring_points":["글을 하나 골랐는가","세 가지 기준으로 하나씩 따졌는가","고른 글에서 따져 볼 점도 찾았는가"]},"explanation":["문제를 봐요.","이유를 봐요.","생길 문제도 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L10_challenge#10','kor',4,2,'u1','L10','g4_2_kor_u1_L10_challenge','lesson_challenge','K4-2-u1-C38',4,'essay','teacher','짝을 정하는 방법에 대한 내 의견을 「~해야 한다」나 「~라고 생각한다」를 써서 쓰고, 믿을 만한 이유 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C38","difficulty":4,"kind":"essay","stem":"짝을 정하는 방법에 대한 내 의견을 「~해야 한다」나 「~라고 생각한다」를 써서 쓰고, 믿을 만한 이유 두 가지를 쓰세요.","answer_guide":{"answer":"예: 나는 한 달은 제비뽑기로, 다음 달은 스스로 정하는 방법을 번갈아 써야 한다고 생각한다. 제비뽑기 달에는 반 친구들을 두루 알게 되고, 스스로 정하는 달에는 지난달 짝이 되었던 친구 가운데서 고를 수 있어 혼자 남는 친구가 줄기 때문이다. 또 번갈아 하면 한쪽 방법의 아쉬운 점을 다른 쪽이 채워 주기 때문이다.","scoring_points":["의견을 나타내는 표현을 썼는가","이유 두 가지를 썼는가","이유가 뒷받침할 까닭이 있어 믿을 만한가"]},"explanation":["표현을 살려요.","이유는 두 가지예요.","장담하지 않고 까닭을 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#1','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C39',1,'mc','auto','재미있게 본 만화를 현실과 비교하며 소개할 때 넣으면 좋은 것은 무엇인가요?',ARRAY['K4-2-u1-X37']::text[],false,'{"seq":1,"concept":"K4-2-u1-C39","difficulty":1,"kind":"mc","stem":"재미있게 본 만화를 현실과 비교하며 소개할 때 넣으면 좋은 것은 무엇인가요?","options":[{"t":"현실과 비슷한 점과 다른 점","correct":true},{"t":"줄거리를 처음부터 끝까지 모두","mis":"K4-2-u1-X37"},{"t":"「재미있었다」 한마디만","mis":"K4-2-u1-X37"},{"t":"나오는 인물들의 키와 나이","mis":"K4-2-u1-X37"}],"explanation":["줄거리만 옮기면 안 돼요.","한마디로는 모자라요.","현실과 견준 생각을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#2','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C43',1,'mc','auto','바르게 쓴 말은 무엇인가요?',ARRAY['K4-2-u1-X39']::text[],false,'{"seq":2,"concept":"K4-2-u1-C43","difficulty":1,"kind":"mc","stem":"바르게 쓴 말은 무엇인가요?","options":[{"t":"보려고","correct":true},{"t":"볼려고","mis":"K4-2-u1-X39"},{"t":"쓸려고","mis":"K4-2-u1-X39"},{"t":"탈려고","mis":"K4-2-u1-X39"}],"explanation":["보다 · 쓰다 · 타다에는 ㄹ이 없어요.","ㄹ을 덧붙이면 틀려요.","‘보려고’가 바르게 쓴 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#3','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C44',1,'mc','auto','「그리다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":3,"concept":"K4-2-u1-C44","difficulty":1,"kind":"mc","stem":"「그리다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?","options":[{"t":"그림","correct":true},{"t":"그리음","mis":"K4-2-u1-X41"},{"t":"그릶","mis":"K4-2-u1-X41"},{"t":"그리믐","mis":"K4-2-u1-X41"}],"explanation":["받침이 없어요.","받침 없으면 ㅁ만 붙어요.","‘그림’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#4','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C45',1,'mc','auto','ㄲ 받침을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":4,"concept":"K4-2-u1-C45","difficulty":1,"kind":"mc","stem":"ㄲ 받침을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"닦다","correct":true},{"t":"닥다","mis":"K4-2-u1-X42"},{"t":"닭다","mis":"K4-2-u1-X42"},{"t":"닫다","mis":"K4-2-u1-X42"}],"explanation":["걸레로 문지르는 일이에요.","받침이 쌍받침이에요.","‘닦다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#5','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C40',2,'mc','auto','준혁이가 쓴 게시글의 의견은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":5,"concept":"K4-2-u1-C40","difficulty":2,"kind":"mc","stem":"준혁이가 쓴 게시글의 의견은 무엇인가요?","options":[{"t":"산책로에서도 자전거를 탈 수 있게 해 달라","correct":true},{"t":"찻길을 더 넓혀 달라","mis":"K4-2-u1-X19"},{"t":"표지판을 더 세워 달라","mis":"K4-2-u1-X19"},{"t":"산책로에서는 자전거를 타지 말자","mis":"K4-2-u1-X19"}],"explanation":["누가 쓴 글인지 먼저 봐요.","끝의 「~해 주세요」를 봐요.","탈 수 있게 해 달라는 의견이에요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#6','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C40',2,'match','auto','게시글과 댓글의 의견·이유를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u1-C40","difficulty":2,"kind":"match","stem":"게시글과 댓글의 의견·이유를 알맞게 이으세요.","pairs":[{"l":"준혁이의 이유","r":"찻길 옆 좁은 길에서 타야 해서 무섭다"},{"l":"현서의 의견","r":"산책로에서는 자전거를 타지 않는 것이 맞다"},{"l":"현서의 이유","r":"산책하다 자전거에 부딪힐 뻔했다"}],"mis":"K4-2-u1-X19","explanation":["누가 한 말인지 봐요.","의견과 이유를 갈라요.","세 짝을 이어요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#7','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C42',2,'mc','auto','준혁이의 글에 달 댓글로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":7,"concept":"K4-2-u1-C42","difficulty":2,"kind":"mc","stem":"준혁이의 글에 달 댓글로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「저는 현서 님 생각에 찬성해요. 산책로에는 어린 동생들도 뛰어다녀 부딪치면 크게 다칠 수 있기 때문이에요. 준혁 님이 무서운 마음도 이해해요.」","correct":true},{"t":"「반대! 자전거 타는 사람은 다 위험해요!」","mis":"K4-2-u1-X38"},{"t":"「저도요.」","mis":"K4-2-u1-X38"},{"t":"「준혁 님은 겁이 많은가 봐요.」","mis":"K4-2-u1-X38"}],"explanation":["의견이 있나요?","이유가 있나요?","존중하는 말투인가요?"],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#8','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C43',2,'mc','auto','「놀다」에 「-려고」를 붙인 말로 바른 것은 무엇인가요?',ARRAY['K4-2-u1-X40','K4-2-u1-X39']::text[],false,'{"seq":8,"concept":"K4-2-u1-C43","difficulty":2,"kind":"mc","stem":"「놀다」에 「-려고」를 붙인 말로 바른 것은 무엇인가요?","options":[{"t":"놀려고","correct":true},{"t":"노려고","mis":"K4-2-u1-X40"},{"t":"놀을려고","mis":"K4-2-u1-X39"},{"t":"놀으려고","mis":"K4-2-u1-X40"}],"explanation":["놀다에는 ㄹ이 원래 있어요.","ㄹ을 빼지 않아요.","‘놀려고’가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#9','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C44',2,'mc','auto','「믿다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":9,"concept":"K4-2-u1-C44","difficulty":2,"kind":"mc","stem":"「믿다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?","options":[{"t":"믿음","correct":true},{"t":"밈","mis":"K4-2-u1-X41"},{"t":"믿움","mis":"K4-2-u1-X41"},{"t":"믿기","mis":"K4-2-u1-X41"}],"explanation":["받침이 있어요.","받침 있으면 ‘음’이 붙어요.","‘믿음’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_basic#10','kor',4,2,'u1','L12','g4_2_kor_u1_L12_basic','lesson_basic','K4-2-u1-C41',3,'error','auto','준혁이와 현서의 의견을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u1-X28']::text[],false,'{"seq":10,"concept":"K4-2-u1-C41","difficulty":3,"kind":"error","stem":"준혁이와 현서의 의견을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「현서는 자전거를 타 본 적이 없어서 반대하는 거야.」","correct":true,"mis_target":"K4-2-u1-X28"},{"t":"친구 가 — 「둘 다 안전을 걱정하는데, 걱정하는 사람이 달라.」","mis":"K4-2-u1-X28"},{"t":"친구 다 — 「둘 다 직접 겪은 일을 이유로 들었어.」","mis":"K4-2-u1-X28"}],"explanation":["현서는 부딪힐 뻔한 일을 말했어요.","모르고 반대한 게 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#1','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C44',2,'mc','auto','「베풀다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":1,"concept":"K4-2-u1-C44","difficulty":2,"kind":"mc","stem":"「베풀다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?","options":[{"t":"베풂","correct":true},{"t":"베품","mis":"K4-2-u1-X41"},{"t":"베풀음","mis":"K4-2-u1-X41"},{"t":"베플음","mis":"K4-2-u1-X41"}],"explanation":["받침이 ㄹ이에요.","ㄹ에 ㅁ이 붙으면 ㄻ이에요.","‘베풂’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#2','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C45',2,'mc','auto','ㅆ 받침을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":2,"concept":"K4-2-u1-C45","difficulty":2,"kind":"mc","stem":"ㅆ 받침을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"왔다","correct":true},{"t":"왓다","mis":"K4-2-u1-X42"},{"t":"와따","mis":"K4-2-u1-X42"},{"t":"왇다","mis":"K4-2-u1-X42"}],"explanation":["소리가 [왇따]여도요.","쌍받침 그대로 써요.","‘왔다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#3','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C39',3,'mc','auto','친구들이 만화를 소개했어요. 이 단원에서 배운 대로 가장 알맞게 소개한 것은 무엇인가요?',ARRAY['K4-2-u1-X37','K4-2-u1-X02']::text[],false,'{"seq":3,"concept":"K4-2-u1-C39","difficulty":3,"kind":"mc","stem":"친구들이 만화를 소개했어요. 이 단원에서 배운 대로 가장 알맞게 소개한 것은 무엇인가요?","options":[{"t":"「제가 본 만화에서는 구름이 편지를 나르는데, 현실에서는 사람이 편지를 전해요. 그 장면 덕분에 멀리 있는 사람에게 마음을 전하는 일이 소중하게 느껴졌어요.」","correct":true},{"t":"「주인공이 집을 나와서 구름을 만나고, 편지를 나르고, 다시 집에 돌아와요.」","mis":"K4-2-u1-X37"},{"t":"「정말 재미있었어요. 꼭 보세요.」","mis":"K4-2-u1-X37"},{"t":"「현실과 달라서 거짓말 만화예요.」","mis":"K4-2-u1-X02"}],"explanation":["비슷한 점과 다른 점이 있나요?","꾸민 부분이 준 것이 있나요?","현실과 견준 소개를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#4','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C43',3,'mc','auto','「-려고」를 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u1-X39','K4-2-u1-X40']::text[],false,'{"seq":4,"concept":"K4-2-u1-C43","difficulty":3,"kind":"mc","stem":"「-려고」를 바르게 쓴 문장은 무엇인가요?","options":[{"t":"동생과 놀려고 마당으로 나섰다.","correct":true},{"t":"물을 마실려고 컵을 꺼냈다.","mis":"K4-2-u1-X39"},{"t":"편지를 쓸려고 종이를 꺼냈다.","mis":"K4-2-u1-X39"},{"t":"그림을 만드려고 풀을 샀다.","mis":"K4-2-u1-X40"}],"explanation":["마시다 · 쓰다에는 ㄹ이 없어요.","만들다에는 ㄹ이 있어요.","놀다도 ㄹ이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#5','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C43',3,'error','auto','친구가 글에서 「-려고」를 고쳐 썼어요. 잘못 고친 것은 무엇인가요?',ARRAY['K4-2-u1-X40','K4-2-u1-X39']::text[],false,'{"seq":5,"concept":"K4-2-u1-C43","difficulty":3,"kind":"error","stem":"친구가 글에서 「-려고」를 고쳐 썼어요. 잘못 고친 것은 무엇인가요?","options":[{"t":"놀려고 → 노려고","correct":true,"mis_target":"K4-2-u1-X40"},{"t":"볼려고 → 보려고","mis":"K4-2-u1-X39"},{"t":"탈려고 → 타려고","mis":"K4-2-u1-X39"}],"explanation":["보다 · 타다는 ㄹ을 빼야 맞아요.","놀다는 ㄹ이 원래 있어요.","‘놀려고’는 고치면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#6','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C42',3,'mc','auto','「반대! 자전거 타는 사람은 다 위험해요!」라는 댓글을 고쳐 쓸 때 더해야 할 것은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":6,"concept":"K4-2-u1-C42","difficulty":3,"kind":"mc","stem":"「반대! 자전거 타는 사람은 다 위험해요!」라는 댓글을 고쳐 쓸 때 더해야 할 것은 무엇인가요?","options":[{"t":"의견을 받쳐 주는 이유와 다른 사람을 존중하는 말","correct":true},{"t":"느낌표를 더 많이","mis":"K4-2-u1-X38"},{"t":"「저도요」 한마디","mis":"K4-2-u1-X38"},{"t":"자전거 타는 사람의 이름","mis":"K4-2-u1-X38"}],"explanation":["의견만 외쳤어요.","이유가 없어요.","존중하는 말도 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#7','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C41',3,'ox','auto','준혁이와 현서는 둘 다 안전을 걱정하지만 걱정하는 사람이 달라요.',ARRAY['K4-2-u1-X28']::text[],false,'{"seq":7,"concept":"K4-2-u1-C41","difficulty":3,"kind":"ox","stem":"준혁이와 현서는 둘 다 안전을 걱정하지만 걱정하는 사람이 달라요.","answer":"O","reason_options":[{"t":"준혁이는 자전거 타는 어린이의 안전을, 현서는 걷는 사람의 안전을 걱정했기 때문에","correct":true},{"t":"현서만 안전을 걱정하고 준혁이는 재미만 생각했기 때문에","mis":"K4-2-u1-X28"}],"mis":"K4-2-u1-X28","explanation":["준혁이는 찻길이 무서워요.","현서는 부딪힐 뻔했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#8','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C41',4,'mc','auto','준혁이의 의견대로만 하면 생길 수 있는 문제는 무엇인가요?',ARRAY['K4-2-u1-X32']::text[],false,'{"seq":8,"concept":"K4-2-u1-C41","difficulty":4,"kind":"mc","stem":"준혁이의 의견대로만 하면 생길 수 있는 문제는 무엇인가요?","options":[{"t":"걷는 사람이 많은 산책로에서 자전거와 부딪칠 수 있다","correct":true},{"t":"표지판을 하나 더 세워야 한다","mis":"K4-2-u1-X32"},{"t":"준혁이가 찻길에서 더 자주 탄다","mis":"K4-2-u1-X32"},{"t":"현서가 산책을 더 많이 한다","mis":"K4-2-u1-X32"}],"explanation":["현서가 걱정한 일이에요.","한쪽 의견대로만 하면요?","다른 쪽 걱정이 남아요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#9','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C42',4,'essay','teacher','준혁이의 게시글에 달 내 댓글을 쓰세요. 의견과 이유가 드러나고 두 사람을 존중하는 말이 들어가게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u1-C42","difficulty":4,"kind":"essay","stem":"준혁이의 게시글에 달 내 댓글을 쓰세요. 의견과 이유가 드러나고 두 사람을 존중하는 말이 들어가게 쓰세요.","answer_guide":{"answer":"예: 저는 산책로 옆에 자전거 길을 따로 그어 주면 좋겠다고 생각해요. 걷는 사람과 자전거가 다니는 곳이 나뉘면 서로 부딪칠 일이 줄기 때문이에요. 찻길이 무서운 준혁 님 마음도, 부딪힐 뻔해 놀란 현서 님 마음도 이해해요.","scoring_points":["의견을 썼는가","의견을 받쳐 주는 이유를 썼는가","두 사람을 존중하는 말을 썼는가"]},"explanation":["내 의견을 써요.","이유를 붙여요.","존중하는 말을 더해요."],"asset":{"type":"passage","lines":["준혁 — 공원 산책로에 「자전거 금지」 표지판이 생겼습니다.","이제 찻길 옆 좁은 길에서 자전거를 타야 해서 무섭습니다.","어린이들이 안전하게 탈 수 있도록 산책로에서도 자전거를 타게 해 주세요.","댓글 현서 — 저는 생각이 달라요. 지난주 할머니와 산책하다가","뒤에서 달려온 자전거에 부딪힐 뻔했어요.","걷는 사람이 많은 산책로에서는 자전거를 타지 않는 것이 맞다고 생각해요."],"title":"동네 소식판 「공원 산책로에서 자전거를 탈 수 있게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_L12_challenge#10','kor',4,2,'u1','L12','g4_2_kor_u1_L12_challenge','lesson_challenge','K4-2-u1-C39',4,'essay','teacher','재미있게 본 만화나 이야기를 하나 골라(지어내도 돼요) 현실과 비슷한 점과 다른 점, 꾸며 쓴 부분이 준 재미나 깨달음이 드러나게 소개하세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u1-C39","difficulty":4,"kind":"essay","stem":"재미있게 본 만화나 이야기를 하나 골라(지어내도 돼요) 현실과 비슷한 점과 다른 점, 꾸며 쓴 부분이 준 재미나 깨달음이 드러나게 소개하세요.","answer_guide":{"answer":"예: 제가 소개할 이야기는 밤마다 신발장 속 신발들이 하루 동안 다닌 길을 이야기하는 이야기입니다. 신발이 하루 종일 우리와 함께 걷는 것은 현실과 비슷하지만, 신발이 말을 하는 것은 다릅니다. 신발들의 이야기를 들으니 매일 쓰는 물건도 소중히 다뤄야겠다는 생각이 들었습니다.","scoring_points":["작품을 밝혔는가","현실과 비슷한 점과 다른 점을 썼는가","꾸며 쓴 부분이 준 재미나 깨달음을 썼는가"]},"explanation":["줄거리를 다 옮기지 않아요.","현실과 견줘요.","준 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#1','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C1',1,'mc','auto','이 단원에서 나란히 놓고 비교한 두 가지는 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X33','K4-2-u1-X02']::text[],false,'{"seq":1,"concept":"K4-2-u1-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 나란히 놓고 비교한 두 가지는 무엇인가요?","options":[{"t":"작품과 현실 · 서로 다른 의견","correct":true},{"t":"작품과 줄거리 · 같은 의견끼리","mis":"K4-2-u1-X20"},{"t":"제목과 끝 줄 · 이유의 개수","mis":"K4-2-u1-X33"},{"t":"꾸민 부분과 거짓말 · 먼저 쓴 의견과 나중 의견","mis":"K4-2-u1-X02"}],"explanation":["하나는 작품과 현실이에요.","하나는 서로 다른 의견이에요.","나란히 놓고 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#2','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C4',1,'mc','auto','친구와 같은 시를 읽고 마음에 남은 장면이 달랐어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X03','K4-2-u1-X04']::text[],false,'{"seq":2,"concept":"K4-2-u1-C4","difficulty":1,"kind":"mc","stem":"친구와 같은 시를 읽고 마음에 남은 장면이 달랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"둘 다 까닭이 있으면 저마다의 감상이다","correct":true},{"t":"둘 중 하나는 잘못 읽었다","mis":"K4-2-u1-X03"},{"t":"선생님께 정답 장면을 여쭤보아 하나로 정한다","mis":"K4-2-u1-X03"},{"t":"까닭 없이 아무 장면이나 말해도 된다","mis":"K4-2-u1-X04"}],"explanation":["겪은 일이 달라요.","그래서 남는 곳도 달라요.","까닭과 함께 말하면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#3','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C12',1,'mc','auto','「골목 끝 빨간 우체통」에서 은호에게 답장을 보낸 사람은 누구인가요?',ARRAY['K4-2-u1-X11','K4-2-u1-X16']::text[],false,'{"seq":3,"concept":"K4-2-u1-C12","difficulty":1,"kind":"mc","stem":"「골목 끝 빨간 우체통」에서 은호에게 답장을 보낸 사람은 누구인가요?","options":[{"t":"해린","correct":true},{"t":"건우","mis":"K4-2-u1-X11"},{"t":"할머니","mis":"K4-2-u1-X11"},{"t":"빨간 우체통","mis":"K4-2-u1-X16"}],"explanation":["은행잎 그림을 떠올려요.","짝의 필통에 있었어요.","해린이에요."],"asset":{"type":"passage","lines":["다음 날 아침, 은호의 창틀에 하늘색 편지 한 장이 놓여 있었다.","「나도 이 동네가 아직 낯설어. 쉬는 시간에 창밖을 보는 건 나도 똑같아.」","편지 끝에는 이름 대신 작은 은행잎이 그려져 있었다.","어느 날 은호는 짝 해린이의 필통에 똑같은 은행잎 그림을 보았다.","은호는 교실 뒤에서 한참 서성이다가 용기를 내어 말했다. 「혹시…… 너니?」","해린이도 지난봄에 이사를 왔던 것이다.","두 아이는 함께 마지막 편지를 넣었다. 「이제부터는 우리가 직접 말할게.」"],"title":"이야기 「골목 끝 빨간 우체통」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#4','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C21',1,'mc','auto','아침 독서 두 글은 어떤 문제를 두고 쓴 글인가요?',ARRAY['K4-2-u1-X18']::text[],false,'{"seq":4,"concept":"K4-2-u1-C21","difficulty":1,"kind":"mc","stem":"아침 독서 두 글은 어떤 문제를 두고 쓴 글인가요?","options":[{"t":"아침 독서 시간에 만화책을 읽어도 될까","correct":true},{"t":"쉬는 시간을 늘릴까","mis":"K4-2-u1-X18"},{"t":"받아쓰기를 언제 볼까","mis":"K4-2-u1-X18"},{"t":"만화책을 살까 말까","mis":"K4-2-u1-X18"}],"explanation":["두 글 모두 아침 독서 시간이에요.","만화책이 나와요.","읽어도 될지를 다뤄요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#5','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C28',1,'mc','auto','글 ㉮에서 글쓴이의 의견이 드러난 줄은 몇 번 줄인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X24']::text[],false,'{"seq":5,"concept":"K4-2-u1-C28","difficulty":1,"kind":"mc","stem":"글 ㉮에서 글쓴이의 의견이 드러난 줄은 몇 번 줄인가요?","options":[{"t":"5번 줄","correct":true},{"t":"1번 줄","mis":"K4-2-u1-X27"},{"t":"2번 줄","mis":"K4-2-u1-X24"},{"t":"4번 줄","mis":"K4-2-u1-X24"}],"explanation":["1번 줄은 있었던 일이에요.","2~4번 줄은 이유예요.","「그러므로」로 시작하는 줄이에요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#6','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C32',1,'mc','auto','「그 의견대로 했을 때 다른 문제가 생기지 않는가?」는 무엇을 하는 물음인가요?',ARRAY['K4-2-u1-X30','K4-2-u1-X33']::text[],false,'{"seq":6,"concept":"K4-2-u1-C32","difficulty":1,"kind":"mc","stem":"「그 의견대로 했을 때 다른 문제가 생기지 않는가?」는 무엇을 하는 물음인가요?","options":[{"t":"의견을 평가하는 기준","correct":true},{"t":"제목을 짓는 방법","mis":"K4-2-u1-X30"},{"t":"글의 길이를 재는 방법","mis":"K4-2-u1-X30"},{"t":"이유의 개수를 세는 방법","mis":"K4-2-u1-X33"}],"explanation":["의견을 따져 보는 물음이에요.","세 가지 가운데 하나예요.","평가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#7','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C42',1,'mc','auto','게시판에 댓글을 쓸 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":7,"concept":"K4-2-u1-C42","difficulty":1,"kind":"mc","stem":"게시판에 댓글을 쓸 때 알맞은 것은 무엇인가요?","options":[{"t":"의견과 이유를 쓰고 다른 사람을 존중하는 말투로 쓴다","correct":true},{"t":"반대 의견에는 「틀렸어요!」라고만 쓴다","mis":"K4-2-u1-X38"},{"t":"「저도요」 한마디만 쓴다","mis":"K4-2-u1-X38"},{"t":"글쓴이를 깎아내리는 말을 쓴다","mis":"K4-2-u1-X38"}],"explanation":["의견이 있어야 해요.","이유가 있어야 해요.","존중하는 말투예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#8','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C43',1,'mc','auto','「-려고」를 바르게 쓴 말은 무엇인가요?',ARRAY['K4-2-u1-X40','K4-2-u1-X39']::text[],false,'{"seq":8,"concept":"K4-2-u1-C43","difficulty":1,"kind":"mc","stem":"「-려고」를 바르게 쓴 말은 무엇인가요?","options":[{"t":"만들려고","correct":true},{"t":"만드려고","mis":"K4-2-u1-X40"},{"t":"쓸려고","mis":"K4-2-u1-X39"},{"t":"볼려고","mis":"K4-2-u1-X39"}],"explanation":["만들다에는 ㄹ이 있어요.","쓰다 · 보다에는 ㄹ이 없어요.","‘만들려고’가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#9','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C16',2,'mc','auto','「할머니의 사과나무」에서 말하거나 움직이는 것은 없지만 현실에서는 일어나기 어려운 일은 무엇인가요?',ARRAY['K4-2-u1-X44','K4-2-u1-X05']::text[],false,'{"seq":9,"concept":"K4-2-u1-C16","difficulty":2,"kind":"mc","stem":"「할머니의 사과나무」에서 말하거나 움직이는 것은 없지만 현실에서는 일어나기 어려운 일은 무엇인가요?","options":[{"t":"아침에 심은 씨가 하루 만에 사과가 열린 나무가 된 일","correct":true},{"t":"할머니가 무릎이 아파 마당에 잘 나오지 않으신 일","mis":"K4-2-u1-X44"},{"t":"사과를 반으로 갈라 나누어 먹은 일","mis":"K4-2-u1-X44"},{"t":"말하는 것이 없으니 모두 실제로 있을 수 있는 일이다","mis":"K4-2-u1-X05"}],"explanation":["말하는 것은 없어요.","그런데 씨가 하루 만에 자랄까요?","평범해 보여도 현실과 달라요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#10','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C18',2,'mc','auto','「할머니의 사과나무」의 글쓴이가 전하려는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":10,"concept":"K4-2-u1-C18","difficulty":2,"kind":"mc","stem":"「할머니의 사과나무」의 글쓴이가 전하려는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"마음을 담아 나누면 함께 더 행복해진다","correct":true},{"t":"씨를 심으면 하루 만에 열매를 얻을 수 있다","mis":"K4-2-u1-X16"},{"t":"맛있는 것은 혼자 먹어야 더 맛있다","mis":"K4-2-u1-X17"},{"t":"아픈 사람은 혼자 쉬게 두어야 한다","mis":"K4-2-u1-X17"}],"explanation":["5번 줄 할머니 말을 봐요.","6번 줄도 봐요.","나누니 웃으셨어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#11','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C7',2,'mc','auto','「느림보 신호등」과 현실을 바르게 견준 것은 무엇인가요?',ARRAY['K4-2-u1-X07']::text[],false,'{"seq":11,"concept":"K4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「느림보 신호등」과 현실을 바르게 견준 것은 무엇인가요?","options":[{"t":"시 — 초록불이 할머니를 기다린다 / 현실 — 초록불은 정해진 시간이 지나면 바뀐다","correct":true},{"t":"시 — 신호등이 말을 한다 / 현실 — 자동차는 정지선에서 멈춘다","mis":"K4-2-u1-X07"},{"t":"시 — 자동차가 하품한다 / 현실 — 할머니는 지팡이를 짚는다","mis":"K4-2-u1-X07"},{"t":"시 — 할머니가 천천히 건넌다 / 현실 — 신호등은 말을 한다","mis":"K4-2-u1-X07"}],"explanation":["같은 대상끼리 견줘요.","초록불은 초록불끼리예요.","현실의 모습도 맞아야 해요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#12','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C14',2,'mc','auto','「할머니의 사과나무」에서 「나」의 말과 행동으로 짐작할 수 있는 성격은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"「할머니의 사과나무」에서 「나」의 말과 행동으로 짐작할 수 있는 성격은 무엇인가요?","options":[{"t":"할머니를 생각해 마음을 쓰는 다정한 성격","correct":true},{"t":"혼자 있기를 좋아하는 성격","mis":"K4-2-u1-X13"},{"t":"사과를 싫어하는 성격","mis":"K4-2-u1-X13"},{"t":"학교에 자주 늦는 성격","mis":"K4-2-u1-X13"}],"explanation":["씨를 심었어요.","사과를 가져다 드렸어요.","할머니를 생각했어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#13','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C22',2,'mc','auto','글 ㉯의 글쓴이가 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X25']::text[],false,'{"seq":13,"concept":"K4-2-u1-C22","difficulty":2,"kind":"mc","stem":"글 ㉯의 글쓴이가 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"만화책을 본 친구들이 그림만 넘기다 금방 다 보았다","correct":true},{"t":"책 읽기를 싫어하던 짝도 만화책은 끝까지 읽었다","mis":"K4-2-u1-X19"},{"t":"그림과 글을 함께 따라가며 흐름을 익힌다","mis":"K4-2-u1-X19"},{"t":"아침 독서 시간에 무엇이든 읽어도 된다","mis":"K4-2-u1-X25"}],"explanation":["글 ㉮의 이유와 섞지 않아요.","2·3번 줄이에요.","그림만 넘긴 일이에요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#14','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C27',2,'mc','auto','글 ㉯의 제목만 보고 「무엇이든 읽어도 괜찮다는 글이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":14,"concept":"K4-2-u1-C27","difficulty":2,"kind":"mc","stem":"글 ㉯의 제목만 보고 「무엇이든 읽어도 괜찮다는 글이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"물음 제목은 실마리야. 끝 줄에서 글쓴이의 대답을 확인해 봐","correct":true},{"t":"맞아. 제목에 괜찮다고 했어.","mis":"K4-2-u1-X25"},{"t":"제목은 헷갈리니 안 읽는 게 좋아.","mis":"K4-2-u1-X26"},{"t":"물음 제목은 언제나 의견과 거꾸로야.","mis":"K4-2-u1-X25"}],"explanation":["제목은 물음이에요.","대답은 끝 줄에 있어요.","끝에서 확인해요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#15','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C33',2,'mc','auto','아침 독서 글 ㉮의 이유 가운데 믿기 어려운 이유는 무엇인가요?',ARRAY['K4-2-u1-X31','K4-2-u1-X22']::text[],false,'{"seq":15,"concept":"K4-2-u1-C33","difficulty":2,"kind":"mc","stem":"아침 독서 글 ㉮의 이유 가운데 믿기 어려운 이유는 무엇인가요?","options":[{"t":"만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것이다","correct":true},{"t":"책 읽기를 싫어하던 짝도 만화책은 끝까지 읽었다","mis":"K4-2-u1-X31"},{"t":"그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있다","mis":"K4-2-u1-X31"},{"t":"셋 다 믿을 만하니 따질 것이 없다","mis":"K4-2-u1-X22"}],"explanation":["「모두」·「백 점」을 봐요.","뒷받침할 까닭이 있나요?","믿기 어려운 이유예요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#16','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C40',2,'mc','auto','하율이가 쓴 게시글의 의견은 무엇인가요?',ARRAY['K4-2-u1-X19']::text[],false,'{"seq":16,"concept":"K4-2-u1-C40","difficulty":2,"kind":"mc","stem":"하율이가 쓴 게시글의 의견은 무엇인가요?","options":[{"t":"밤 아홉 시가 지나면 정자 불을 꺼 달라","correct":true},{"t":"정자 불을 더 밝게 해 달라","mis":"K4-2-u1-X19"},{"t":"정자 옆길을 넓혀 달라","mis":"K4-2-u1-X19"},{"t":"정자 불은 켜 두어야 한다","mis":"K4-2-u1-X19"}],"explanation":["하율이 글이에요.","「~해 주세요」를 봐요.","꺼 달라는 의견이에요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#17','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C8',3,'mc','auto','「할머니의 사과나무」에서 할머니가 사과를 반으로 갈라 주시는 장면은 어떻게 보는 것이 알맞나요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X44']::text[],false,'{"seq":17,"concept":"K4-2-u1-C8","difficulty":3,"kind":"mc","stem":"「할머니의 사과나무」에서 할머니가 사과를 반으로 갈라 주시는 장면은 어떻게 보는 것이 알맞나요?","options":[{"t":"현실에도 있을 법한 모습이지만, 글쓴이가 나누는 마음을 보여 주려고 골라 지은 장면이다","correct":true},{"t":"말하는 것이 아니니 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"이야기는 다 꾸민 것이라 따질 필요가 없다","mis":"K4-2-u1-X06"},{"t":"할머니가 사과를 나누는 일은 현실에서 일어날 수 없다","mis":"K4-2-u1-X44"}],"explanation":["현실에도 있을 법해요.","그래도 글쓴이가 지은 장면이에요.","나누는 마음을 보여 줘요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#18','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C18',3,'mc','auto','친구들이 「할머니의 사과나무」의 전하려는 생각을 서로 다르게 말했을 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X17','K4-2-u1-X16']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"친구들이 「할머니의 사과나무」의 전하려는 생각을 서로 다르게 말했을 때 알맞은 생각은 무엇인가요?","options":[{"t":"이야기 속 근거를 댈 수 있으면 서로 달라도 받아들일 수 있다","correct":true},{"t":"맨 처음 말한 친구의 생각이 정답이다","mis":"K4-2-u1-X17"},{"t":"사과나무가 하루 만에 자란다는 생각도 3번 줄이 근거이니 알맞다","mis":"K4-2-u1-X16"},{"t":"근거 없이 떠오르는 대로 말해도 다 알맞다","mis":"K4-2-u1-X17"}],"explanation":["여러 갈래가 될 수 있어요.","근거가 서야 해요.","꾸민 장치를 믿는 건 아니에요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#19','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C35',3,'mc','auto','「㉮는 이유가 셋, ㉯는 둘이니 ㉮가 더 알맞아.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X22','K4-2-u1-X21']::text[],false,'{"seq":19,"concept":"K4-2-u1-C35","difficulty":3,"kind":"mc","stem":"「㉮는 이유가 셋, ㉯는 둘이니 ㉮가 더 알맞아.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「㉮에는 4번 줄처럼 믿기 어려운 이유가 섞여 있어. 개수보다 이유가 믿을 만한지 따져 봐.」","correct":true},{"t":"「맞아. 이유가 많을수록 좋은 의견이야.」","mis":"K4-2-u1-X33"},{"t":"「이유는 상관없어. 마음에 드는 쪽을 고르면 돼.」","mis":"K4-2-u1-X22"},{"t":"「㉯가 나중에 나왔으니 ㉯가 맞아.」","mis":"K4-2-u1-X21"}],"explanation":["개수가 아니에요.","마음에 드는 쪽도 아니에요.","이유의 힘을 봐요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#20','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C28',3,'mc','auto','「쉬는 시간 간식, 정말 안 될까요?」에서 의견을 찾는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X27','K4-2-u1-X26']::text[],false,'{"seq":20,"concept":"K4-2-u1-C28","difficulty":3,"kind":"mc","stem":"「쉬는 시간 간식, 정말 안 될까요?」에서 의견을 찾는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"제목으로 짐작하고 → 끝 줄 「그러므로 ~해야 합니다」에서 확인하고 → 가운데 두 줄에서 이유를 찾는다","correct":true},{"t":"제목의 「안 될까요」를 보고 먹지 말자는 의견으로 정한다","mis":"K4-2-u1-X25"},{"t":"첫 줄을 의견으로 보고 끝 줄은 읽지 않는다","mis":"K4-2-u1-X27"},{"t":"제목은 건너뛰고 아무 줄이나 의견으로 고른다","mis":"K4-2-u1-X26"}],"explanation":["제목은 짐작이에요.","끝 줄에서 확인해요.","가운데에 이유가 있어요."],"asset":{"type":"passage","lines":["우리 반은 쉬는 시간에 간식을 먹지 않기로 했습니다.","그런데 아침을 못 먹고 오는 친구는 둘째 시간쯤 배가 고파 집중하기 어렵습니다.","또 집에서 싸 온 과일은 냄새도 적고 쓰레기도 거의 나오지 않습니다.","그러므로 쉬는 시간에 집에서 싸 온 과일은 먹을 수 있게 해야 합니다."],"title":"글 「쉬는 시간 간식, 정말 안 될까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#21','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C37',3,'mc','auto','「아침 독서 시간에 글이 많은 책 반, 만화책 반을 읽자.」는 섞은 의견을 두고 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u1-X35','K4-2-u1-X23','K4-2-u1-X36']::text[],false,'{"seq":21,"concept":"K4-2-u1-C37","difficulty":3,"kind":"mc","stem":"「아침 독서 시간에 글이 많은 책 반, 만화책 반을 읽자.」는 섞은 의견을 두고 알맞은 생각은 무엇인가요?","options":[{"t":"섞은 의견도 문제에 알맞은지, 이유가 믿을 만한지, 다른 문제는 없는지 따져 본다","correct":true},{"t":"두 의견을 반씩 섞었으니 저절로 가장 좋다","mis":"K4-2-u1-X35"},{"t":"두 글쓴이와 다르니 낼 수 없는 의견이다","mis":"K4-2-u1-X23"},{"t":"섞은 의견은 이유가 없어도 된다","mis":"K4-2-u1-X36"}],"explanation":["섞어도 돼요.","저절로 좋아지진 않아요.","같은 기준으로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#22','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C10',3,'mc','auto','「할머니의 사과나무」의 한 부분을 바꾸어 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X09','K4-2-u1-X02']::text[],false,'{"seq":22,"concept":"K4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「할머니의 사과나무」의 한 부분을 바꾸어 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 견주어 본 뒤 「할머니와 함께 씨를 심고 싹이 트기를 기다렸다」처럼 바꾸고 바꾼 까닭을 말한다","correct":true},{"t":"「사과」를 아무 낱말로나 바꾼다","mis":"K4-2-u1-X09"},{"t":"꾸민 부분을 모두 지워 현실과 똑같이 만든다","mis":"K4-2-u1-X02"},{"t":"이야기를 그대로 외워 옮겨 쓴다","mis":"K4-2-u1-X09"}],"explanation":["현실과 견줘요.","바라는 모습을 상상해요.","까닭도 말해요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#23','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C18',4,'mc','auto','「할머니의 사과나무」를 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X17']::text[],false,'{"seq":23,"concept":"K4-2-u1-C18","difficulty":4,"kind":"mc","stem":"「할머니의 사과나무」를 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「하루 만에 자란 나무는 꾸민 거지만, 그 덕분에 할머니를 웃게 하고 싶은 마음이 크게 느껴져. 함께 나누면 더 행복해진다는 이야기 같아.」","correct":true},{"t":"「말하는 게 없으니 다 진짜 일이고, 사과 씨는 하루면 자라.」","mis":"K4-2-u1-X05"},{"t":"「꾸며 쓴 이야기라 생각할 거리가 없어.」","mis":"K4-2-u1-X06"},{"t":"「사과는 아껴서 혼자 먹으라는 이야기야.」","mis":"K4-2-u1-X17"}],"explanation":["꾸민 부분을 알아봐요.","그 까닭을 생각해요.","근거 있는 생각을 골라요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#24','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C16',4,'essay','teacher','「할머니의 사과나무」에서 말하거나 움직이는 것이 아닌데도 현실에서 일어나기 어려운 일을 찾아 그 까닭을 쓰고, 현실과 닮은 부분도 하나 찾아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C16","difficulty":4,"kind":"essay","stem":"「할머니의 사과나무」에서 말하거나 움직이는 것이 아닌데도 현실에서 일어나기 어려운 일을 찾아 그 까닭을 쓰고, 현실과 닮은 부분도 하나 찾아 쓰세요.","answer_guide":{"answer":"예: 아침에 심은 사과 씨가 학교에 다녀온 사이 내 키만 한 나무가 되어 사과가 열린 일이다. 말하거나 움직이는 것은 아니지만, 실제로 사과나무는 씨를 심고 여러 해가 지나야 열매를 맺기 때문에 하루 만에는 일어날 수 없다. 무릎이 아프신 할머니가 마당에 잘 나오지 않으시는 모습은 현실과 닮았다.","scoring_points":["현실에서 일어나기 어려운 일을 찾았는가","현실의 규칙이나 경험과 견주어 까닭을 썼는가","현실과 닮은 부분을 찾았는가"]},"explanation":["말하는 것이 없어도 찾아요.","현실과 견주어요.","닮은 부분도 찾아요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_a#25','kor',4,2,'u1','','g4_2_kor_u1_review_a','unit_review','K4-2-u1-C39',4,'essay','teacher','「할머니의 사과나무」를 친구에게 소개하는 글을 쓰세요. 현실과 비슷한 점과 다른 점, 꾸며 쓴 부분이 준 재미나 깨달음이 드러나게 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C39","difficulty":4,"kind":"essay","stem":"「할머니의 사과나무」를 친구에게 소개하는 글을 쓰세요. 현실과 비슷한 점과 다른 점, 꾸며 쓴 부분이 준 재미나 깨달음이 드러나게 쓰세요.","answer_guide":{"answer":"예: 제가 소개할 이야기는 「할머니의 사과나무」입니다. 무릎이 아프신 할머니를 생각하는 손주의 마음은 현실과 비슷하지만, 아침에 심은 씨가 하루 만에 사과가 열린 나무가 되는 것은 현실과 다릅니다. 이 꾸며 쓴 장면 덕분에 할머니를 웃게 하고 싶은 마음이 얼마나 큰지 느낄 수 있었습니다.","scoring_points":["작품 제목을 밝혔는가","현실과 비슷한 점과 다른 점을 썼는가","꾸며 쓴 부분이 준 재미나 깨달음을 썼는가"]},"explanation":["줄거리를 다 옮기지 않아요.","현실과 견줘요.","꾸민 부분이 준 것을 써요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#1','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C2',1,'mc','auto','「할머니의 사과나무」에서 현실과 비슷한 부분은 무엇인가요?',ARRAY['K4-2-u1-X01']::text[],false,'{"seq":1,"concept":"K4-2-u1-C2","difficulty":1,"kind":"mc","stem":"「할머니의 사과나무」에서 현실과 비슷한 부분은 무엇인가요?","options":[{"t":"무릎이 아프신 할머니가 마당에 잘 나오지 않으시는 모습","correct":true},{"t":"학교에 다녀오는 사이 나무가 내 키만큼 자란 일","mis":"K4-2-u1-X01"},{"t":"하루 만에 빨간 사과가 열린 일","mis":"K4-2-u1-X01"},{"t":"아침에 심은 씨가 저녁에 나무가 된 일","mis":"K4-2-u1-X01"}],"explanation":["우리 동네에서도 볼 수 있나요?","하루 만에 자라는 나무는 없어요.","할머니 모습이 현실과 닮았어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#2','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C5',1,'mc','auto','「할머니의 사과나무」에서 인상 깊은 장면을 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u1-X04']::text[],false,'{"seq":2,"concept":"K4-2-u1-C5","difficulty":1,"kind":"mc","stem":"「할머니의 사과나무」에서 인상 깊은 장면을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「사과를 반으로 갈라 주시는 장면이 인상 깊어. 나도 할머니와 나눠 먹은 일이 떠올랐거든.」","correct":true},{"t":"「사과 장면.」","mis":"K4-2-u1-X04"},{"t":"「할머니가 강아지와 산책하는 장면이 인상 깊어.」","mis":"K4-2-u1-X04"},{"t":"「이 이야기는 백 점짜리야.」","mis":"K4-2-u1-X04"}],"explanation":["이야기 속 장면이어야 해요.","까닭이 있어야 해요.","둘 다 있는 말을 골라요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#3','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C13',1,'blank','auto','「은호는 교실 뒤에서 한참 (　) 용기를 내어 말했다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":3,"concept":"K4-2-u1-C13","difficulty":1,"kind":"blank","stem":"「은호는 교실 뒤에서 한참 (　) 용기를 내어 말했다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"서성이다가","correct":true},{"t":"낯설다가","mis":"K4-2-u1-X12"},{"t":"나누다가","mis":"K4-2-u1-X12"},{"t":"뛰어놀다가","mis":"K4-2-u1-X12"}],"explanation":["왔다 갔다 했어요.","한곳에 머물지 않았어요.","서성이다가예요."],"asset":{"type":"passage","lines":["다음 날 아침, 은호의 창틀에 하늘색 편지 한 장이 놓여 있었다.","「나도 이 동네가 아직 낯설어. 쉬는 시간에 창밖을 보는 건 나도 똑같아.」","편지 끝에는 이름 대신 작은 은행잎이 그려져 있었다.","어느 날 은호는 짝 해린이의 필통에 똑같은 은행잎 그림을 보았다.","은호는 교실 뒤에서 한참 서성이다가 용기를 내어 말했다. 「혹시…… 너니?」","해린이도 지난봄에 이사를 왔던 것이다.","두 아이는 함께 마지막 편지를 넣었다. 「이제부터는 우리가 직접 말할게.」"],"title":"이야기 「골목 끝 빨간 우체통」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#4','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C20',1,'mc','auto','아침 독서 두 글의 글쓴이에 대해 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X36','K4-2-u1-X18']::text[],false,'{"seq":4,"concept":"K4-2-u1-C20","difficulty":1,"kind":"mc","stem":"아침 독서 두 글의 글쓴이에 대해 알맞은 것은 무엇인가요?","options":[{"t":"같은 문제를 두고 의견과 이유가 다르다","correct":true},{"t":"한 글쓴이는 문제를 잘못 알았다","mis":"K4-2-u1-X21"},{"t":"두 글쓴이 모두 이유를 쓰지 않았다","mis":"K4-2-u1-X36"},{"t":"두 글은 서로 다른 문제를 다룬다","mis":"K4-2-u1-X18"}],"explanation":["문제는 같아요.","의견이 달라요.","이유도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#5','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C26',1,'mc','auto','「아침 독서 시간에 만화책도 읽게 해야 합니다.」는 의견, 이유, 있었던 일 가운데 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X25']::text[],false,'{"seq":5,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"「아침 독서 시간에 만화책도 읽게 해야 합니다.」는 의견, 이유, 있었던 일 가운데 무엇인가요?","options":[{"t":"의견","correct":true},{"t":"이유","mis":"K4-2-u1-X24"},{"t":"있었던 일","mis":"K4-2-u1-X24"},{"t":"제목","mis":"K4-2-u1-X25"}],"explanation":["글쓴이의 생각이에요.","「~해야 합니다」예요.","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#6','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C31',1,'mc','auto','「생각이나 방법을 내놓음」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":6,"concept":"K4-2-u1-C31","difficulty":1,"kind":"mc","stem":"「생각이나 방법을 내놓음」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"제안","correct":true},{"t":"배려","mis":"K4-2-u1-X12"},{"t":"두루","mis":"K4-2-u1-X12"},{"t":"대답","mis":"K4-2-u1-X12"}],"explanation":["「~자고 제안해요」를 떠올려요.","내놓는 일이에요.","‘제안’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#7','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C39',1,'mc','auto','작품을 소개할 때 꾸며 쓴 부분에 대해 말하면 좋은 것은 무엇인가요?',ARRAY['K4-2-u1-X02','K4-2-u1-X37']::text[],false,'{"seq":7,"concept":"K4-2-u1-C39","difficulty":1,"kind":"mc","stem":"작품을 소개할 때 꾸며 쓴 부분에 대해 말하면 좋은 것은 무엇인가요?","options":[{"t":"그 부분이 준 재미나 깨달음","correct":true},{"t":"그 부분이 거짓말이라는 것","mis":"K4-2-u1-X02"},{"t":"그 부분의 글자 수","mis":"K4-2-u1-X37"},{"t":"그 부분을 빼고 다시 쓴 줄거리","mis":"K4-2-u1-X37"}],"explanation":["꾸민 부분은 잘못이 아니에요.","무엇을 주었나요?","재미나 깨달음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#8','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C44',1,'mc','auto','「만들다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":8,"concept":"K4-2-u1-C44","difficulty":1,"kind":"mc","stem":"「만들다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?","options":[{"t":"만듦","correct":true},{"t":"만듬","mis":"K4-2-u1-X41"},{"t":"만들음","mis":"K4-2-u1-X41"},{"t":"만드름","mis":"K4-2-u1-X41"}],"explanation":["받침이 ㄹ이에요.","ㄹ에 ㅁ이 붙으면 ㄻ이에요.","‘만듦’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#9','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C8',2,'mc','auto','「사과나무 이야기에는 말하는 게 없으니 다 진짜 있었던 일이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":9,"concept":"K4-2-u1-C8","difficulty":2,"kind":"mc","stem":"「사과나무 이야기에는 말하는 게 없으니 다 진짜 있었던 일이야.」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「하루 만에 열매가 맺힌 것처럼 평범해 보여도 현실과 다른 일이 있어. 이야기 전체가 글쓴이가 지은 거야.」","correct":true},{"t":"「맞아. 말하는 게 없으면 다 진짜야.」","mis":"K4-2-u1-X05"},{"t":"「이야기는 다 꾸민 거라 견줄 필요가 없어.」","mis":"K4-2-u1-X06"},{"t":"「사과나무가 정말 하루 만에 자랄 수도 있어.」","mis":"K4-2-u1-X01"}],"explanation":["말하는 것만 꾸민 게 아니에요.","하루 만에 자란 나무가 있어요.","이야기 전체를 글쓴이가 지었어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#10','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C17',2,'mc','auto','할머니가 무릎이 아프신 것처럼 현실과 닮은 부분은 읽는 사람에게 무엇을 주나요?',ARRAY['K4-2-u1-X15','K4-2-u1-X02','K4-2-u1-X01']::text[],false,'{"seq":10,"concept":"K4-2-u1-C17","difficulty":2,"kind":"mc","stem":"할머니가 무릎이 아프신 것처럼 현실과 닮은 부분은 읽는 사람에게 무엇을 주나요?","options":[{"t":"읽는 사람이 인물의 마음에 공감하게 한다","correct":true},{"t":"신기한 재미만 준다","mis":"K4-2-u1-X15"},{"t":"이야기가 거짓임을 알려 준다","mis":"K4-2-u1-X02"},{"t":"이야기가 실제로 있었던 일임을 알려 준다","mis":"K4-2-u1-X01"}],"explanation":["아픈 가족을 본 적이 있나요?","그 마음을 알 것 같아요.","공감하게 돼요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#11','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C9',2,'mc','auto','「뛰지 않아도 되는 길」이라는 말로 알 수 있는 말하는 이의 바람은 무엇인가요?',ARRAY['K4-2-u1-X08']::text[],false,'{"seq":11,"concept":"K4-2-u1-C9","difficulty":2,"kind":"mc","stem":"「뛰지 않아도 되는 길」이라는 말로 알 수 있는 말하는 이의 바람은 무엇인가요?","options":[{"t":"누구나 서두르지 않고 안전하게 건너는 길","correct":true},{"t":"달리기 연습을 할 수 있는 길","mis":"K4-2-u1-X08"},{"t":"자동차만 다니는 길","mis":"K4-2-u1-X08"},{"t":"신호등이 없는 길","mis":"K4-2-u1-X08"}],"explanation":["뛰지 않아도 돼요.","서두르지 않아도 돼요.","안전하게 건너는 길이에요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#12','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C15',2,'ox','auto','할머니와 함께 산 적이 없으면 「할머니의 사과나무」를 나와 관련지을 수 없어요.',ARRAY['K4-2-u1-X14']::text[],false,'{"seq":12,"concept":"K4-2-u1-C15","difficulty":2,"kind":"ox","stem":"할머니와 함께 산 적이 없으면 「할머니의 사과나무」를 나와 관련지을 수 없어요.","answer":"X","reason_options":[{"t":"아픈 가족을 도운 일이나 책·영상에서 본 일을 떠올려 견줄 수 있기 때문에","correct":true},{"t":"인물과 똑같은 일을 겪어야 관련지을 수 있기 때문에","mis":"K4-2-u1-X14"}],"mis":"K4-2-u1-X14","explanation":["비슷한 일이면 돼요.","본 일도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#13','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C22',2,'match','auto','아침 독서 두 글과 그 글이 든 이유를 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K4-2-u1-C22","difficulty":2,"kind":"match","stem":"아침 독서 두 글과 그 글이 든 이유를 알맞게 이으세요.","pairs":[{"l":"글 ㉮ 만화책도 읽자","r":"그림과 글을 함께 따라가며 흐름을 익힌다"},{"l":"글 ㉯ 아침엔 글이 많은 책","r":"키득거리는 소리에 옆 친구가 집중하기 어렵다"},{"l":"두 글이 함께 다룬 것","r":"아침 독서 시간의 만화책"}],"mis":"K4-2-u1-X19","explanation":["누구의 이유인지 봐요.","의견을 받쳐 주는지 봐요.","다룬 것은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#14','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C29',2,'mc','auto','아침 독서 두 글이 만화책을 다르게 본 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X18']::text[],false,'{"seq":14,"concept":"K4-2-u1-C29","difficulty":2,"kind":"mc","stem":"아침 독서 두 글이 만화책을 다르게 본 점으로 알맞은 것은 무엇인가요?","options":[{"t":"㉮는 책을 펴게 하는 좋은 점을, ㉯는 집중을 흐트러뜨리는 걱정되는 점을 크게 보았다","correct":true},{"t":"㉯를 쓴 사람은 만화책을 읽어 본 적이 없다","mis":"K4-2-u1-X28"},{"t":"두 글 모두 만화책의 좋은 점만 말했다","mis":"K4-2-u1-X28"},{"t":"두 글은 서로 다른 시간을 다루었다","mis":"K4-2-u1-X18"}],"explanation":["같은 만화책이에요.","보는 점이 달라요.","좋은 점 · 걱정되는 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#15','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C34',2,'mc','auto','글 ㉯의 의견대로 하면 생길 수 있는 다른 문제는 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X34']::text[],false,'{"seq":15,"concept":"K4-2-u1-C34","difficulty":2,"kind":"mc","stem":"글 ㉯의 의견대로 하면 생길 수 있는 다른 문제는 무엇인가요?","options":[{"t":"만화책으로 책과 친해지던 친구가 아침 독서 시간을 더 지루해할 수 있다","correct":true},{"t":"교실에 책장이 모자라게 된다","mis":"K4-2-u1-X32"},{"t":"만화책 값이 오른다","mis":"K4-2-u1-X32"},{"t":"글 ㉯는 걱정을 말한 글이라 다른 문제가 생기지 않는다","mis":"K4-2-u1-X34"}],"explanation":["글 ㉮의 첫째 이유를 떠올려요.","누가 어려움을 겪을까요?","책과 멀어지는 친구예요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#16','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C40',2,'mc','auto','도하가 댓글에서 든 이유는 무엇인가요?',ARRAY['K4-2-u1-X19','K4-2-u1-X24']::text[],false,'{"seq":16,"concept":"K4-2-u1-C40","difficulty":2,"kind":"mc","stem":"도하가 댓글에서 든 이유는 무엇인가요?","options":[{"t":"불이 꺼진 날 길이 어두워 넘어질 뻔했다","correct":true},{"t":"창으로 빛이 들어와 동생이 깊이 잠들지 못한다","mis":"K4-2-u1-X19"},{"t":"정자 불은 켜 두어야 한다","mis":"K4-2-u1-X24"},{"t":"정자 바로 옆 집에 산다","mis":"K4-2-u1-X19"}],"explanation":["도하의 말이에요.","의견과 이유를 갈라요.","넘어질 뻔한 일이 이유예요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#17','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C16',3,'error','auto','「할머니의 사과나무」에서 현실에서 일어나기 어려운 일을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K4-2-u1-X44','K4-2-u1-X05']::text[],false,'{"seq":17,"concept":"K4-2-u1-C16","difficulty":3,"kind":"error","stem":"「할머니의 사과나무」에서 현실에서 일어나기 어려운 일을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 가 — 「할머니가 오랜만에 소리 내어 웃으신 일」","correct":true,"mis_target":"K4-2-u1-X44"},{"t":"친구 나 — 「아침에 심은 씨가 저녁에 내 키만 한 나무가 된 일」","mis":"K4-2-u1-X05"},{"t":"친구 다 — 「하루 만에 빨간 사과가 열린 일」","mis":"K4-2-u1-X05"}],"explanation":["웃으시는 건 흔한 일이에요.","하루 만에 자란 나무는 아니에요.","친구 가가 잘못 찾았어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#18','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C18',3,'mc','auto','「아픈 사람 곁에서 마음을 나누면 힘이 된다」는 생각의 근거로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"mc","stem":"「아픈 사람 곁에서 마음을 나누면 힘이 된다」는 생각의 근거로 가장 알맞은 것은 무엇인가요?","options":[{"t":"5·6번 줄 — 사과를 나누자 할머니가 오랜만에 소리 내어 웃으셨다","correct":true},{"t":"3번 줄 — 씨를 심은 자리에 하루 만에 나무가 섰다","mis":"K4-2-u1-X16"},{"t":"4번 줄 — 사과 하나를 땄다","mis":"K4-2-u1-X17"},{"t":"2번 줄 — 아침에 마당에 씨를 심었다","mis":"K4-2-u1-X17"}],"explanation":["마음을 나눈 줄을 찾아요.","그 뒤에 무슨 일이 있었나요?","할머니가 웃으셨어요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#19','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C24',3,'mc','auto','서로 다른 의견을 비교할 때 바른 태도는 무엇인가요?',ARRAY['K4-2-u1-X21','K4-2-u1-X43','K4-2-u1-X22']::text[],false,'{"seq":19,"concept":"K4-2-u1-C24","difficulty":3,"kind":"mc","stem":"서로 다른 의견을 비교할 때 바른 태도는 무엇인가요?","options":[{"t":"다른 의견을 틀렸다고 하지 않되, 이유가 알맞은지는 꼭 따져 본다","correct":true},{"t":"다른 의견은 틀린 의견이니 듣지 않는다","mis":"K4-2-u1-X21"},{"t":"다툼이 생기지 않게 무조건 친구 의견을 따른다","mis":"K4-2-u1-X43"},{"t":"의견은 다 맞으니 따질 필요가 없다","mis":"K4-2-u1-X22"}],"explanation":["틀렸다고 하지 않아요.","그냥 따르지도 않아요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#20','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C27',3,'mc','auto','글 ㉯의 제목과 의견의 관계로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X26']::text[],false,'{"seq":20,"concept":"K4-2-u1-C27","difficulty":3,"kind":"mc","stem":"글 ㉯의 제목과 의견의 관계로 알맞은 것은 무엇인가요?","options":[{"t":"제목은 「무엇이든 괜찮을지」 묻고, 끝 줄에서 「아침에는 글이 많은 책」이라고 대답한다","correct":true},{"t":"제목이 곧 의견이라 무엇이든 괜찮다는 글이다","mis":"K4-2-u1-X25"},{"t":"물음 제목은 의견이 없다는 뜻이다","mis":"K4-2-u1-X25"},{"t":"제목은 의견과 상관없으니 볼 필요가 없다","mis":"K4-2-u1-X26"}],"explanation":["제목은 물음이에요.","대답은 끝 줄이에요.","둘을 이어 봐요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#21','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C38',3,'mc','auto','의견을 나타내는 글로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X36','K4-2-u1-X24']::text[],false,'{"seq":21,"concept":"K4-2-u1-C38","difficulty":3,"kind":"mc","stem":"의견을 나타내는 글로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「저는 아침 독서 시간에 만화책도 읽게 해야 한다고 생각합니다. 책을 멀리하던 친구도 책을 펴게 되기 때문입니다.」","correct":true},{"t":"「만화책 최고! 무조건 읽게 해 주세요!」","mis":"K4-2-u1-X36"},{"t":"「어제 짝이 만화책을 읽었다고 합니다.」","mis":"K4-2-u1-X24"},{"t":"「만화책을 반대하는 친구는 틀렸습니다.」","mis":"K4-2-u1-X36"}],"explanation":["의견을 나타내는 표현이 있나요?","이유가 있나요?","다른 의견을 깎아내리지 않나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#22','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C11',3,'mc','auto','「느림보 신호등」과 현실을 견주어 본 친구가 얻은 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X10','K4-2-u1-X06','K4-2-u1-X01']::text[],false,'{"seq":22,"concept":"K4-2-u1-C11","difficulty":3,"kind":"mc","stem":"「느림보 신호등」과 현실을 견주어 본 친구가 얻은 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「우리 동네 건널목도 초록불이 짧은지 살펴보게 됐어.」","correct":true},{"t":"「시가 현실과 달라서 틀린 곳을 찾았어.」","mis":"K4-2-u1-X10"},{"t":"「시는 꾸민 거라 견주어 볼 게 없었어.」","mis":"K4-2-u1-X06"},{"t":"「시가 실제로 있었던 일인지 확인했어.」","mis":"K4-2-u1-X01"}],"explanation":["틀린 곳 찾기가 아니에요.","현실을 되돌아봐요.","우리 동네가 새로 보여요."],"asset":{"type":"passage","lines":["우리 동네 네거리에는 / 느림보 신호등이 산다","할머니가 지팡이를 짚고 / 한 걸음, 또 한 걸음 / 건너기 시작하면","초록 눈을 끔벅끔벅 / 「천천히 오세요」 / 빨간 눈은 꾹 참고 기다린다","책가방 멘 나도 / 숨 고르며 걷는다 / 뛰지 않아도 되는 길","자동차들도 부릉부릉 대신 / 하품하며 기다리는 / 느긋한 우리 동네"],"title":"동시 「느림보 신호등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#23','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C32',4,'mc','auto','아침 독서 두 글을 세 가지 기준으로 평가한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X34','K4-2-u1-X30']::text[],false,'{"seq":23,"concept":"K4-2-u1-C32","difficulty":4,"kind":"mc","stem":"아침 독서 두 글을 세 가지 기준으로 평가한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 문제에 알맞다. ㉮의 4번 줄은 믿기 어렵다. ㉮대로 하면 집중이 흐트러질 수 있고, ㉯대로 하면 책을 멀리하는 친구가 생길 수 있다","correct":true},{"t":"㉮가 이유가 많으니 더 알맞다","mis":"K4-2-u1-X33"},{"t":"㉯는 경험을 들었으니 따질 것이 없다","mis":"K4-2-u1-X34"},{"t":"글이 더 긴 ㉯가 더 알맞다","mis":"K4-2-u1-X30"}],"explanation":["문제에 알맞은가요?","이유가 믿을 만한가요?","다른 문제는 없나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#24','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C18',4,'essay','teacher','「할머니의 사과나무」의 글쓴이가 전하려는 생각을 쓰고, 그렇게 생각한 근거를 이야기에서 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C18","difficulty":4,"kind":"essay","stem":"「할머니의 사과나무」의 글쓴이가 전하려는 생각을 쓰고, 그렇게 생각한 근거를 이야기에서 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 마음을 담아 나누면 함께 더 행복해진다는 생각이다. 할머니가 사과를 반으로 갈라 「같이 먹으니 더 달구나.」라고 하셨고, 무릎이 아파 마당에도 잘 나오지 않으시던 할머니가 오랜만에 소리 내어 웃으셨기 때문이다.","scoring_points":["전하려는 생각을 썼는가","이야기 속 근거를 두 가지 찾았는가","꾸민 장치를 그대로 믿는 생각이 아닌가"]},"explanation":["생각을 한 문장으로 써요.","근거는 이야기 속에서요.","장치가 아니라 마음이에요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_b#25','kor',4,2,'u1','','g4_2_kor_u1_review_b','unit_review','K4-2-u1-C37',4,'essay','teacher','아침 독서 시간의 만화책에 대한 내 의견을 쓰세요(두 글과 같아도, 새 의견이어도 돼요). 믿을 만한 이유 두 가지와, 내 의견대로 했을 때 생길 수 있는 문제와 그 대책도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C37","difficulty":4,"kind":"essay","stem":"아침 독서 시간의 만화책에 대한 내 의견을 쓰세요(두 글과 같아도, 새 의견이어도 돼요). 믿을 만한 이유 두 가지와, 내 의견대로 했을 때 생길 수 있는 문제와 그 대책도 쓰세요.","answer_guide":{"answer":"예: 나는 아침 독서 시간에 만화책도 읽되, 다 읽은 뒤 느낀 점을 한 줄 쓰게 해야 한다고 생각한다. 책을 멀리하던 친구도 책을 펴게 되고, 느낀 점을 쓰면 그림만 넘기는 일이 줄기 때문이다. 다만 키득거리는 소리가 날 수 있으니 만화책을 읽는 자리를 교실 한쪽에 따로 두면 좋겠다.","scoring_points":["내 의견을 썼는가","믿을 만한 이유 두 가지를 썼는가","내 의견에서 생길 문제와 대책을 썼는가"]},"explanation":["같아도 새로워도 돼요.","이유는 두 가지예요.","내 의견도 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#1','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C3',1,'ox','auto','현실과 다르게 꾸며 쓴 부분이 있는 이야기는 거짓말 이야기예요.',ARRAY['K4-2-u1-X02']::text[],false,'{"seq":1,"concept":"K4-2-u1-C3","difficulty":1,"kind":"ox","stem":"현실과 다르게 꾸며 쓴 부분이 있는 이야기는 거짓말 이야기예요.","answer":"X","reason_options":[{"t":"꾸며 쓴 부분은 글쓴이가 생각과 마음을 전하는 방법이기 때문에","correct":true},{"t":"현실과 다른 일을 쓰면 모두 거짓이기 때문에","mis":"K4-2-u1-X02"}],"mis":"K4-2-u1-X02","explanation":["꾸민 부분에는 까닭이 있어요.","재미와 마음을 전해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#2','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C4',1,'ox','auto','다현이와 채이는 아이의 선택을 두고 생각이 달랐으니 한 명은 잘못 읽은 거예요.',ARRAY['K4-2-u1-X03']::text[],false,'{"seq":2,"concept":"K4-2-u1-C4","difficulty":1,"kind":"ox","stem":"다현이와 채이는 아이의 선택을 두고 생각이 달랐으니 한 명은 잘못 읽은 거예요.","answer":"X","reason_options":[{"t":"같은 장면도 사람마다 다르게 생각할 수 있고 둘 다 까닭을 말했기 때문에","correct":true},{"t":"이야기마다 정해진 생각이 하나뿐이기 때문에","mis":"K4-2-u1-X03"}],"mis":"K4-2-u1-X03","explanation":["다현이는 드린 게 좋았대요.","채이는 함께 열었으면 했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"다현","text":"하나뿐인 바닷바람을 아저씨께 드린 건 정말 따뜻한 선택이야."},{"who":"채이","text":"나는 아저씨와 같이 열어서 둘 다 시원했으면 더 좋았을 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#3','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C12',1,'mc','auto','「골목 끝 빨간 우체통」의 처음에 일어난 일은 무엇인가요?',ARRAY['K4-2-u1-X11']::text[],false,'{"seq":3,"concept":"K4-2-u1-C12","difficulty":1,"kind":"mc","stem":"「골목 끝 빨간 우체통」의 처음에 일어난 일은 무엇인가요?","options":[{"t":"이사 온 은호가 친구에게 말을 걸지 못했다","correct":true},{"t":"은호가 해린이에게 먼저 말을 걸었다","mis":"K4-2-u1-X11"},{"t":"창틀에 하늘색 편지가 놓였다","mis":"K4-2-u1-X11"},{"t":"두 아이가 마지막 편지를 넣었다","mis":"K4-2-u1-X11"}],"explanation":["처음 · 가운데 · 끝이에요.","처음엔 창밖만 보았어요.","말을 걸지 못했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#4','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C24',1,'ox','auto','아침 독서 두 글은 의견이 반대이니 한쪽은 틀린 의견이에요.',ARRAY['K4-2-u1-X21']::text[],false,'{"seq":4,"concept":"K4-2-u1-C24","difficulty":1,"kind":"ox","stem":"아침 독서 두 글은 의견이 반대이니 한쪽은 틀린 의견이에요.","answer":"X","reason_options":[{"t":"다른 의견은 틀린 의견이 아니고, 이유가 알맞은지 따져 보면 되기 때문에","correct":true},{"t":"한 문제의 정답 의견은 하나뿐이기 때문에","mis":"K4-2-u1-X21"}],"mis":"K4-2-u1-X21","explanation":["둘 다 이유가 있어요.","다른 것과 틀린 것은 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#5','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C28',1,'mc','auto','아침 독서 글 ㉯의 글쓴이의 의견은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X27']::text[],false,'{"seq":5,"concept":"K4-2-u1-C28","difficulty":1,"kind":"mc","stem":"아침 독서 글 ㉯의 글쓴이의 의견은 무엇인가요?","options":[{"t":"아침 독서 시간에는 글이 많은 책을, 만화책은 쉬는 시간에 읽자","correct":true},{"t":"아침 독서 시간에 무엇이든 읽어도 된다","mis":"K4-2-u1-X25"},{"t":"만화책을 아예 읽지 말자","mis":"K4-2-u1-X27"},{"t":"재미있는 장면에서 키득거리지 말자","mis":"K4-2-u1-X27"}],"explanation":["4번 줄을 봐요.","「그래서 저는 ~ 제안합니다」예요.","읽는 때를 나누자는 의견이에요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#6','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C32',1,'ox','auto','의견을 평가할 때는 글쓴이가 누구인지를 가장 먼저 따져요.',ARRAY['K4-2-u1-X30']::text[],false,'{"seq":6,"concept":"K4-2-u1-C32","difficulty":1,"kind":"ox","stem":"의견을 평가할 때는 글쓴이가 누구인지를 가장 먼저 따져요.","answer":"X","reason_options":[{"t":"문제에 알맞은가, 이유가 믿을 만한가, 다른 문제는 없는가를 따져야 하기 때문에","correct":true},{"t":"친한 친구가 쓴 의견이 더 알맞기 때문에","mis":"K4-2-u1-X30"}],"mis":"K4-2-u1-X30","explanation":["누가 썼는지가 아니에요.","세 가지 기준이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#7','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C42',1,'mc','auto','하율이의 글에 달 댓글로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X38']::text[],false,'{"seq":7,"concept":"K4-2-u1-C42","difficulty":1,"kind":"mc","stem":"하율이의 글에 달 댓글로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「저는 도하 님 생각에 찬성해요. 밤길이 어두우면 어린이와 어르신이 넘어지기 쉽기 때문이에요. 하율 님 동생이 잘 자지 못하는 것도 걱정돼요.」","correct":true},{"t":"「불 끄면 안 돼요!!!」","mis":"K4-2-u1-X38"},{"t":"「저도 그래요.」","mis":"K4-2-u1-X38"},{"t":"「하율 님은 자기 집만 생각하네요.」","mis":"K4-2-u1-X38"}],"explanation":["의견이 있나요?","이유가 있나요?","존중하는 말이 있나요?"],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#8','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C45',1,'mc','auto','끈을 매어 풀어지지 않게 하는 일을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u1-X42']::text[],false,'{"seq":8,"concept":"K4-2-u1-C45","difficulty":1,"kind":"mc","stem":"끈을 매어 풀어지지 않게 하는 일을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"묶다","correct":true},{"t":"묵다","mis":"K4-2-u1-X42"},{"t":"묷다","mis":"K4-2-u1-X42"},{"t":"뭇다","mis":"K4-2-u1-X42"}],"explanation":["받침이 쌍받침이에요.","ㄲ이에요.","‘묶다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#9','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C16',2,'ox','auto','말하거나 움직이는 사물이 나오지 않는 이야기는 모두 현실에서 일어날 수 있는 일이에요.',ARRAY['K4-2-u1-X05']::text[],false,'{"seq":9,"concept":"K4-2-u1-C16","difficulty":2,"kind":"ox","stem":"말하거나 움직이는 사물이 나오지 않는 이야기는 모두 현실에서 일어날 수 있는 일이에요.","answer":"X","reason_options":[{"t":"주소 없는 편지의 답장이나 하루 만에 열린 사과처럼 평범해 보여도 현실과 다른 일이 있기 때문에","correct":true},{"t":"꾸며 쓴 부분은 말하거나 움직이는 사물에만 있기 때문에","mis":"K4-2-u1-X05"}],"mis":"K4-2-u1-X05","explanation":["우체통 답장을 떠올려요.","사과나무도 떠올려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#10','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C17',2,'mc','auto','하루 만에 자란 사과나무처럼 꾸며 쓴 부분은 읽는 사람에게 무엇을 주나요?',ARRAY['K4-2-u1-X15','K4-2-u1-X01','K4-2-u1-X02']::text[],false,'{"seq":10,"concept":"K4-2-u1-C17","difficulty":2,"kind":"mc","stem":"하루 만에 자란 사과나무처럼 꾸며 쓴 부분은 읽는 사람에게 무엇을 주나요?","options":[{"t":"할머니를 위하는 마음이 얼마나 큰지 실감 나게 보여 주는 재미와 감동","correct":true},{"t":"공감만 주고 재미는 없다","mis":"K4-2-u1-X15"},{"t":"사과나무가 실제로 그렇게 자란다는 믿음","mis":"K4-2-u1-X01"},{"t":"이야기를 믿지 말라는 신호","mis":"K4-2-u1-X02"}],"explanation":["신기한 장면이에요.","마음이 커 보여요.","재미와 감동을 줘요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#11','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C6',2,'mc','auto','「할머니의 사과나무」를 읽고 내 경험을 떠올린 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X14','K4-2-u1-X04','K4-2-u1-X01']::text[],false,'{"seq":11,"concept":"K4-2-u1-C6","difficulty":2,"kind":"mc","stem":"「할머니의 사과나무」를 읽고 내 경험을 떠올린 말로 알맞은 것은 무엇인가요?","options":[{"t":"「나도 아픈 할아버지께 귤을 까 드린 적이 있어서 그 마음을 알 것 같아.」","correct":true},{"t":"「사과나무를 키워 본 적이 없으니 나와 상관없는 이야기야.」","mis":"K4-2-u1-X14"},{"t":"「이야기에 없는 할머니네 강아지 이야기를 지어 보자.」","mis":"K4-2-u1-X04"},{"t":"「이 이야기는 실제로 있었던 일이 분명해.」","mis":"K4-2-u1-X01"}],"explanation":["비슷한 일을 떠올려요.","똑같지 않아도 돼요.","그러면 마음이 보여요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#12','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C19',2,'mc','auto','「할머니의 사과나무」를 읽고 현실에서 할 수 있는 도움으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X45','K4-2-u1-X17']::text[],false,'{"seq":12,"concept":"K4-2-u1-C19","difficulty":2,"kind":"mc","stem":"「할머니의 사과나무」를 읽고 현실에서 할 수 있는 도움으로 알맞은 것은 무엇인가요?","options":[{"t":"몸이 불편한 이웃 어르신의 장바구니를 들어 드린다","correct":true},{"t":"하루 만에 자라는 사과 씨를 찾아 심어 드린다","mis":"K4-2-u1-X45"},{"t":"사과나무에게 열매를 빨리 맺어 달라고 부탁한다","mis":"K4-2-u1-X45"},{"t":"아픈 사람에게는 아무것도 하지 않는 게 낫다","mis":"K4-2-u1-X17"}],"explanation":["현실에서 할 수 있어야 해요.","꾸민 장치는 쓸 수 없어요.","장바구니는 들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#13','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C23',2,'mc','auto','아침 독서 두 글을 비교하며 읽은 친구가 얻은 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X20','K4-2-u1-X21']::text[],false,'{"seq":13,"concept":"K4-2-u1-C23","difficulty":2,"kind":"mc","stem":"아침 독서 두 글을 비교하며 읽은 친구가 얻은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"만화책의 좋은 점과 걱정되는 점을 함께 알게 되어 내 의견을 정하기 쉬워졌다","correct":true},{"t":"글 ㉯가 더 기니까 ㉯를 따르면 된다","mis":"K4-2-u1-X20"},{"t":"나와 같은 의견인 글만 읽고 다른 글은 넘겼다","mis":"K4-2-u1-X20"},{"t":"어느 글이 틀렸는지 알게 되었다","mis":"K4-2-u1-X21"}],"explanation":["두 글을 다 읽었어요.","좋은 점 · 걱정되는 점이에요.","내 의견을 정하기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#14','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C30',2,'mc','auto','어린이 신문에서 의견이 담긴 기사를 읽을 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u1-X29','K4-2-u1-X25','K4-2-u1-X27']::text[],false,'{"seq":14,"concept":"K4-2-u1-C30","difficulty":2,"kind":"mc","stem":"어린이 신문에서 의견이 담긴 기사를 읽을 때 알맞은 방법은 무엇인가요?","options":[{"t":"제목 → 끝부분 → 이유 차례로 글쓴이의 의견을 찾아본다","correct":true},{"t":"신문 기사에는 의견이 없으니 있었던 일만 읽는다","mis":"K4-2-u1-X29"},{"t":"제목만 보고 의견을 정한다","mis":"K4-2-u1-X25"},{"t":"가장 긴 문장을 의견으로 정한다","mis":"K4-2-u1-X27"}],"explanation":["기사에도 의견이 있어요.","차례를 지켜요.","제목 · 끝부분 · 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#15','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C36',2,'mc','auto','아침 독서 두 글을 공평하게 평가한 말은 무엇인가요?',ARRAY['K4-2-u1-X34','K4-2-u1-X22']::text[],false,'{"seq":15,"concept":"K4-2-u1-C36","difficulty":2,"kind":"mc","stem":"아침 독서 두 글을 공평하게 평가한 말은 무엇인가요?","options":[{"t":"㉮의 4번 줄은 믿기 어렵고, ㉯도 책을 멀리하는 친구가 생길 수 있는지 따져 봐야 한다","correct":true},{"t":"㉯는 지난주 경험을 들었으니 따질 것 없이 맞다","mis":"K4-2-u1-X34"},{"t":"㉮만 따지면 된다","mis":"K4-2-u1-X34"},{"t":"두 글 다 따지지 않고 마음에 드는 쪽을 고른다","mis":"K4-2-u1-X22"}],"explanation":["㉮를 따졌어요.","㉯도 따져요.","같은 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#16','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C41',2,'mc','auto','하율이와 도하에 대해 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X19','K4-2-u1-X18']::text[],false,'{"seq":16,"concept":"K4-2-u1-C41","difficulty":2,"kind":"mc","stem":"하율이와 도하에 대해 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 직접 겪은 일을 이유로 들었고, 걱정하는 사람이 다르다","correct":true},{"t":"도하는 하율이네 사정을 몰라서 반대했다","mis":"K4-2-u1-X28"},{"t":"하율이만 이유를 들었다","mis":"K4-2-u1-X19"},{"t":"두 사람은 서로 다른 정자 이야기를 했다","mis":"K4-2-u1-X18"}],"explanation":["하율이는 동생 잠을 걱정해요.","도하는 밤길을 걱정해요.","둘 다 겪은 일이에요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#17','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C16',3,'mc','auto','「골목 끝 빨간 우체통」의 답장과 콩 이야기의 저녁밥에서 함께 배울 수 있는 점은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X44']::text[],false,'{"seq":17,"concept":"K4-2-u1-C16","difficulty":3,"kind":"mc","stem":"「골목 끝 빨간 우체통」의 답장과 콩 이야기의 저녁밥에서 함께 배울 수 있는 점은 무엇인가요?","options":[{"t":"말하거나 움직이는 것이 없어도 현실의 규칙과 견주면 일어날 수 없는 일이 있다","correct":true},{"t":"신기해 보이지 않는 일은 모두 실제로 있었던 일이다","mis":"K4-2-u1-X05"},{"t":"두 이야기는 다 꾸민 것이라 현실과 견줄 필요가 없다","mis":"K4-2-u1-X06"},{"t":"편지와 콩은 현실에 없는 물건이다","mis":"K4-2-u1-X44"}],"explanation":["편지는 주소가 있어야 가요.","콩은 하루 만에 열리지 않아요.","평범해 보여도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#18','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C18',3,'error','auto','「골목 끝 빨간 우체통」의 전하려는 생각을 두고 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X17']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"error","stem":"「골목 끝 빨간 우체통」의 전하려는 생각을 두고 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「이사를 가면 친구를 사귀지 말아야 한다는 이야기야.」","correct":true,"mis_target":"K4-2-u1-X17"},{"t":"친구 가 — 「먼저 다가가면 같은 마음의 친구를 만날 수 있다는 이야기 같아.」","mis":"K4-2-u1-X17"},{"t":"친구 다 — 「쓸쓸한 마음은 나만 느끼는 게 아니라는 이야기 같아.」","mis":"K4-2-u1-X17"}],"explanation":["가와 다는 근거가 있어요.","나는 이야기와 거꾸로예요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#19','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C24',3,'ox','auto','다른 의견을 존중한다는 것은 친구 의견을 무조건 따른다는 뜻이에요.',ARRAY['K4-2-u1-X43']::text[],false,'{"seq":19,"concept":"K4-2-u1-C24","difficulty":3,"kind":"ox","stem":"다른 의견을 존중한다는 것은 친구 의견을 무조건 따른다는 뜻이에요.","answer":"X","reason_options":[{"t":"친구의 이유를 끝까지 듣고 나와 친구의 이유를 함께 따져 보는 것이기 때문에","correct":true},{"t":"다툼을 막으려면 내 의견을 버려야 하기 때문에","mis":"K4-2-u1-X43"}],"mis":"K4-2-u1-X43","explanation":["존중은 끝까지 듣는 거예요.","따르는 것과 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#20','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C28',3,'error','auto','글 ㉯의 의견을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K4-2-u1-X27','K4-2-u1-X19']::text[],false,'{"seq":20,"concept":"K4-2-u1-C28","difficulty":3,"kind":"error","stem":"글 ㉯의 의견을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 다 — 「1번 줄 ‘무엇을 읽든 책만 펴면 된다’가 글쓴이의 의견이야.」","correct":true,"mis_target":"K4-2-u1-X27"},{"t":"친구 가 — 「4번 줄 ‘제안합니다’에서 의견을 확인했어.」","mis":"K4-2-u1-X27"},{"t":"친구 나 — 「2·3번 줄이 그 의견을 받쳐 주는 이유야.」","mis":"K4-2-u1-X19"}],"explanation":["1번 줄은 남들이 할 수 있는 생각이에요.","글쓴이는 「그런데」로 뒤집었어요.","친구 다가 잘못 찾았어요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#21','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C38',3,'error','auto','친구가 쓴 아침 독서 의견 글을 읽고 한마디씩 했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X36']::text[],false,'{"seq":21,"concept":"K4-2-u1-C38","difficulty":3,"kind":"error","stem":"친구가 쓴 아침 독서 의견 글을 읽고 한마디씩 했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 가 — 「나는 만화책이 싫으니까 네 의견은 틀렸어.」","correct":true,"mis_target":"K4-2-u1-X36"},{"t":"친구 나 — 「네 의견대로 하면 키득거리는 소리는 어떻게 할지 궁금해.」","mis":"K4-2-u1-X36"},{"t":"친구 다 — 「의견은 나와 다르지만 첫째 이유는 경험이라 믿음이 가.」","mis":"K4-2-u1-X36"}],"explanation":["의견이 달라도 존중해요.","이유를 중심으로 말해요.","친구 가가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#22','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C3',3,'ox','auto','「할머니의 사과나무」에서 하루 만에 자란 나무는 이야기를 망치는 잘못된 부분이에요.',ARRAY['K4-2-u1-X02']::text[],false,'{"seq":22,"concept":"K4-2-u1-C3","difficulty":3,"kind":"ox","stem":"「할머니의 사과나무」에서 하루 만에 자란 나무는 이야기를 망치는 잘못된 부분이에요.","answer":"X","reason_options":[{"t":"할머니를 위하는 마음이 얼마나 큰지 실감 나게 보여 주는 꾸며 쓴 부분이기 때문에","correct":true},{"t":"이야기에는 현실에서 일어나는 일만 써야 하기 때문에","mis":"K4-2-u1-X02"}],"mis":"K4-2-u1-X02","explanation":["꾸민 부분에는 까닭이 있어요.","마음이 커 보여요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#23','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C41',4,'mc','auto','하율이와 도하의 의견을 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X28','K4-2-u1-X21','K4-2-u1-X22']::text[],false,'{"seq":23,"concept":"K4-2-u1-C41","difficulty":4,"kind":"mc","stem":"하율이와 도하의 의견을 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 겪은 일을 이유로 들었다. 하율이 의견대로만 하면 밤길이 어두워지고, 도하 의견대로만 하면 동생의 잠 문제가 남는다","correct":true},{"t":"도하는 하율이네 사정을 몰라서 반대했으니 하율이가 맞다","mis":"K4-2-u1-X28"},{"t":"먼저 글을 쓴 하율이의 의견을 따라야 한다","mis":"K4-2-u1-X21"},{"t":"두 사람 다 맞으니 따질 필요가 없다","mis":"K4-2-u1-X22"}],"explanation":["둘 다 겪은 일이에요.","한쪽대로만 하면요?","다른 쪽 걱정이 남아요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#24','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C32',4,'essay','teacher','아침 독서 두 글 가운데 하나를 골라 세 가지 기준(문제에 알맞은가 · 이유가 믿을 만한가 · 다른 문제는 없는가)으로 평가해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C32","difficulty":4,"kind":"essay","stem":"아침 독서 두 글 가운데 하나를 골라 세 가지 기준(문제에 알맞은가 · 이유가 믿을 만한가 · 다른 문제는 없는가)으로 평가해 쓰세요.","answer_guide":{"answer":"예: 글 ㉮를 평가하면, 아침 독서 시간에 무엇을 읽을지라는 문제에 알맞은 의견이다. 짝이 만화책을 끝까지 읽은 경험은 믿을 만하지만, 모두가 받아쓰기에서 백 점을 받는다는 이유는 뒷받침할 까닭이 없어 믿기 어렵다. 또 ㉮대로 하면 그림만 넘기다 시간이 끝나거나 옆 친구가 집중하기 어려울 수 있다.","scoring_points":["글을 하나 골랐는가","세 가지 기준으로 하나씩 따졌는가","믿기 어려운 이유나 생길 문제를 찾았는가"]},"explanation":["문제를 봐요.","이유를 봐요.","생길 문제를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_c#25','kor',4,2,'u1','','g4_2_kor_u1_review_c','unit_review','K4-2-u1-C24',4,'essay','teacher','친구와 의견이 다를 때 어떻게 하면 좋을지 쓰세요. 「한쪽은 틀렸다」와 「다 맞으니 따질 필요 없다」가 왜 알맞지 않은지도 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C24","difficulty":4,"kind":"essay","stem":"친구와 의견이 다를 때 어떻게 하면 좋을지 쓰세요. 「한쪽은 틀렸다」와 「다 맞으니 따질 필요 없다」가 왜 알맞지 않은지도 함께 쓰세요.","answer_guide":{"answer":"예: 친구의 이유를 끝까지 듣고, 나와 친구의 이유가 믿을 만한지 함께 따져 보아야 한다. 의견이 다르다고 한쪽이 틀린 것은 아니므로 「한쪽은 틀렸다」는 알맞지 않다. 하지만 다 맞다고 따지지 않으면 더 알맞은 의견을 찾을 수 없으므로 「따질 필요 없다」도 알맞지 않다.","scoring_points":["어떻게 하면 좋을지 썼는가","「한쪽은 틀렸다」가 알맞지 않은 까닭을 썼는가","「따질 필요 없다」가 알맞지 않은 까닭을 썼는가"]},"explanation":["끝까지 들어요.","틀린 것이 아니에요.","그래도 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#1','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C2',1,'mc','auto','작품 속 세계에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X01','K4-2-u1-X06','K4-2-u1-X05']::text[],false,'{"seq":1,"concept":"K4-2-u1-C2","difficulty":1,"kind":"mc","stem":"작품 속 세계에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"현실과 비슷한 부분과 꾸며 쓴 부분이 함께 있다","correct":true},{"t":"언제나 현실과 똑같다","mis":"K4-2-u1-X01"},{"t":"다 꾸민 것이라 현실과 견줄 것이 없다","mis":"K4-2-u1-X06"},{"t":"말하는 사물이 나오는 곳만 현실과 다르다","mis":"K4-2-u1-X05"}],"explanation":["닮은 부분이 있어요.","꾸민 부분도 있어요.","둘이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#2','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C5',1,'mc','auto','인상 깊은 장면을 말할 때 함께 말해야 할 것은 무엇인가요?',ARRAY['K4-2-u1-X04','K4-2-u1-X03']::text[],false,'{"seq":2,"concept":"K4-2-u1-C5","difficulty":1,"kind":"mc","stem":"인상 깊은 장면을 말할 때 함께 말해야 할 것은 무엇인가요?","options":[{"t":"왜 그 장면이 마음에 남았는지 까닭","correct":true},{"t":"작품에 매긴 점수","mis":"K4-2-u1-X04"},{"t":"이야기에 없는 다음 장면","mis":"K4-2-u1-X04"},{"t":"친구가 고른 장면","mis":"K4-2-u1-X03"}],"explanation":["장면만으로는 모자라요.","왜 그 장면인지 말해요.","까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#3','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C13',1,'mc','auto','「전에 겪어 보지 않아 익숙하지 않다」를 뜻하는 낱말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":3,"concept":"K4-2-u1-C13","difficulty":1,"kind":"mc","stem":"「전에 겪어 보지 않아 익숙하지 않다」를 뜻하는 낱말은 무엇인가요?","options":[{"t":"낯설다","correct":true},{"t":"머뭇거리다","mis":"K4-2-u1-X12"},{"t":"서성이다","mis":"K4-2-u1-X12"},{"t":"반갑다","mis":"K4-2-u1-X12"}],"explanation":["새 동네가 그랬어요.","익숙하지 않아요.","‘낯설다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#4','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C24',1,'mc','auto','의견이 반대인 두 글을 읽고 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X22','K4-2-u1-X21','K4-2-u1-X30']::text[],false,'{"seq":4,"concept":"K4-2-u1-C24","difficulty":1,"kind":"mc","stem":"의견이 반대인 두 글을 읽고 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"어느 쪽 이유가 의견을 잘 받쳐 주는지 따져 본다","correct":true},{"t":"두 글 다 맞으니 그냥 둔다","mis":"K4-2-u1-X22"},{"t":"먼저 읽은 글을 따른다","mis":"K4-2-u1-X21"},{"t":"친한 친구가 쓴 글을 고른다","mis":"K4-2-u1-X30"}],"explanation":["그냥 두지 않아요.","먼저 · 친한 친구로 정하지 않아요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#5','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C26',1,'mc','auto','「책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.」는 글 ㉮에서 무엇인가요?',ARRAY['K4-2-u1-X24','K4-2-u1-X25','K4-2-u1-X19']::text[],false,'{"seq":5,"concept":"K4-2-u1-C26","difficulty":1,"kind":"mc","stem":"「책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.」는 글 ㉮에서 무엇인가요?","options":[{"t":"의견을 받쳐 주는 이유","correct":true},{"t":"글쓴이의 의견","mis":"K4-2-u1-X24"},{"t":"글의 제목","mis":"K4-2-u1-X25"},{"t":"다른 글쓴이의 이유","mis":"K4-2-u1-X19"}],"explanation":["「첫째」로 시작해요.","의견의 까닭이에요.","이유예요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#6','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C31',1,'blank','auto','「모둠 친구들의 의견을 (　) 듣고 정했다.」의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K4-2-u1-X12']::text[],false,'{"seq":6,"concept":"K4-2-u1-C31","difficulty":1,"kind":"blank","stem":"「모둠 친구들의 의견을 (　) 듣고 정했다.」의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"두루","correct":true},{"t":"배려","mis":"K4-2-u1-X12"},{"t":"제안","mis":"K4-2-u1-X12"},{"t":"혼자","mis":"K4-2-u1-X12"}],"explanation":["빠짐없이 골고루 들었어요.","한 명도 빼지 않았어요.","‘두루’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#7','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C39',1,'ox','auto','작품을 소개할 때는 줄거리를 처음부터 끝까지 빠짐없이 옮기는 것이 가장 좋아요.',ARRAY['K4-2-u1-X37']::text[],false,'{"seq":7,"concept":"K4-2-u1-C39","difficulty":1,"kind":"ox","stem":"작품을 소개할 때는 줄거리를 처음부터 끝까지 빠짐없이 옮기는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"현실과 견준 생각과 꾸민 부분이 준 재미나 깨달음을 담아야 듣는 친구가 작품을 새롭게 볼 수 있기 때문에","correct":true},{"t":"줄거리를 다 말해야 작품을 소개한 것이기 때문에","mis":"K4-2-u1-X37"}],"mis":"K4-2-u1-X37","explanation":["줄거리는 짧게 해요.","현실과 견준 생각을 담아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#8','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C44',1,'mc','auto','「모이다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?',ARRAY['K4-2-u1-X41']::text[],false,'{"seq":8,"concept":"K4-2-u1-C44","difficulty":1,"kind":"mc","stem":"「모이다」에 「-(으)ㅁ」을 붙여 바꾼 낱말은 무엇인가요?","options":[{"t":"모임","correct":true},{"t":"모이음","mis":"K4-2-u1-X41"},{"t":"모이믐","mis":"K4-2-u1-X41"},{"t":"모음임","mis":"K4-2-u1-X41"}],"explanation":["받침이 없어요.","ㅁ만 붙어요.","‘모임’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#9','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C16',2,'mc','auto','평범해 보이는 일이 현실과 다른지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06']::text[],false,'{"seq":9,"concept":"K4-2-u1-C16","difficulty":2,"kind":"mc","stem":"평범해 보이는 일이 현실과 다른지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"내 경험이나 현실의 규칙과 견주어 본다","correct":true},{"t":"말하는 사물이 나오는지만 본다","mis":"K4-2-u1-X05"},{"t":"신기해 보이지 않으면 현실이라고 정한다","mis":"K4-2-u1-X05"},{"t":"이야기는 다 꾸민 것이니 따지지 않는다","mis":"K4-2-u1-X06"}],"explanation":["주소가 없으면 편지가 갈까요?","씨가 하루 만에 자랄까요?","현실과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#10','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C18',2,'error','auto','「할머니의 사과나무」의 전하려는 생각을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X16','K4-2-u1-X17']::text[],false,'{"seq":10,"concept":"K4-2-u1-C18","difficulty":2,"kind":"error","stem":"「할머니의 사과나무」의 전하려는 생각을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「사과 씨는 아침에 심어야 빨리 자란다는 이야기야.」","correct":true,"mis_target":"K4-2-u1-X16"},{"t":"친구 가 — 「아픈 사람 곁에 함께 있어 주는 게 큰 힘이 된다는 이야기 같아.」","mis":"K4-2-u1-X17"},{"t":"친구 나 — 「좋아하는 것을 나누면 더 즐겁다는 이야기 같아.」","mis":"K4-2-u1-X17"}],"explanation":["가와 나는 근거가 있어요.","다는 꾸민 장치를 믿었어요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["1 할머니는 요즘 무릎이 아프셔서 마당에 잘 나오지 않으신다.","2 나는 할머니가 좋아하시는 사과를 드리고 싶어 아침에 마당에 사과 씨를 심었다.","3 학교에 다녀오니 씨를 심은 자리에 내 키만 한 나무가 서 있고, 빨간 사과가 열려 있었다.","4 나는 사과 하나를 따서 할머니 방으로 가져다 드렸다.","5 할머니는 사과를 반으로 갈라 내 손에 쥐여 주셨다. 「같이 먹으니 더 달구나.」","6 할머니가 오랜만에 소리 내어 웃으셨다."],"title":"이야기 「할머니의 사과나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#11','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C6',2,'ox','auto','내 경험을 떠올리며 읽으면 작품에서 현실과 닮은 부분과 다른 부분을 찾기 쉬워요.',ARRAY['K4-2-u1-X01']::text[],false,'{"seq":11,"concept":"K4-2-u1-C6","difficulty":2,"kind":"ox","stem":"내 경험을 떠올리며 읽으면 작품에서 현실과 닮은 부분과 다른 부분을 찾기 쉬워요.","answer":"O","reason_options":[{"t":"내가 겪은 일과 견주면 닮은 점과 다른 점이 잘 보이기 때문에","correct":true},{"t":"작품은 내 경험과 똑같이 쓰여 있기 때문에","mis":"K4-2-u1-X01"}],"mis":"K4-2-u1-X01","explanation":["초록불에 뛴 적을 떠올려요.","시와 견주어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#12','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C14',2,'mc','auto','은호의 처음 모습만 보고 「말이 없는 아이」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X13']::text[],false,'{"seq":12,"concept":"K4-2-u1-C14","difficulty":2,"kind":"mc","stem":"은호의 처음 모습만 보고 「말이 없는 아이」라고 한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「끝에 용기를 내어 먼저 말을 건 모습도 함께 봐야 해.」","correct":true},{"t":"「맞아. 첫 장면이 그 인물의 전부야.」","mis":"K4-2-u1-X13"},{"t":"「성격은 이름을 보면 알 수 있어.」","mis":"K4-2-u1-X13"},{"t":"「인물의 성격은 짐작하지 않아도 돼.」","mis":"K4-2-u1-X13"}],"explanation":["처음엔 창밖만 보았어요.","끝엔 먼저 말을 걸었어요.","함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#13','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C25',2,'mc','auto','아침 독서 두 글을 읽고 새로운 의견을 낸 것은 무엇인가요?',ARRAY['K4-2-u1-X23']::text[],false,'{"seq":13,"concept":"K4-2-u1-C25","difficulty":2,"kind":"mc","stem":"아침 독서 두 글을 읽고 새로운 의견을 낸 것은 무엇인가요?","options":[{"t":"한 주에 하루를 「만화책 읽는 날」로 정하자","correct":true},{"t":"아침 독서 시간에 만화책도 읽게 하자","mis":"K4-2-u1-X23"},{"t":"아침 독서 시간에는 글이 많은 책만 읽자","mis":"K4-2-u1-X23"},{"t":"두 글 가운데 하나만 골라야 한다","mis":"K4-2-u1-X23"}],"explanation":["두 글에 없던 생각이에요.","하나를 고르지 않았어요.","새 의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#14','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C27',2,'ox','auto','제목에 물음표가 있으면 그 글에는 글쓴이의 의견이 없어요.',ARRAY['K4-2-u1-X25']::text[],false,'{"seq":14,"concept":"K4-2-u1-C27","difficulty":2,"kind":"ox","stem":"제목에 물음표가 있으면 그 글에는 글쓴이의 의견이 없어요.","answer":"X","reason_options":[{"t":"물음 제목 글도 끝부분에서 글쓴이의 대답, 곧 의견을 밝히기 때문에","correct":true},{"t":"의견은 제목에만 나타나기 때문에","mis":"K4-2-u1-X25"}],"mis":"K4-2-u1-X25","explanation":["스티커 글 ㉯를 떠올려요.","끝에 의견이 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#15','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C34',2,'mc','auto','글 ㉮의 의견대로 하면 생길 수 있는 다른 문제는 무엇인가요?',ARRAY['K4-2-u1-X32','K4-2-u1-X34']::text[],false,'{"seq":15,"concept":"K4-2-u1-C34","difficulty":2,"kind":"mc","stem":"글 ㉮의 의견대로 하면 생길 수 있는 다른 문제는 무엇인가요?","options":[{"t":"그림만 넘기다 시간이 끝나거나 키득거리는 소리로 옆 친구가 집중하기 어려울 수 있다","correct":true},{"t":"만화책을 좋아하는 친구가 더 많아진다","mis":"K4-2-u1-X32"},{"t":"받아쓰기 시험이 없어진다","mis":"K4-2-u1-X32"},{"t":"글 ㉯의 걱정은 글 ㉮와 상관없다","mis":"K4-2-u1-X34"}],"explanation":["글 ㉯가 걱정한 일이에요.","누가 어려움을 겪을까요?","옆 친구예요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#16','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C41',2,'ox','auto','하율이와 도하 가운데 한 사람은 정자 불을 잘못 보고 있어요.',ARRAY['K4-2-u1-X28']::text[],false,'{"seq":16,"concept":"K4-2-u1-C41","difficulty":2,"kind":"ox","stem":"하율이와 도하 가운데 한 사람은 정자 불을 잘못 보고 있어요.","answer":"X","reason_options":[{"t":"하율이는 잠을, 도하는 밤길 안전을 걱정해 같은 불을 다르게 본 것이기 때문에","correct":true},{"t":"같은 불을 두고 생각이 다르면 한쪽이 잘못 본 것이기 때문에","mis":"K4-2-u1-X28"}],"mis":"K4-2-u1-X28","explanation":["같은 불이에요.","걱정하는 것이 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#17','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C8',3,'mc','auto','작품 속 세계에 대한 생각 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X05','K4-2-u1-X06','K4-2-u1-X02']::text[],false,'{"seq":17,"concept":"K4-2-u1-C8","difficulty":3,"kind":"mc","stem":"작품 속 세계에 대한 생각 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"현실과 닮은 부분도, 꾸며 쓴 부분도 모두 글쓴이가 전하려는 생각에 맞게 골라 엮은 것이다","correct":true},{"t":"신기한 장면만 꾸민 것이고 나머지는 실제 일이다","mis":"K4-2-u1-X05"},{"t":"모두 꾸민 것이라 현실과 상관없다","mis":"K4-2-u1-X06"},{"t":"현실과 다른 곳은 글쓴이의 실수다","mis":"K4-2-u1-X02"}],"explanation":["닮은 부분도 골라 쓴 거예요.","꾸민 부분도 까닭이 있어요.","글쓴이가 엮은 세계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#18','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C18',3,'ox','auto','그림자 우체통이나 하루 만에 자란 나무처럼 꾸민 장치를 그대로 믿는 생각도 글쓴이가 전하려는 생각이 될 수 있어요.',ARRAY['K4-2-u1-X16']::text[],false,'{"seq":18,"concept":"K4-2-u1-C18","difficulty":3,"kind":"ox","stem":"그림자 우체통이나 하루 만에 자란 나무처럼 꾸민 장치를 그대로 믿는 생각도 글쓴이가 전하려는 생각이 될 수 있어요.","answer":"X","reason_options":[{"t":"꾸민 장치는 생각을 전하는 방법일 뿐, 전하려는 생각은 인물의 마음과 일에서 찾아야 하기 때문에","correct":true},{"t":"이야기에 나온 일이면 무엇이든 전하려는 생각이기 때문에","mis":"K4-2-u1-X16"}],"mis":"K4-2-u1-X16","explanation":["장치는 방법이에요.","생각은 마음에서 찾아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#19','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C35',3,'error','auto','아침 독서 두 글을 평가했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u1-X33','K4-2-u1-X31']::text[],false,'{"seq":19,"concept":"K4-2-u1-C35","difficulty":3,"kind":"error","stem":"아침 독서 두 글을 평가했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉯는 이유가 둘뿐이니까 틀린 의견이야.」","correct":true,"mis_target":"K4-2-u1-X33"},{"t":"친구 가 — 「㉯의 2번 줄은 지난주 경험이라 믿음이 가.」","mis":"K4-2-u1-X31"},{"t":"친구 다 — 「㉮의 4번 줄은 뒷받침할 까닭이 없어.」","mis":"K4-2-u1-X31"}],"explanation":["개수로 틀렸다고 했어요.","이유의 힘을 봐야 해요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#20','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C27',3,'ox','auto','글 ㉮처럼 의견이 드러난 제목이어도 글 끝부분에서 의견을 확인해야 해요.',ARRAY['K4-2-u1-X25']::text[],false,'{"seq":20,"concept":"K4-2-u1-C27","difficulty":3,"kind":"ox","stem":"글 ㉮처럼 의견이 드러난 제목이어도 글 끝부분에서 의견을 확인해야 해요.","answer":"O","reason_options":[{"t":"제목은 짐작하는 실마리이고 의견은 글 끝에서 확인하는 차례를 지켜야 하기 때문에","correct":true},{"t":"의견이 드러난 제목이면 글은 읽지 않아도 되기 때문에","mis":"K4-2-u1-X25"}],"mis":"K4-2-u1-X25","explanation":["제목은 실마리예요.","끝에서 확인해요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 우리 반은 아침 독서 시간에 만화책을 읽지 못하게 되어 있습니다.","2 첫째, 책 읽기를 싫어하던 제 짝도 만화책은 끝까지 읽었습니다.","3 둘째, 만화책은 그림과 글을 함께 따라가며 이야기의 흐름을 익힐 수 있습니다.","4 셋째, 만화책을 읽으면 우리 반 모두가 받아쓰기에서 백 점을 받을 것입니다.","5 그러므로 아침 독서 시간에 만화책도 읽게 해야 합니다."],"title":"글 ㉮ 「아침 독서 시간에 만화책도 읽게 해 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#21','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C37',3,'mc','auto','두 글을 평가한 뒤 내 의견을 정한 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u1-X23','K4-2-u1-X35','K4-2-u1-X22']::text[],false,'{"seq":21,"concept":"K4-2-u1-C37","difficulty":3,"kind":"mc","stem":"두 글을 평가한 뒤 내 의견을 정한 말로 알맞은 것은 무엇인가요?","options":[{"t":"「나는 두 글과 달리, 만화책은 읽고 나서 느낀 점을 한 줄 쓰는 날에만 읽자고 생각해. 그림만 넘기는 일이 줄기 때문이야.」","correct":true},{"t":"「두 글 가운데 하나를 꼭 골라야 하니 ㉮로 할래.」","mis":"K4-2-u1-X23"},{"t":"「둘을 반씩 섞었으니 내 의견이 제일 좋아.」","mis":"K4-2-u1-X35"},{"t":"「이유는 모르겠지만 ㉯가 마음에 들어.」","mis":"K4-2-u1-X22"}],"explanation":["새 의견이어도 돼요.","이유가 있어야 해요.","섞었다고 저절로 좋진 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#22','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C11',3,'mc','auto','작품 속 세계와 현실을 비교하는 까닭을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u1-X10','K4-2-u1-X01','K4-2-u1-X02']::text[],false,'{"seq":22,"concept":"K4-2-u1-C11","difficulty":3,"kind":"mc","stem":"작품 속 세계와 현실을 비교하는 까닭을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"현실을 되돌아보고, 다른 세계를 상상하고, 익숙한 것을 새 눈으로 보기 위해서","correct":true},{"t":"작품의 틀린 곳을 찾아 고치기 위해서","mis":"K4-2-u1-X10"},{"t":"현실과 같은 작품만 골라 읽기 위해서","mis":"K4-2-u1-X01"},{"t":"꾸며 쓴 부분이 거짓말임을 밝히기 위해서","mis":"K4-2-u1-X02"}],"explanation":["되돌아보기예요.","상상하기예요.","새 눈으로 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#23','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C27',4,'mc','auto','글 ㉯를 읽고 의견을 가장 바르게 파악한 친구의 말은 무엇인가요?',ARRAY['K4-2-u1-X25','K4-2-u1-X27','K4-2-u1-X26']::text[],false,'{"seq":23,"concept":"K4-2-u1-C27","difficulty":4,"kind":"mc","stem":"글 ㉯를 읽고 의견을 가장 바르게 파악한 친구의 말은 무엇인가요?","options":[{"t":"「제목만 보고 무엇이든 괜찮다는 글인 줄 알았는데, 4번 줄에서 아침에는 글이 많은 책을 읽자는 의견을 확인했어. 이유는 2·3번 줄이야.」","correct":true},{"t":"「제목에 ‘괜찮을까요’가 있으니 무엇이든 괜찮다는 글이야.」","mis":"K4-2-u1-X25"},{"t":"「1번 줄이 맨 앞에 있으니까 그게 의견이야.」","mis":"K4-2-u1-X27"},{"t":"「제목은 헷갈려서 처음부터 안 봤어.」","mis":"K4-2-u1-X26"}],"explanation":["제목으로 짐작했어요.","끝 줄에서 확인했어요.","이유도 찾았어요."],"asset":{"type":"passage","lines":["1 아침 독서 시간에 무엇을 읽든 책만 펴면 된다고 생각할 수도 있습니다.","2 그런데 지난주 만화책을 본 친구들은 그림만 넘기다 몇 권을 금방 다 보았다고 했습니다.","3 또 재미있는 장면이 나오면 키득거리는 소리가 나서 옆 친구가 집중하기 어려웠습니다.","4 그래서 저는 아침 독서 시간에는 글이 많은 책을 읽고, 만화책은 쉬는 시간에 읽자고 제안합니다."],"title":"글 ㉯ 「아침 독서 시간, 무엇이든 괜찮을까요?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#24','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C42',4,'essay','teacher','하율이의 게시글에 달 내 댓글을 쓰세요. 의견과 이유가 드러나고 두 사람을 존중하는 말이 들어가게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u1-C42","difficulty":4,"kind":"essay","stem":"하율이의 게시글에 달 내 댓글을 쓰세요. 의견과 이유가 드러나고 두 사람을 존중하는 말이 들어가게 쓰세요.","answer_guide":{"answer":"예: 저는 밤 아홉 시가 지나면 정자 불을 끄되, 정자 옆길에는 발밑을 비추는 낮은 등을 두면 좋겠다고 생각해요. 길은 밝고 창으로 들어가는 빛은 줄기 때문이에요. 동생이 잘 자기를 바라는 하율 님 마음도, 밤길이 걱정되는 도하 님 마음도 모두 이해해요.","scoring_points":["의견을 썼는가","의견을 받쳐 주는 이유를 썼는가","두 사람을 존중하는 말을 썼는가"]},"explanation":["내 의견을 써요.","이유를 붙여요.","존중하는 말을 더해요."],"asset":{"type":"passage","lines":["하율 — 저는 쉼터 정자 바로 옆 집에 사는 4학년입니다.","정자 불이 밤새 켜져 있어 창으로 빛이 들어와 동생이 깊이 잠들지 못합니다.","밤 아홉 시가 지나면 정자 불을 꺼 주세요.","댓글 도하 — 저는 생각이 달라요. 학원이 끝나면 정자 옆길로 오는데,","불이 꺼진 날 길이 어두워 넘어질 뻔했어요. 정자 불은 켜 두어야 한다고 생각해요."],"title":"동네 소식판 「밤에는 정자 불을 꺼 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u1_review_d#25','kor',4,2,'u1','','g4_2_kor_u1_review_d','unit_review','K4-2-u1-C1',4,'essay','teacher','이 단원에서 배운 것 가운데 앞으로 이야기를 읽을 때 쓸 것과 의견이 담긴 글을 읽을 때 쓸 것을 하나씩 쓰고, 각각 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u1-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것 가운데 앞으로 이야기를 읽을 때 쓸 것과 의견이 담긴 글을 읽을 때 쓸 것을 하나씩 쓰고, 각각 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 이야기를 읽을 때는 말하는 것만이 아니라 평범해 보이는 일도 내 경험과 견주어 현실과 다른지 살펴보겠다. 의견이 담긴 글을 읽을 때는 제목으로 짐작한 뒤 끝부분에서 의견을 확인하고, 이유가 많은지가 아니라 믿을 만한지를 따져 보겠다.","scoring_points":["이야기를 읽을 때 쓸 것을 썼는가","의견 글을 읽을 때 쓸 것을 썼는가","각각 어떻게 쓸지 구체적으로 썼는가"]},"explanation":["작품과 현실이에요.","서로 다른 의견이에요.","어떻게 쓸지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
